INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-CONST-001', 'Preamble-A', 'Sovereignty and Independence: Lebanon is a sovereign, free, and independent homeland. An ultimate homeland for all its sons; unitary in terms of land, people, and institutions, within its boundaries; as provided in this Constitution, and as recognized internationally.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article Preamble-A', 'Sovereignty and Independence', 'Constitutional Law'),
  ('LB-CONST-001', 'Preamble-B', 'Arab Identity: Lebanon has an Arab identity and belonging. It is a founding active member of the Arab League, committed to its Charter; as it is a founding active member of the United Nations Organization, committed to its Charter and the Universal Declaration of Human Rights. The State embodies these principles in all sectors and scopes without exception.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article Preamble-B', 'Arab Identity', 'Constitutional Law'),
  ('LB-CONST-001', 'Preamble-C', 'Democratic Republic: Lebanon is a democratic parliamentary republic based upon the respect of public freedoms, freedom of opinion and freedom of belief; and of social justice and equality in rights and duties among all citizens, without distinction or preference.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article Preamble-C', 'Democratic Republic', 'Constitutional Law'),
  ('LB-CONST-001', 'Preamble-D', 'Popular Sovereignty: The people are the source of powers and of sovereignty, exercising them through constitutional institutions.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article Preamble-D', 'Popular Sovereignty', 'Constitutional Law'),
  ('LB-CONST-001', 'Preamble-E', 'Separation of Powers: The system is based upon the principle of separation of powers, their balance, and their cooperation.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article Preamble-E', 'Separation of Powers', 'Constitutional Law'),
  ('LB-CONST-001', 'Preamble-F', 'Economic Freedom: The economic system is free, guaranteeing individual initiative and private ownership.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article Preamble-F', 'Economic Freedom', 'Constitutional Law'),
  ('LB-CONST-001', 'Preamble-G', 'Balanced Development: Balanced development of regions, culturally, socially, and economically, is a cornerstone of the State unity and the system stability.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article Preamble-G', 'Balanced Development', 'Constitutional Law'),
  ('LB-CONST-001', 'Preamble-H', 'Political Sectarianism: Eliminating political sectarianism is a basic national objective, to be achieved according to a transitional plan.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article Preamble-H', 'Political Sectarianism', 'Constitutional Law'),
  ('LB-CONST-001', 'Preamble-I', 'Territorial Unity: The territory of Lebanon is one for all Lebanese. Every Lebanese has the right to reside on any part thereof, and enjoy it under the sovereignty of the law. No segregation of the people on any belonging whatsoever. No segregation, no partition, and no inhabitation.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article Preamble-I', 'Territorial Unity', 'Constitutional Law'),
  ('LB-CONST-001', 'Preamble-J', 'Legitimacy of Authority: There is no legitimacy to any authority contradicting the charter of co-existence.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article Preamble-J', 'Legitimacy of Authority', 'Constitutional Law'),
  ('LB-CONST-001', '1', 'State Territory: Lebanon is an independent state, with indivisible unity, and complete sovereignty. Its boundaries are the same defining it currently. North: From the mouth of Al-Nahr Al-Kabir along a line following the course of the River to the point of its confluence with Wadi Khalid, its tributary, at the height of Jisr Al-Kamar. East: The summit line separating Wadi Khalid from Wadi Al-Assi River (Oronte), crossing the villages of Muaissara, Harbata, Heit, Abish, Fissan at the height of the two villages of Brina and Matriba. This line follows the boundaries of Northern Baalbeck from the northeasterly side and the southeasterly side, then the boundaries of Baalbeck, Al-Bikaa, Hassbiya, and Eastern Rashiya. South: The current southern boundaries of Sour and Marjayoun. West: The Mediterranean Sea.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 1', 'State Territory', 'Constitutional Law'),
  ('LB-CONST-001', '2', 'Inalienability of Territory: No part of the Lebanese territory may be alienated or ceded.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 2', 'Inalienability of Territory', 'Constitutional Law'),
  ('LB-CONST-001', '3', 'Administrative Boundaries: The boundaries of administrative areas may not be altered except according to a law.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 3', 'Administrative Boundaries', 'Constitutional Law'),
  ('LB-CONST-001', '4', 'Form of Government: The Grand Lebanon is a Republic, whose capital is Beirut.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 4', 'Form of Government', 'Constitutional Law'),
  ('LB-CONST-001', '5', 'National Flag: The Lebanese flag is comprised of red, white, and red horizontal stripes. The cedar in green occupies the center of the white stripe. The size of the white stripe is equivalent to the size of both the red stripes. The cedar is in the center, with its apex touching the red upper stripe, and its base touching the red lower stripe. The size of the cedar is equivalent to a third of the size of the white stripe.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 5', 'National Flag', 'Constitutional Law'),
  ('LB-CONST-001', '6', 'Lebanese Nationality: The Lebanese nationality and the manner in which it is acquired, retained and lost, shall be determined according to the law.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 6', 'Lebanese Nationality', 'Constitutional Law'),
  ('LB-CONST-001', '7', 'Equality Before the Law: All Lebanese are equal before the law. They equally enjoy civil and political rights, and assume obligations and public duties without any distinction among them.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 7', 'Equality Before the Law', 'Constitutional Law'),
  ('LB-CONST-001', '8', 'Personal Freedom: Personal freedom is guaranteed and protected by the law. No one can be arrested, jailed or suspended except according to the rules of the law. No offense can be determined and no penalty can be imposed except according to the law.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 8', 'Personal Freedom', 'Constitutional Law'),
  ('LB-CONST-001', '9', 'Freedom of Conscience and Religion: Freedom of conscience is absolute. In assuming the obligations of glorifying God, the Most High, the State respects all religions and creeds and safeguards the freedom of exercising the religious rites under its protection, without disturbing the public order. It also guarantees the respect of the system of personal status and religious interests of the people, regardless of their different creeds.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 9', 'Freedom of Conscience and Religion', 'Constitutional Law'),
  ('LB-CONST-001', '10', 'Freedom of Education: Education is free so long as it does not disturb the public order, does not violate the morals, and does not touch the dignity of any religion or creed. The rights of communities to establish their own private schools cannot be violated, provided that they comply with the general requirements laid down by the State with respect to public education.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 10', 'Freedom of Education', 'Constitutional Law'),
  ('LB-CONST-001', '11', 'Official Language: The Arabic language is the official national language. The conditions under which the French language is to be used are determined by law.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 11', 'Official Language', 'Constitutional Law'),
  ('LB-CONST-001', '12', 'Right to Public Employment: Every Lebanese has the right to public employment, without any distinction, except on qualification and merit according to the conditions laid down by the law. A special code shall be established to safeguard the rights of employees in the areas to which they belong.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 12', 'Right to Public Employment', 'Constitutional Law'),
  ('LB-CONST-001', '13', 'Freedom of Opinion and Press: The freedom of opinion, expression through speech and writing, the freedom of the press, the freedom of assembly, and the freedom of association, are all guaranteed within the scope of the law.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 13', 'Freedom of Opinion and Press', 'Constitutional Law'),
  ('LB-CONST-001', '14', 'Inviolability of the Dwelling: The dwelling is inviolable. No one is entitled to enter therein except under the conditions and manners prescribed by the law.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 14', 'Inviolability of the Dwelling', 'Constitutional Law'),
  ('LB-CONST-001', '15', 'Right to Property: The ownership is protected by the law. Ownership of any one cannot be expropriated except for reasons of public utility under the conditions prescribed by the law and upon fair compensation to him.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 15', 'Right to Property', 'Constitutional Law'),
  ('LB-CONST-001', '16', 'The Legislative Power is vested in one Chamber: The Chamber of Deputies.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 16', 'Legislative Power', 'Constitutional Law'),
  ('LB-CONST-001', '17', 'The Executive Power is entrusted to the Council of Ministers, which shall exercise it according to the provisions of this Constitution.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 17', 'Executive Power', 'Constitutional Law'),
  ('LB-CONST-001', '18', 'Right to Propose Laws: The Chamber of Deputies and the Council of Ministers have the right to propose laws. A law cannot be published unless the Chamber of Deputies adopts it.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 18', 'Right to Propose Laws', 'Constitutional Law'),
  ('LB-CONST-001', '19', 'A Constitutional Council is established to review the constitutionality of the laws, and to decide on the disputes and protests resulting from the presidential and the representative elections. The right to resort to this Council, with respect to watching the constitutionality of the laws, is due to the President of the Republic, the President of the Chamber of Deputies, and the Prime Minister, or to the members of the Chamber of Deputies, and to Heads of the legally recognized sects, with respect to personal affairs, freedom of belief and the exercise of religious rituals, and freedom of religious education. The rules concerning the organization, the functioning and the composition of the Council and the application to it are established by law.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 19', 'Constitutional Council', 'Constitutional Law'),
  ('LB-CONST-001', '20', 'The Judicial Power is vested in the Courts at various levels and jurisdictions, within a system prescribed by the law which provides the necessary guarantees to the Judges and litigants. Conditions of judicial guarantee and its limits are prescribed by the law. Judges are independent in exercising their functions. Decisions and judgments are issued by all the courts, and are executed in the name of the Lebanese People.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 20', 'Judicial Power', 'Constitutional Law'),
  ('LB-CONST-001', '21', 'Voting Rights: Every Lebanese citizen, twenty-one years old, has a right to be an elector, pending meeting the requirements prescribed by the Electoral Law.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 21', 'Voting Rights', 'Constitutional Law'),
  ('LB-CONST-001', '22', 'With the election of the first Chamber of Deputies on a national basis, not sectarian, a new Senate shall be established in which all religious communities are represented and whose power shall be limited to supreme national causes.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 22', 'Senate', 'Constitutional Law'),
  ('LB-CONST-001', '24', 'Composition of Chamber of Deputies: The Chamber of Deputies consists of elected representatives whose number and the manner of the election are determined by the electoral laws in effect. Until the Chamber of Deputies issues an Electoral Law, outside the sectarian record, representative seats are distributed according to the following rules: (a) Equally between Christians and Moslems. (b) Proportional between the sects of both sides. (c) Proportional among districts.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 24', 'Composition of Chamber of Deputies', 'Constitutional Law'),
  ('LB-CONST-001', '25', 'Elections Upon Dissolution: If the Chamber of Deputies is dissolved, the dissolution decision must call for conducting new elections. These elections are conducted according to Article 24 and within a period not exceeding three months.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 25', 'Elections Upon Dissolution', 'Constitutional Law'),
  ('LB-CONST-001', '26', 'Center of Government: Beirut is the center of the Government and the Chamber of Deputies.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 26', 'Center of Government', 'Constitutional Law'),
  ('LB-CONST-001', '27', 'Representative''s Mandate: The member of the Chamber of Deputies represents the whole nation. His electors cannot impose restrictions or conditions on his mandate.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 27', 'Representative''s Mandate', 'Constitutional Law'),
  ('LB-CONST-001', '28', 'Combining Functions: A Representative may combine the representative and the ministerial functions. Ministers may be selected from the members of the Chamber of Deputies or from persons outside it, or from both.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 28', 'Combining Functions', 'Constitutional Law'),
  ('LB-CONST-001', '32', 'Legislative Sessions: The Chamber holds two ordinary sessions every year. The first session starts on Tuesday following the fifteenth of March, and its meetings continue to the end of May. The second session starts Tuesday following the fifteenth of October. Its meetings are devoted to the discussion of the budget and voting on it, before anything else. The session lasts to year-end.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 32', 'Legislative Sessions', 'Constitutional Law'),
  ('LB-CONST-001', '33', 'Extraordinary Sessions: Ordinary sessions begin and end, de jure, as scheduled by Article 32. The President of the Republic, in agreement with the Head of Government may convene the Chamber of Deputies to extraordinary sessions by a decree setting their opening, end, and agenda. The President of the Republic is required to convene the Chamber to extraordinary sessions in response to the request made by the absolute majority of all its members.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 33', 'Extraordinary Sessions', 'Constitutional Law'),
  ('LB-CONST-001', '34', 'Quorum: The Chamber cannot be validly convened unless attended by the majority of the members who constitute it. Decisions are taken by the majority of votes. In a tie, the project under discussion is rejected.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 34', 'Quorum', 'Constitutional Law'),
  ('LB-CONST-001', '39', 'Legislative Immunity – Opinions: No member of the Chamber may be prosecuted because of the opinions and ideas he expresses during the term of his representation.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 39', 'Legislative Immunity – Opinions', 'Constitutional Law'),
  ('LB-CONST-001', '40', 'Legislative Immunity – Prosecution: No Chamber member may be prosecuted or arrested, during the session, for committing a crime, unless authorized by the Chamber, except in case he is caught in the act.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 40', 'Legislative Immunity – Prosecution', 'Constitutional Law'),
  ('LB-CONST-001', '44', 'Leadership of the Chamber: Every time a new Chamber is elected, it convenes under the presidency of the oldest member, while the youngest two members act as secretaries. The President and Vice-President are separately elected, for the term of the Chamber, by secret balloting and by the absolute majority of the votes cast.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 44', 'Leadership of the Chamber', 'Constitutional Law'),
  ('LB-CONST-001', '48', 'Remuneration of Deputies: The remuneration of the members of the Chamber shall be determined by law.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 48', 'Remuneration of Deputies', 'Constitutional Law'),
  ('LB-CONST-001', '49', 'The President of the Republic is the Chief of State, and the symbol of the unity of the Homeland. He ensures the respect of the Constitution, and the maintenance of Lebanon''s independence, its unity, and its territorial integrity in accordance with the provisions of the Constitution. He chairs the Higher Defence Council. He is the Commander in Chief of the armed forces which are subject to the authority of the Council of Ministers. The President of the Republic is elected by secret ballot, by a two-thirds majority of the votes cast in the Chamber of Deputies in the first round. The President''s term in office is six years. He may only be reelected after a period of six years has lapsed since the end of his previous term.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 49', 'President of the Republic', 'Constitutional Law'),
  ('LB-CONST-001', '50', 'Presidential Oath: When the President of the Republic assumes his office, he has to take the oath of loyalty to the Nation and the Constitution, before the Parliament, according to the following text: ''I swear by Almighty God to respect the Constitution of the Lebanese Nation and its laws, and to maintain the independence of the Lebanese Homeland, and its territorial integrity.''', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 50', 'Presidential Oath', 'Constitutional Law'),
  ('LB-CONST-001', '51', 'Promulgation of Laws: The President of the Republic promulgates the laws according to the time limits specified by the Constitution, after their approval by the Chamber. He asks for their publication, without having the right to amend them or exempt anyone from being subject to their provisions.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 51', 'Promulgation of Laws', 'Constitutional Law'),
  ('LB-CONST-001', '52', 'International Treaties: The President of the Republic assumes the negotiations to sign international treaties and ratify them with the consent of the Head of Government. They cannot be ratified, except after the approval of the Council of Ministers. The Government brings them to the attention of the Chamber of Deputies, as soon as the interest and safety of the State permit.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 52', 'International Treaties', 'Constitutional Law'),
  ('LB-CONST-001', '53', 'Presidential Powers: The President of the Republic: 1. Presides over the Council of Ministers, whenever he wishes, without participating in the vote. 2. Appoints the Head of Government in charge of consulting with the President of the Chamber of Deputies with respect to representative mandatory consultations. 3. Promulgates a decree appointing the Prime Minister separately. 4. Promulgates with the consent of the Prime Minister, the decree to form the Government, and the decrees to accept the resignation of Ministers or their dismissal. 5. Promulgates, independently, the decrees to accept the resignation of the Government or to consider it resigning. 6. Transmits the bills, submitted to him by the Council of Ministers, to the Chamber of Deputies. 7. Receives the Ambassadors, and accepts their accreditation. 8. Presides over official ceremonies, and grants State badges of honor by decree. 9. Grants special pardon by decree, but the general pardon can only be granted by law. 10. In case of necessity, addresses messages to the Chamber of Deputies. 11. Presents any of the urgent matters to the Council of Ministers, outside the agenda. 12. Calls the Council of Ministers to extraordinary meetings, as he deems necessary, in agreement with the Head of Government.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 53', 'Presidential Powers', 'Constitutional Law'),
  ('LB-CONST-001', '55', 'Dissolution of Chamber: In the cases specified in Articles 65 and 77 of this Constitution, the President of the Republic may ask the Council of Ministers for the dissolution of the Chamber of Deputies before the expiration of its mandate. Accordingly, if the Council of Ministers decides to dissolve the Chamber, the President of the Republic issues the dissolution decree. In this case, the electoral bodies convene, according to the provisions of Article 25 of the Constitution, and the new Chamber is convened within fifteen days following the proclamation of the election.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 55', 'Dissolution of Chamber', 'Constitutional Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-CONST-001', '57', 'Presidential Veto: After informing the Council of Ministers, the President of the Republic has the right to request a reconsideration of the law, once during the time limit for its promulgation. His request may not be refused. When the President uses this right, he shall not be required to promulgate the law, until it is approved by the Chamber, after another discussion related to it, and passing it by the absolute majority of the total members constituting the Chamber legally.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 57', 'Presidential Veto', 'Constitutional Law'),
  ('LB-CONST-001', '60', 'Presidential Accountability: While performing his functions, the President of the Republic cannot be accountable except in his violation of the Constitution, or in case of high treason. His liability for ordinary crimes is subject to public laws. He cannot be charged with these crimes, or with violating the Constitution and high treason except by the Chamber of Deputies by a decision issued by a two-thirds majority of all its members.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 60', 'Presidential Accountability', 'Constitutional Law'),
  ('LB-CONST-001', '62', 'Presidential Vacancy: In case the presidency becomes vacant for whatever reason, the functions of the President of the Republic are delegated to the Council of Ministers.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 62', 'Presidential Vacancy', 'Constitutional Law'),
  ('LB-CONST-001', '64', 'Prime Minister Powers: The Prime Minister is the Head of Government. He represents it, speaks in its name, and is responsible for executing the public policy made by the Council of Ministers. He assumes the following powers: 1. Presides over the Council of Ministers. By law, he is Vice President of the Supreme Council of Defense. 2. Conducts the representative consultations for the formation of the Government, and countersigns with the President of the Republic, the decree of its formation. 3. Represents Lebanon in discussions and international meetings. 4. Represents the Government''s policy before the Chamber of Deputies. 5. Assumes the functions of the other Ministers when they are absent.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004, Article 64', 'Prime Minister Powers', 'Constitutional Law'),
  ('LB-CONST-001', NULL, 'Lebanon''s Constitution was originally promulgated under the French Mandate on May 23, 1926. It was significantly amended by the Taif Agreement (Document of National Accord) in 1989-1990, following the end of the 15-year civil war. The 1990 amendments restructured the distribution of political power among religious communities, transferred executive authority from the President to the Council of Ministers, and added the preamble affirming Lebanon''s commitment to international human rights instruments. The most recent amendments were made in 2004.', 'en', 'Lebanese Constitution of 1926 with Amendments through 2004 — Historical Context', 'Historical context and overview', 'Constitutional Law'),
  ('LB-CP-001', '1', 'Purpose: The purpose of this law is to: Outline the general rules concerning the protection of consumers and the safety and quality of goods and services. Assert consumer rights and guarantee the transparency of economic transactions in which the consumer may engage. Protect consumers from fraud and misleading advertisements and prevent their exploitation. The provisions of this Law shall not apply to relations that connect suppliers.', 'en', 'Consumer Protection Law No. 659/2005, Article 1', 'Purpose', 'Commercial Law'),
  ('LB-CP-001', '2', 'Definitions: ''Consumer'': shall mean a natural or legal person who buys, rents, utilizes or benefits from goods or services, for purposes other than his professional activity. ''Supplier'': shall mean a natural or legal person, from the private or the public sector, engaged in the distribution, sale, or rent of goods or in the provision of services, on his behalf, or in the interest of someone else. For the purposes of this Law, ''Supplier'' shall also mean a person who imports goods with the aim of selling, renting or distributing such goods, within the scope of his professional activity. ''Manufacturer'': shall mean a person who transforms or assembles raw or secondary materials. ''Goods'': shall mean immovables and movables whether nutritional, natural transformed or manufactured. ''Service'': shall mean an act consisting of a technical, handicraft, or intellectual activity, of any description as given by the supplier or the consumer. ''Price'': shall mean the sale price, the rental, or the use charge. ''Standards'': shall mean standards and technical regulations that define the characteristics of goods or services, or the production method and the management systems. ''Consumer Associations'': shall mean the associations established for non-political, non-commercial or non-economic purposes. ''Advertiser'': shall mean a person who requests the broadcasting or the publication of an advertisement through any means whatsoever. ''Emergencies'': shall mean those cases that cannot be remedied through the regular course of action, that have a major impact on national security and on human, animal and plant health and safety, and that necessitate immediate action.', 'en', 'Consumer Protection Law No. 659/2005, Article 2', 'Definitions', 'Commercial Law'),
  ('LB-CP-001', '3', 'Consumer Rights: The consumer shall have the following rights that shall be exercised in accordance with the provisions of this Law: The right to protect his health and safety when goods and services are used under proper conditions. The right to receive fair and non-discriminatory treatment from the supplier of goods intended for local consumption or for exportation. The right to receive exact, clear, and sufficient information about goods or services and about the price, description and method of use of such goods and services and the potential risk that they may pose. The right to exchange or repair the goods or to get a refund of the price already paid for a service if such goods or service, when used under proper conditions, do not comply with the applicable or agreed standards or with the purpose for which the goods or services are acquired. The right to obtain an appropriate and full compensation for damage resulting from the consumption of goods or the use of services, when used under proper conditions. The right to establish and adhere to Consumer Protection Associations. The right to sue for damages or for the assertion of his rights, on his own or through Consumer Protection Associations.', 'en', 'Consumer Protection Law No. 659/2005, Article 3', 'Consumer Rights', 'Commercial Law'),
  ('LB-CP-001', '4', 'Supplier Information Obligations: Suppliers shall provide the consumers with exact, sufficient, and clear information about: Essential data about the goods or services and the directions for their use; The price and the terms of the contract including the procedures of the contract; The risks that goods or services may pose.', 'en', 'Consumer Protection Law No. 659/2005, Article 4', 'Supplier Information Obligations', 'Commercial Law'),
  ('LB-CP-001', '5', 'Price Display Requirements: The supplier shall: Conspicuously display the price in Lebanese pounds on the goods or on the shelves where such goods are displayed. Comply with the official weights and volumes metric system.', 'en', 'Consumer Protection Law No. 659/2005, Article 5', 'Price Display Requirements', 'Commercial Law'),
  ('LB-CP-001', '6', 'Price Display in Service Establishments: Prices shall also be displayed in an easily identifiable place in service establishments, especially hotels, furnished apartments, restaurants, cafés and amusement centers.', 'en', 'Consumer Protection Law No. 659/2005, Article 6', 'Price Display in Service Establishments', 'Commercial Law'),
  ('LB-CP-001', '7', 'Labeling Requirements: The information determined by the relevant administration, must be displayed on the labels attached to the goods or to the packages of such goods, depending on the goods'' nature and description and in accordance with applicable standards. The above-mentioned information may include, inter alia: The goods'' nature, type, elements, ingredients and/or composition; The net weight, volume or number of the goods; The shelf life of the goods; The country of origin; The name and address of the manufacturer or supplier; The side effects and the safety instructions of the goods.', 'en', 'Consumer Protection Law No. 659/2005, Article 7', 'Labeling Requirements', 'Commercial Law'),
  ('LB-CP-001', '8', 'Foodstuffs Control: Foodstuffs that are sold by weight in unpacked form shall be subjected to the control of the Consumer Protection Directorate.', 'en', 'Consumer Protection Law No. 659/2005, Article 8', 'Foodstuffs Control', 'Commercial Law'),
  ('LB-CP-001', '9', 'Language Requirements: The information on the labels or on the packages of the goods must be displayed in principle in Arabic. In general, Arabic must be used for any act aimed at displaying goods or services. The cases where it is permissible to use French or English as a substitute for Arabic shall be determined upon the decision of the Minister of Economy and Trade.', 'en', 'Consumer Protection Law No. 659/2005, Article 9', 'Language Requirements', 'Commercial Law'),
  ('LB-CP-001', '10', 'Used or Faulty Goods: When used, reconditioned, or faulty goods that do not cause any damage to consumer health and safety, are displayed, the supplier must conspicuously indicate the state of such goods on the goods and at his business location. The supplier must also indicate the state of the goods in the contract of sale or in the invoice.', 'en', 'Consumer Protection Law No. 659/2005, Article 10', 'Used or Faulty Goods', 'Commercial Law'),
  ('LB-CP-001', '11', 'Misleading Advertisement: A misleading advertisement means an advertisement which by any means includes a false representation, declaration or pretense or which contains expressions of such a nature as to mislead or deceive the consumer, either directly or indirectly. Should be considered misleading the representation, declaration or pretense that treats, inter alia, of one of the following issues: The nature, composition and essential characteristics of the goods as well as the elements or the element''s quantity of such goods; The origin, weight, volume, manufacturing method, expiry date, directions for use or safety instructions of the goods; The type of the service and the agreed place for the provision of such service; The contract terms, the total price and the method of payment; The advertiser''s obligations; The identity, qualifications and description of the manufacturer or supplier. Should also be considered a misleading advertisement: The false declaration by the advertiser that he holds prizes, certifications, attestations or private or official medals; The advertisement which include the illegal use of a logo or a trademark, or the use of an imitated or simulated mark.', 'en', 'Consumer Protection Law No. 659/2005, Article 11', 'Misleading Advertisement', 'Commercial Law'),
  ('LB-CP-001', '12', 'Burden of Proof in Advertising: The advertiser must prove the veracity of the information announced in his advertisement and supply to the Consumer Protection Directorate or to the relevant examining court the documents that they may request.', 'en', 'Consumer Protection Law No. 659/2005, Article 12', 'Burden of Proof in Advertising', 'Commercial Law'),
  ('LB-CP-001', '13', 'Correction of Misleading Advertisements: The Ministry of Economy and Trade shall have the right to require the advertiser to correct or amend its advertisement, to publish a notice of the correction or amendment, or to broadcast such notice, through the same media which broadcasted or published the misleading advertisement. In addition, the examining court may automatically order to stop the broadcasting of the misleading advertisement. The decision of the court in this regard must be immediately implemented. The judicial authority which makes such decision shall have the right to revoke it.', 'en', 'Consumer Protection Law No. 659/2005, Article 13', 'Correction of Misleading Advertisements', 'Commercial Law'),
  ('LB-CP-001', '14', 'Advertising Regulations: The general principles regulating the advertisement related to goods and services and the main requirements for such advertisements, shall be determined by virtue of a decree issued by the Council of Ministers, at the suggestion of the Minister of Economy and Trade.', 'en', 'Consumer Protection Law No. 659/2005, Article 14', 'Advertising Regulations', 'Commercial Law'),
  ('LB-CP-001', '15', 'Promotional Offers: The supplier, who advertises a special offer for the promotion of goods or services, must determine either the period of time in which such goods or services are available for sale, or the available quantity of such goods or services. The supplier shall, when necessary, announce the terms of the contract. Where the supplier does not determine such period or quantity, the offer shall last one month after the date of the first advertisement unless the supplier has announced in the same manner and through the same media the date at which his offer will be concluded.', 'en', 'Consumer Protection Law No. 659/2005, Article 15', 'Promotional Offers', 'Commercial Law'),
  ('LB-CP-001', '16', 'Failure to Deliver Promoted Goods: Should the supplier fail to deliver the promoted goods or services exactly of the kind advertised, the consumer may choose one of the following options: to accept another goods or services of the kind advertised, if the supplier so offers; or to cancel the contract and recover any amount previously paid. The consumer shall also have the right to claim damages resulting from the use of such goods or services, which shall be no less than the difference between the price of the goods or services during the period of the offer and their actual price.', 'en', 'Consumer Protection Law No. 659/2005, Article 16', 'Failure to Deliver Promoted Goods', 'Commercial Law'),
  ('LB-CP-001', '17', 'Scope of Contractual Provisions: The provisions of this Law treating of contracts concluded between suppliers and consumers shall be enforced, without prejudice to the provisions of the laws on liberal professions, banks, and insurance companies.', 'en', 'Consumer Protection Law No. 659/2005, Article 17', 'Scope of Contractual Provisions', 'Commercial Law'),
  ('LB-CP-001', '18', 'Contract Interpretation: A contract shall be interpreted in the favor of a consumer. The contract''s circumstances, the benefits resulting there from and the balance between the rights and obligations of both parties, should all be taken into consideration in order to determine the extent of a consumer''s satisfaction.', 'en', 'Consumer Protection Law No. 659/2005, Article 18', 'Contract Interpretation', 'Commercial Law'),
  ('LB-CP-001', '19', 'Standard Form Contracts: A contract whether prepared by a supplier or approved by official authorities or the contract that a consumer is not entitled to modify, must fulfill the following requirements: The contract must be drawn in simple and straightforward Arabic language. English is however permissible where parties so agree. The contract must not refer to texts or documents which had not been supplied to the consumer before he had entered into the contract. The contract must clearly determine the cost, the date of payment and the method of payment and the place and time of delivery.', 'en', 'Consumer Protection Law No. 659/2005, Article 19', 'Standard Form Contracts', 'Commercial Law'),
  ('LB-CP-001', '20', 'Right to Review Contract: The supplier must make a copy of the contract available to the consumer, in order for the consumer to read such contract before entering into it.', 'en', 'Consumer Protection Law No. 659/2005, Article 20', 'Right to Review Contract', 'Commercial Law'),
  ('LB-CP-001', '21', 'Installment Plan Requirements: A supplier, who offers an installment plan, must provide the consumer with the following information: The cost, when the payment is settled at once not on credit; The applicable annual interest rate; the supplier must also specify whether the interest is simple or compound and determine the method of calculation of such interest and the total amount of the interest and the expenses to be paid by the consumer; The number and amount of each installment and the due date for payment; The total cost after all installments are paid, inclusive of the value of the goods or services if paid at once added to the interests and expenses; The rights and obligations of both a supplier and a consumer, whenever one of them breaches the contract.', 'en', 'Consumer Protection Law No. 659/2005, Article 21', 'Installment Plan Requirements', 'Commercial Law'),
  ('LB-CP-001', '22', 'Copy of Signed Contract: A supplier shall provide the consumer with a copy of the contract that the supplier had signed. This copy shall be exempted from all fees especially the stamp duty.', 'en', 'Consumer Protection Law No. 659/2005, Article 22', 'Copy of Signed Contract', 'Commercial Law'),
  ('LB-CP-001', '23', 'Early Settlement of Installments: A consumer may, at any time, settle all installments before maturity, provided that the due interest is deducted from the amount of such installments. When a financial institution or a bank enters into a contract with a consumer, the procedures of the implementation of the previous paragraph, and when necessary, the due penalties must be included in such contract.', 'en', 'Consumer Protection Law No. 659/2005, Article 23', 'Early Settlement of Installments', 'Commercial Law'),
  ('LB-CP-001', '24', 'Deposits: Settled payments must not be considered a deposit, unless if the consumer has been previously informed, in writing, that he has no right to get a refund if he rescinds the contract.', 'en', 'Consumer Protection Law No. 659/2005, Article 24', 'Deposits', 'Commercial Law'),
  ('LB-CP-001', '25', 'Invoice Requirements: A supplier or a service provider must provide the consumer with an invoice encompassing the following data: The name, commercial registration number and address of the establishment; The identification of the product or service; The sale or rent unit and its price; The agreed quantity; The amount of collected taxes and fees; The date and the total value in LBP of the invoice. If the product or service is not immediately delivered, the invoice must include the place, date and conditions of delivery.', 'en', 'Consumer Protection Law No. 659/2005, Article 25', 'Invoice Requirements', 'Commercial Law'),
  ('LB-CP-001', '26', 'Abusive Clauses: The clauses, aiming at or leading to the creation of an imbalance between the rights and obligations of a supplier and a consumer in the favor of the supplier, shall be considered abusive. The abusive aspect of a contract shall be evaluated on the basis of the date, clauses and attachments of such contract, except for price-related clauses. The following clauses shall be, inter alia, considered abusive: The clauses that exempt the supplier from his liabilities; The consumer''s waiver of any of his rights prescribed by laws and regulations; The clause that places the burden of proof on the consumer, in cases other than those prescribed by the Law; The supplier''s unilateral entitlement to modify one or all of the clauses of the contract, especially in terms of price, date and place of delivery; The supplier''s entitlement to rescind an open-ended contract, without notifying the consumer about his desire to rescind it, within a reasonable period; The consumer''s obligation – if he breaches any of his contractual obligations - to overcompensate the damage caused to the supplier; The supplier''s entitlement to interpret the provisions of the contract; The consumer''s obligation to carry out his commitments, while the supplier abstains from carrying out his commitments; The clause that does not allow mediation or arbitration for dispute settlement in accordance with the provisions of this Law. Abusive clauses shall be deemed completely void, while all other clauses shall remain applicable.', 'en', 'Consumer Protection Law No. 659/2005, Article 26', 'Abusive Clauses', 'Commercial Law'),
  ('LB-CP-001', '27', 'After-Sale Service: The supplier or manufacturer must: Provide parts or pieces necessary for the use of specific goods or services; Provide after sale service and maintenance. Such obligations shall be considered binding within a reasonable period of time, commensurate with the expected date of use of the goods or services, unless the consumer had received a written and express notice about a different period. The supplier or manufacturer shall be exempted from the above mentioned obligations, when the consumer receives an express written notice stating undoubtedly, that the consumer or manufacture is not committed to any of these obligations.', 'en', 'Consumer Protection Law No. 659/2005, Article 27', 'After-Sale Service', 'Commercial Law'),
  ('LB-CP-001', '28', 'Quality Guarantee: The supplier shall guarantee the quality of the goods or services and the availability of the description that such supplier has announced or that the consumer has requested in writing. The supplier shall also guarantee that the goods or services are delivered to the consumer without the objection of any third party. The supplier must not include in his contracts any clause that exempts him from the obligations mentioned here above.', 'en', 'Consumer Protection Law No. 659/2005, Article 28', 'Quality Guarantee', 'Commercial Law'),
  ('LB-CP-001', '29', 'Guarantee of Invisible Faults: The supplier shall guarantee invisible faults that concretely damage the goods or services or make such goods or services unsuitable for the use to which they can be put depending on their nature or on the provisions of the contract. The guarantee shall neither cover faults that slightly damage the goods or services or the use of such goods or services, nor faults customarily allowable. The supplier must include the previous paragraph in all documents made available to the consumer. The supplier may commit himself to additional guarantees. In this case, the additional guarantees shall be added to the guarantees laid down in this Law.', 'en', 'Consumer Protection Law No. 659/2005, Article 29', 'Guarantee of Invisible Faults', 'Commercial Law'),
  ('LB-CP-001', '30', 'Proof of Invisible Fault: The consumer or his successors must prove, by all means, that the invisible fault existed at the date of delivery and that such fault had either caused concrete damage to the goods or services or had made such goods or services unsuitable for the purpose for which they are intended.', 'en', 'Consumer Protection Law No. 659/2005, Article 30', 'Proof of Invisible Fault', 'Commercial Law'),
  ('LB-CP-001', '31', 'Time Limit for Guarantee Claims: The guarantee-related legal proceedings and the procedures of mediation or dispute settlement prescribed in this Law shall be initiated within one month after the fault had been discovered, unless the disrespectability of this period is due to delaying tactics used by the supplier.', 'en', 'Consumer Protection Law No. 659/2005, Article 31', 'Time Limit for Guarantee Claims', 'Commercial Law'),
  ('LB-CP-001', '32', 'Cancellation Right: A consumer shall have the right to request the cancellation of the contract and to recover the amount already paid if the faulty goods mentioned in Articles 28 and 29 of this Law, had not been replaced or repaired within a reasonable period of time proportionate to the nature of the goods or services. The consumer may in addition to the above be able to claim damages.', 'en', 'Consumer Protection Law No. 659/2005, Article 32', 'Cancellation Right', 'Commercial Law'),
  ('LB-CP-001', '33', 'Repair Obligations: The supplier shall, before repairing the goods, notify the consumer in writing and for free about the repair cost assessed and the duration of such repair. The supplier shall, after the repair had been concluded, specify in the invoice furnished to the consumer the parts that they were replaced and the price of such parts and whether they are new, used or renovated. The supplier shall guarantee the spare parts and shall be responsible for the labor cost within a period lasting for 3 months after the date of delivery of the repaired goods. This guarantee shall not cover cases where the goods are repaired due to misuse.', 'en', 'Consumer Protection Law No. 659/2005, Article 33', 'Repair Obligations', 'Commercial Law'),
  ('LB-CP-001', '34', 'Public Order Provisions: The provisions of the present chapter shall fall within the public order.', 'en', 'Consumer Protection Law No. 659/2005, Article 34', 'Public Order Provisions', 'Commercial Law'),
  ('LB-CP-001', '35', 'Consumer Health and Safety Standards: The provisions of this Law related to consumer health and safety as well as the texts of applicable laws and regulations defining the standards related to specific goods or services and the conditions for trading in such goods and services, shall all be implemented.', 'en', 'Consumer Protection Law No. 659/2005, Article 35', 'Consumer Health and Safety Standards', 'Commercial Law'),
  ('LB-CP-001', '36', 'Risk Information: The supplier shall provide to the consumer information reasonably necessary for the consumer to assess the risks linked to the use of the goods or services during the expected period of such use.', 'en', 'Consumer Protection Law No. 659/2005, Article 36', 'Risk Information', 'Commercial Law'),
  ('LB-CP-001', '37', 'Instructions for Use: A manufacturer or supplier shall demonstrate in writing and clearly the best method of use of the goods or services and warn the consumer of the risks that could result from the misuse of such product or service. The above-mentioned information must be written in Arabic.', 'en', 'Consumer Protection Law No. 659/2005, Article 37', 'Instructions for Use', 'Commercial Law'),
  ('LB-CP-001', '38', 'Market Compliance: The supplier, who places goods or services for the first time on the market, must ensure the compliance of such goods or services with the standards prescribed in the applicable laws and regulations. The supplier must also ensure that the said goods or services comply with the safety standards, if used properly and naturally.', 'en', 'Consumer Protection Law No. 659/2005, Article 38', 'Market Compliance', 'Commercial Law'),
  ('LB-CP-001', '39', 'Lebanese Accreditation Council — Laboratories: The Lebanese Accreditation Council established by the Law No.572 of 11 February 2004 shall specify the local and international laboratories, the accreditation agencies and the inspection and prior testing offices, whose certificates related to the safety of goods especially food safety, are recognized in Lebanon.', 'en', 'Consumer Protection Law No. 659/2005, Article 39', 'Lebanese Accreditation Council — Laboratories', 'Commercial Law'),
  ('LB-CP-001', '40', 'Lebanese Accreditation Council — Certification: The Lebanese Accreditation Council established by the Law No.572 of 11 February 2004 shall specify the conditions required to grant scientific institutions the authority to issue certificates attesting the compliance of goods and services with the adopted standards.', 'en', 'Consumer Protection Law No. 659/2005, Article 40', 'Lebanese Accreditation Council — Certification', 'Commercial Law'),
  ('LB-CP-001', '41', 'Testing of Goods: The Consumer Protection Directorate located at the Ministry of Economy and Trade may request to test specific goods in accredited laboratories at the expense of the manufacturer or supplier, especially when such goods are newly launched or when doubts exist about a danger jeopardizing the health or safety of consumers. The Director General of Economy and Trade, may, when necessary, allow the re-testing of such goods, provided that the supplier incurs the re-testing expenses, if the retesting is decided at the supplier''s request. The Minister of Economy and Trade may, at the suggestion of the Director General of Economy and trade, suspend the trading in such goods, until the results of the tests have been obtained.', 'en', 'Consumer Protection Law No. 659/2005, Article 41', 'Testing of Goods', 'Commercial Law'),
  ('LB-CP-001', '42', 'Ceasing Non-Compliant Trade: The supplier shall cease the trading in goods or services which are not in conformity with the safety-related applicable standards.', 'en', 'Consumer Protection Law No. 659/2005, Article 42', 'Ceasing Non-Compliant Trade', 'Commercial Law'),
  ('LB-CP-001', '43', 'Proof of Non-Compliance: The damaged person or his successors shall prove that the goods do not comply with the applicable safety standards that are expected from the proper use of the goods or services. The damaged shall also prove that the damage is caused in result of such incompliance and indicate the value of such damage.', 'en', 'Consumer Protection Law No. 659/2005, Article 43', 'Proof of Non-Compliance', 'Commercial Law'),
  ('LB-CP-001', '44', 'Recall Obligations: When a manufacturer or supplier finds out by experience or in the light of the information made available to him, that the goods or services that the he has placed on the market contain one or more faults that might detriment consumers health or jeopardize their safety, such manufacturer or supplier must take all necessary measures to inform the public about the faults and warn of their risks, through the media. If such is the case, the manufacturer or supplier must, in addition to the above, take the following measures: To refrain from trading in the goods or services; To withdraw the goods placed on the market; To recall the goods sold or rent and reimburse the money already paid; To exchange the goods at the supplier or manufacturer''s own expense or to reimburse the money already paid if the repair of the goods is impossible. In the cases mentioned here above, the supplier or the manufacturer shall notify the Consumer Protection Directorate located at the Ministry of Economy and Trade about the said risks and shall specify the measures to be taken.', 'en', 'Consumer Protection Law No. 659/2005, Article 44', 'Recall Obligations', 'Commercial Law'),
  ('LB-CP-001', '45', 'Ministry Powers — Public Health Risks: When the Ministry of Economy and Trade has scientific proofs about a risk that may result from the use of given goods or services and threaten public health or safety, whether such risk had already occurred or is expected to occur, the Ministry shall inform the public about the risks and the precautionary measures to be taken. If such is the case, the Minister of Economy and Trade shall issue decisions laying down the procedures aimed at protecting public health and safety, such as: Prohibiting the importation or exportation of such goods in emergencies; Setting out specific requirements as to the importation or exportation of such goods; Prohibiting the trading in the goods or services; Withdrawing the goods from the market, at the expense of the manufacturer or supplier; Destroying the goods at the expense of the manufacturer or supplier, jointly and severally, if such a procedure is the only solution for the protection of public health and safety. Such decisions shall be published through the media and sent to the Council of Ministers for approval.', 'en', 'Consumer Protection Law No. 659/2005, Article 45', 'Ministry Powers — Public Health Risks', 'Commercial Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-CP-001', '46', 'Manufacturer and Supplier Liability: The manufacturer and the supplier shall be responsible for the damage caused by the goods or services to public health and safety, even if the competent administration has granted any type of certificates related to such goods or services. In such a case, and where the existence of any serious risk is not proved to have occurred at the time of the grant of the certificates, the government or the public institutions shall not be liable for such damage.', 'en', 'Consumer Protection Law No. 659/2005, Article 46', 'Manufacturer and Supplier Liability', 'Commercial Law'),
  ('LB-CP-001', '47', 'Special Import/Export Requirements: The special requirements concerning the importation or exportation of specific goods shall be determined, when necessary, by virtue of decrees issued at the suggestion of the Minister of Economy and Trade and the competent Minister, following consultation with ''The National Consumer Protection Council'' mentioned in Article 60 of this Law.', 'en', 'Consumer Protection Law No. 659/2005, Article 47', 'Special Import/Export Requirements', 'Commercial Law'),
  ('LB-CP-001', '48', 'Prohibited Practices: The supplier or manufacturer shall be prohibited to perform the following acts: Manufacturing, preparing, owning, transporting, displaying or distributing all classes of goods or services in such a manner as to hide either their nature, or their essential characteristics, or the proportion of their essential ingredients; Counterfeiting or attempting to counterfeit goods; Manufacturing goods or rendering services incompliant with the mandatory applicable standards or which jeopardize the consumer''s health or safety; Delivering goods or services incompliant with the adopted and agreed standards, especially in terms of quantity, type, description or origin; Misleading the consumer, by any means, such as by concealing or neglecting information or by communicating to the consumer wrong information about the nature, type, origin, essential characteristics, composition and constituents of the goods or about the instructions for use and expiry date of such goods.', 'en', 'Consumer Protection Law No. 659/2005, Article 48', 'Prohibited Practices', 'Commercial Law'),
  ('LB-CP-001', '49', 'Weighing and Measuring Devices: The following acts shall be prohibited: The use of unchecked weighing and measuring devices and other inaccurate instruments used in the weighing, measuring or gauging of goods; The use of devices or instruments for fraudulent practices.', 'en', 'Consumer Protection Law No. 659/2005, Article 49', 'Weighing and Measuring Devices', 'Commercial Law'),
  ('LB-CP-001', '50', 'Prohibited Supplier Acts: Taking into consideration the provisions of Article 11 of this Law, the supplier shall not be allowed: To rescind the contract or tie the contract up with a certain number or quantity of goods or services while the stores of such supplier are opened to sell other goods, unless such goods or services have been subjected to a special official regulation; To tie up the sale of certain goods or the rendering of certain services with the purchase of specific quantities or other goods or services, except for cases where the buyer is able to buy separately any goods or services object of a set offer or where such goods or services are sold in non detachable packs or units; To sell or rent any goods at a price exceeding the promoted price; To deliver to the consumer goods or services without having expressed his will to buy or rent such goods or services; To provide to the consumer false information with regard to the date of the delivery of the goods or services or the terms of the contract and the method of payment.', 'en', 'Consumer Protection Law No. 659/2005, Article 50', 'Prohibited Supplier Acts', 'Commercial Law'),
  ('LB-CP-001', '51', 'Scope of Distance Trading Provisions: The provisions of this Chapter treats of distance or door-to-door trading practices performed by the supplier, in particular the practices that take place at the residence of the consumer, by telephone, through the Internet or by any other adopted means. The provisions of this Chapter shall apply neither to financial and bank transactions nor to auction sale and immovables-related transactions.', 'en', 'Consumer Protection Law No. 659/2005, Article 51', 'Scope of Distance Trading Provisions', 'Commercial Law'),
  ('LB-CP-001', '52', 'Pre-Contract Information in Distance Sales: In the cases prescribed in Article 51, the consumer must be provided with clear information necessary to make a decision about entering into a contract, especially concerning the following: The identification, name, address, number and place of registration and e-mail of the supplier; The goods or services subject of the offer, the instructions for the use of such goods and services and the risks that may result from such use; The length of the offer period; The cost of the goods or services and the adopted currency in addition to all the charges that may be added to the cost, especially fees, taxes and any type of expenses, and the method of payment; The guarantees offered by the supplier; The period of the contract; The delivery date and place and the expenses due; The procedures that shall be implemented to conclude the contract; The period in which the consumer may rescind the contract; The law related to such trading practice and the relevant bodies, courts and authorities entitled to settle any contract-related dispute; The call cost.', 'en', 'Consumer Protection Law No. 659/2005, Article 52', 'Pre-Contract Information in Distance Sales', 'Commercial Law'),
  ('LB-CP-001', '53', 'Written Documentation: The supplier must furnish to the consumer a written document encompassing all information mentioned in Article 52.', 'en', 'Consumer Protection Law No. 659/2005, Article 53', 'Written Documentation', 'Commercial Law'),
  ('LB-CP-001', '54', 'Consumer Rights in Distance Sales: The information provided by the supplier must enable the consumer to clearly identify the product or the service offered for sale, and to look into a specimen of the agreed agreement. The consumer shall also be entitled to modify or correct his order. That being the case, both parties must keep a record of the whole trading practice made.', 'en', 'Consumer Protection Law No. 659/2005, Article 54', 'Consumer Rights in Distance Sales', 'Commercial Law'),
  ('LB-CP-001', '55', 'Right of Rescission in Distance Sales: Contrary to any other text, the consumer who enters into a contract through a distance trading practice, shall have the right to rescind the contract within a period of seven days from the date of signing the contract or from the date of the delivery of the goods, without need to provide any reason and without incurring any penalties or costs other than the direct cost of returning the goods. The consumer''s right of rescission must be clearly stated in the contract. Failure to mention the right of rescission in the contract shall increase the rescission period to three months. In such cases, the supplier must reimburse the total cost of the goods within fifteen days of the date of rescission. The provisions of this Article shall apply to door-to-door transactions as well.', 'en', 'Consumer Protection Law No. 659/2005, Article 55', 'Right of Rescission in Distance Sales', 'Commercial Law'),
  ('LB-CP-001', NULL, 'Lebanon''s first comprehensive consumer protection statute, enacted February 4, 2005. Established the Consumer Protection Directorate at the Ministry of Economy and Trade. Covers consumer rights, labeling, advertising, contracts, guarantees, product safety, prohibited practices, and distance trading. Implements obligations consistent with EU consumer protection standards of the period.', 'en', 'Consumer Protection Law No. 659/2005 — Historical Context', 'Historical context and overview', 'Commercial Law'),
  ('LB-IP-001', '1', 'Definitions: For the purpose of applying the provisions of this Law, the meaning of the terms and expressions hereinafter shall be as follows, unless otherwise indicated in the context. These definitions apply also to related rights. ''Performance of work'' means the execution of a work through exhibition, playing music, reciting, narrating, acting, dancing or any other means whether directly or through any means or device. ''Public performance'' means a performance which is given in a place or places where the number of persons present exceeds the members of one family and their direct acquaintances. ''Broadcasting'' means the transmission of the work for public reception by wireless means including transmission by satellite. ''Computer program'' means a set of orders expressed in words or symbols or in any other form which when entered into a matter readable by a computer shall enable the computer to perform or execute a certain task or give a certain result. ''Phonogram/sound recording'' means every fixation by any physical means of the sounds of a performance or of other sounds, whether resulting from the performance of a work or not, other than a fixation incorporated in an audiovisual work. ''Reprographic reproduction'' means making copies from the original of a work by means other than printing, such as photocopying, and includes enlarged or reduced copies of the work. ''Related rights'' means the rights that performers, producers of phonograms, television and radio broadcasting organizations and publishing houses enjoy. ''Work'' means every work within the meaning of Articles 2 and 3 of this Law. ''Collective work'' means a work in which more than one natural person participates under the initiative and supervision of a natural person who, or legal entity which, undertakes to publish it under his/its own name. ''Audiovisual work'' means every work consisting of a set of consecutive images related to each other, whether accompanied by sound or not, and that gives the impression of motion if displayed, broadcast or transmitted with special devices. ''Work of joint authorship'' means every work created by more than one author on condition that the said work does not constitute a collective work. ''Producer of sound recording/phonogram or audiovisual work'' means the natural person who, or legal entity which, takes the initiative and responsibility for producing the audiovisual work or sound recording/phonogram. ''Author'' means the natural person who creates a certain work. ''Reproduction'' means making one or more copies of any work by any means or in any form, including a permanent or temporary recording on phonogram records, tapes, disks, electronic memory. ''Copy'' means the product of any copying, recording, printing, or photocopying of the original work. ''Publication'' means making copies of the work or of the sound recording/phonogram available to the public in reasonable quantities with the consent of the author or the producer of the sound recording/phonogram, by means of selling, renting, or any other means of property transfer or acquisition of a copy. ''Communication to the public'' means making the work available to the public by wire or wireless transmission of sounds and/or images, in such a way as to allow the public to hear or view the work at a distance from the broadcasting center. This includes making the work available to the public by wire or wireless means (like the internet) in such a way that every person may access it from a place and at a time chosen by them.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 1', 'Definitions', 'Intellectual Property Law'),
  ('LB-IP-001', '2', 'Protected Works: The protection of this Law shall apply to every production of the human spirit be it written, pictorial, sculptural, manuscript or oral, regardless of its value, importance or purpose and the mode or form of its expression. The protection of this Law shall apply, among other works, to: books, archives, pamphlets, publications, printed material and other literary, scientific and artistic writings; lectures, addresses and other oral works; audiovisual works and photographs; musical compositions with or without words; dramatic or dramatico-musical works; choreographic works and pantomimes; drawings, sculpture, engraving, ornamentation, weaving and lithography; illustrations and drawings related to architecture; computer programs whatever their language and including preliminary work; maps, plans, sketches and three-dimensional works relative to geography, topography, architecture or science; any kind of plastic art work whether intended for industry or not.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 2', 'Protected Works', 'Intellectual Property Law'),
  ('LB-IP-001', '3', 'Derivative Works: The following derivative works shall be subject to the provisions of this Law and shall be protected as original works without prejudice to the rights in the original work: translations, adaptations, transformations and arrangements of music; collections of literary or artistic works and compilations of data, whether in machine-readable or other form, provided that they are authorized by the copyright holder or his public or private successors and that by reason of the selection and arrangement of their contents they constitute intellectual creations.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 3', 'Derivative Works', 'Intellectual Property Law'),
  ('LB-IP-001', '4', 'Exclusions from Protection: The following shall be excluded from the protection provided by this Law: daily news; laws, legislative decrees, decrees and decisions issued by all public authorities and official translations thereof; judicial decisions of all kinds and official translations thereof; speeches delivered in public assemblies and meetings (the authors of speeches and presentations shall enjoy the sole right of collecting and publishing such lectures and presentations); ideas, data and abstract scientific facts; artistic folkloric works of all kinds. However, works inspired by folklore shall enjoy protection.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 4', 'Exclusions from Protection', 'Intellectual Property Law'),
  ('LB-IP-001', '5', 'Author''s Property Right: The author of any artistic or literary work shall, as a result of the creation of the work, have an absolute property right over his work and shall reserve all his rights without having to follow any formalities.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 5', 'Author''s Property Right', 'Intellectual Property Law'),
  ('LB-IP-001', '6', 'Joint Authorship: In the case of a joint work in which each contribution consists of an integral part of the work as a whole, all the contributors shall be considered coauthors and co-owners of copyright in the work. However, if it is possible to distinguish the contribution of each author from the others, each of the joint authors shall be considered the author of his own contribution. In a joint work, none of the coauthors may, in the absence of any written agreement to the contrary, exercise copyright without the consent of the other authors.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 6', 'Joint Authorship', 'Intellectual Property Law'),
  ('LB-IP-001', '7', 'Collective Works: In the case of a collective work, the natural person who, or legal entity which, took the initiative to create the work and supervise its execution shall, in the absence of any agreement to the contrary, be considered the copyright holder.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 7', 'Collective Works', 'Intellectual Property Law'),
  ('LB-IP-001', '8', 'Works Created Under Employment: In the case of a work created by natural persons working under a work contract for a natural person or legal entity in the course of performing their duties or professional obligations, the employer shall, in the absence of any agreement to the contrary, be the copyright holder and shall exercise the rights provided for in Article 15 of this Law.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 8', 'Works Created Under Employment', 'Intellectual Property Law'),
  ('LB-IP-001', '9', 'Audiovisual Works: In the case of an audiovisual work, the producer shall, in the absence of any agreement to the contrary, be considered the copyright holder.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 9', 'Audiovisual Works', 'Intellectual Property Law'),
  ('LB-IP-001', '10', 'Anonymous and Pseudonymous Works: In the case of anonymous and pseudonymous works, the natural person who, or legal entity which, published the work shall be considered the author. However should the identity of the author be revealed, he himself shall exercise these rights.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 10', 'Anonymous and Pseudonymous Works', 'Intellectual Property Law'),
  ('LB-IP-001', '11', 'Presumption of Authorship: The person whose name is shown on a literary or artistic work in the commonly known way shall, unless proved otherwise, be considered the author.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 11', 'Presumption of Authorship', 'Intellectual Property Law'),
  ('LB-IP-001', '12', 'Eligibility for Protection — Persons: The protection of this Law shall apply to the artistic and literary works of the following: Lebanese authors, wherever they reside; non-Lebanese authors who are nationals of, or resident in, a State party to the Berne Convention for the Protection of Literary and Artistic Works or the Universal Copyright Convention; authors who are nationals of any State that is a member of the Arab League but which is not party to the above-mentioned Conventions, provided reciprocal treatment is applied; producers of audiovisual works who have their headquarters or habitual residence in Lebanon or in any State party to the Berne Convention for the Protection of Literary and Artistic Works or the Universal Copyright Convention.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 12', 'Eligibility for Protection — Persons', 'Intellectual Property Law'),
  ('LB-IP-001', '13', 'Eligibility for Protection — Works: The protection of this Law shall apply to: literary and artistic works first published in Lebanon; literary and artistic works first published in a State party to one of the above-mentioned Conventions; literary and artistic works first published outside Lebanon and outside the States party to one of the above-mentioned Conventions, provided that they are published in Lebanon or in a State party to the above-mentioned Conventions within 30 days of their publication in the other country.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 13', 'Eligibility for Protection — Works', 'Intellectual Property Law'),
  ('LB-IP-001', '14', 'Copyright Holder''s Rights: The copyright holder shall enjoy economic and moral rights.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 14', 'Copyright Holder''s Rights', 'Intellectual Property Law'),
  ('LB-IP-001', '15', 'Economic Rights: The copyright holder shall have the exclusive right to exploit the work commercially and, accordingly, shall have the right to authorize or prohibit the following: any copying, printing, recording and reproduction of the work in any manner or form including photography, cinematography, sound or visual recordings of any kind or any other form; any translation, adaptation, alteration, transformation, summarizing, reworking of the work or rearrangement of the music; the sale, distribution or rental of the work; the importation of copies of the work manufactured abroad; the public performance of the work; communication to the public of the work by wire or wireless means, whether through hertzian waves or the like or through coded or uncoded satellites, including the rebroadcast of normal television or radio broadcasts or satellite transmissions by any means of diffusion of sounds and images.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 15', 'Economic Rights', 'Intellectual Property Law'),
  ('LB-IP-001', '16', 'Transfer of Economic Rights: The economic rights of the author shall be considered as movable rights and may be transferred in whole or in part.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 16', 'Transfer of Economic Rights', 'Intellectual Property Law'),
  ('LB-IP-001', '17', 'Exploitation Contracts: Any contract for the exploitation or assignment of economic rights shall, whatever its subject, be drawn up in writing, otherwise it shall entail nullity of the contract. It shall set out in detail the rights covered by the contract and indicate the time and location. The contract shall also require that the author gets a percentage of the exploitation revenues and assignment proceeds. If such a contract does not set a time limit, it shall be valid for 10 years only from the date of signature of the contract.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 17', 'Exploitation Contracts', 'Intellectual Property Law'),
  ('LB-IP-001', '18', 'Future Works Assignment: The assignment in whole of future works shall be considered as void.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 18', 'Future Works Assignment', 'Intellectual Property Law'),
  ('LB-IP-001', '19', 'Restrictive Interpretation of Copyright Contracts: The assignment by the author of any of his rights must be limited in all cases to that right only and copyright contracts shall be construed in a restrictive manner.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 19', 'Restrictive Interpretation of Copyright Contracts', 'Intellectual Property Law'),
  ('LB-IP-001', '20', 'Songs — Equal Rights of Author and Composer: The author and composer of a song shall have equal rights in that work, unless agreed otherwise.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 20', 'Songs — Equal Rights of Author and Composer', 'Intellectual Property Law'),
  ('LB-IP-001', '21', 'Moral Rights: Independently of the rights provided for in the previous Article and even after the assignment of the said rights, the author shall enjoy the following moral rights: the right to disclose the work and to determine the way and method of such disclosure; the right to claim authorship of the work and to have his name mentioned on every copy of the work each time the work is used in public; the right to use a pseudonym or to remain anonymous; the right to object to any distortion, mutilation or modification of the work which would be prejudicial to his honor, reputation, fame or artistic, literary or scientific position; the right to rescind contracts for the assignment of economic rights even after their publication if rescission is necessary to safeguard his person and reputation or is due to a change in his beliefs or in the circumstances, provided that third parties are compensated for damage resulting from such rescission.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 21', 'Moral Rights', 'Intellectual Property Law'),
  ('LB-IP-001', '22', 'Non-Assignability of Moral Rights: It shall not be permitted to assign or attach the moral rights of the author but the said rights may be transmitted by testamentary disposition or inheritance laws.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 22', 'Non-Assignability of Moral Rights', 'Intellectual Property Law'),
  ('LB-IP-001', '23', 'Personal Use Exception: Without prejudice to the provisions of Article 24 of this Law, any natural person may, for his personal and private use, copy, record or make a single copy of any work protected under this Law without the authorization or consent of the copyright holder and without having to pay him any compensation, provided that the work has been legally published. The use of a copy copied or reproduced inside a company or at any other work place shall not be considered as personal and private use.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 23', 'Personal Use Exception', 'Intellectual Property Law'),
  ('LB-IP-001', '24', 'Limitations on Personal Use Exception: The exception provided for in the previous Article shall not apply if it is prejudicial to the other rights and interests of the copyright holder. In particular, it shall be prohibited to: execute an architectural work in the form of a complete or partial construction; copy, record or reproduce any work of which a limited number of original copies are published; reproduce the whole or a significant part of a book; record or transmit compilations of data of all kinds; record or copy computer programs unless the record or copy is made by the person authorized by the copyright holder to use the program and for the purpose of making a single copy for use in the case of loss or damage of the original copy.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 24', 'Limitations on Personal Use Exception', 'Intellectual Property Law'),
  ('LB-IP-001', '25', 'Educational Institutions — Computer Programs: Non-profit-making educational institutions, universities and public libraries may, without the authorization of the author and without obligation to pay him compensation, reproduce a limited number of computer programs for the purpose of lending them free of charge to students and university people, provided that they possess at least one original copy of the work and provided that the Ministry of Education, the Ministry of Culture and Higher Education and the Ministry of Technical and Vocational Education subsequently issue decrees determining the copying mechanism, the categories of computer programs that may be copied and the number of copies allowed. It shall also be permitted, without the authorization of the author and without obligation to pay him compensation, to use a limited part of any legally published work for purposes of criticism, argumentation or citation or for an educational purpose, provided that the part used does not exceed what is necessary and customary. However, the name of the author and the source shall always be indicated.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 25', 'Educational Institutions — Computer Programs', 'Intellectual Property Law'),
  ('LB-IP-001', '26', 'Educational Reproduction: It shall be permitted, without the authorization of the author and without obligation to pay him compensation, to copy or reproduce articles published in newspapers and magazines or short excerpts of a work, provided that it is done solely for educational purposes and within the necessary limits of such purpose. If the names of the author(s) and the publisher appear on the original work, they shall be mentioned in each and every use of the copy of the article or work.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 26', 'Educational Reproduction', 'Intellectual Property Law'),
  ('LB-IP-001', '27', 'Preservation Copies by Libraries: Non-profit-making public libraries may, without the authorization of the author and without obligation to pay him compensation, make an additional copy of a work to be used in case of loss or damage of the original work, provided that they possess at least one copy of the original work.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 27', 'Preservation Copies by Libraries', 'Intellectual Property Law'),
  ('LB-IP-001', '28', 'Archival Copies of Audiovisual Works: It shall be permitted, by decision of the Minister of Culture and Higher Education, without the authorization of the author and without obligation to pay him compensation, to copy, reproduce or record an audiovisual work of special artistic value in order to keep it in the Ministry''s archives, in case the copyright holder unfairly refuses to authorize the making of the said copy.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 28', 'Archival Copies of Audiovisual Works', 'Intellectual Property Law'),
  ('LB-IP-001', '29', 'Judicial Proceedings: It shall be permitted, without the authorization of the author and without obligation to pay him compensation, to copy, reproduce or record a specific work for use in judicial or administrative proceedings and within the limits required by such proceedings.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 29', 'Judicial Proceedings', 'Intellectual Property Law'),
  ('LB-IP-001', '30', 'Media Reporting — Current Events: The media shall be permitted, without the authorization of the author, without obligation to pay compensation to the author, and within the limits of fair practice, to use short excerpts of works that are displayed or heard during current events in the course of reporting such events in the media, provided that the name of the author and the source are mentioned.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 30', 'Media Reporting — Current Events', 'Intellectual Property Law'),
  ('LB-IP-001', '31', 'Media — Public Spaces: The media shall be permitted, without the authorization of the author and without obligation to pay him compensation, to publish pictures of architectural works, visual artistic works, photographic works or works of applied art, provided that such works are available in places open to the public.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 31', 'Media — Public Spaces', 'Intellectual Property Law'),
  ('LB-IP-001', '32', 'Official Ceremonies and Educational Activities: It shall be permitted, without the authorization of the author and without obligation to pay him compensation, to display or perform a work in public during the following occasions: official ceremonies within the limits required for such ceremonies; activities carried out by educational institutions during which teachers or students use the work, provided that the audience is limited to the teachers, students, students'' parents and persons directly involved in the activities of the said educational institution.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 32', 'Official Ceremonies and Educational Activities', 'Intellectual Property Law'),
  ('LB-IP-001', '33', 'Museum Display: It shall be permitted, without the authorization of the author and without obligation to pay him compensation, to display an artistic work in museums or in exhibitions organized inside museums provided that the museum owns the tangible material that contains the work and that such display is not prejudicial to the legal interests of the author.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 33', 'Museum Display', 'Intellectual Property Law'),
  ('LB-IP-001', '34', 'Sale Catalogues: It shall be permitted, without the authorization of the author and without obligation to pay him compensation, to copy or reproduce an artistic work for the purpose of publishing it in catalogues intended to facilitate the sale of the work, provided that such copying or reproduction is not prejudicial to the legal interests of the author.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 34', 'Sale Catalogues', 'Intellectual Property Law'),
  ('LB-IP-001', '35', 'Holders of Related Rights: Producers of sound recordings, radio and television broadcasting organizations, publishing houses and performers such as actors, musicians, singers, members of musical groups, dancers, artists of puppet shows and circus artists shall be considered as holders of related rights.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 35', 'Holders of Related Rights', 'Intellectual Property Law'),
  ('LB-IP-001', '36', 'Protection of Producers of Sound Recordings: Producers of sound recordings shall enjoy protection in the following cases: (a) if the producer of the sound recording is Lebanese or a national of a State party to the Rome Convention 1961; (b) if the first fixation of sound is undertaken in a State party to the above-mentioned Convention; (c) if the sound recording is first published in a State party to the above-mentioned Convention. If the sound recording is first published in a country that is not party to the Rome Convention and published afterwards, within 30 days of the first publication, in a State that is party to the said Convention, the said sound recording shall be considered as first published in the State party to the Convention.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 36', 'Protection of Producers of Sound Recordings', 'Intellectual Property Law'),
  ('LB-IP-001', '37', 'Protection of Performers: Performers shall enjoy protection in the following cases: (a) when their performance is undertaken in Lebanon or in a State party to the Rome Convention; (b) when their performance is fixed in a sound recording protected under Article 36 of this Law; (c) when their unfixed performance is fixed in a sound recording through a program protected under Article 38 of this Law.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 37', 'Protection of Performers', 'Intellectual Property Law'),
  ('LB-IP-001', '38', 'Protection of Broadcasting Organizations: Broadcasting organizations shall enjoy protection in the following two cases: (a) if the headquarters of the organization is in Lebanon or in a State party to the Rome Convention; (b) if the program is broadcast via a transmission device in Lebanon or in a State party to the Rome Convention.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 38', 'Protection of Broadcasting Organizations', 'Intellectual Property Law'),
  ('LB-IP-001', '39', 'Rights of Performers: Without prejudice to the provisions of Article 15 of this Law, performers shall have the right to authorize or prohibit the following: the broadcasting or communication to the public of their unfixed performance unless the broadcasting or communication is a rebroadcast of a previously authorized broadcast; the fixation or recording of their unfixed performance on any tangible material; the copying, sale or rental of any recordings containing an unauthorized fixation of their performance.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 39', 'Rights of Performers', 'Intellectual Property Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-IP-001', '40', 'Representation of Performers in Joint Works: Performers participating in a joint work or show shall elect by relative majority one person to represent them in the exercise of their rights stated in Article 39 of this Law.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 40', 'Representation of Performers in Joint Works', 'Intellectual Property Law'),
  ('LB-IP-001', '41', 'Rights of Audiovisual Producers: Producers, who are authorized by the performers to undertake the first fixation of an audiovisual work on any tangible matter, shall have the exclusive right to copy, distribute, sell and rent the audiovisual work they have produced and communicate it to the public.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 41', 'Rights of Audiovisual Producers', 'Intellectual Property Law'),
  ('LB-IP-001', '42', 'Rights of Broadcasting Organizations: The radio and television companies, establishments and corporations referred to in Article 38 of this Law, shall have the right to authorize or prohibit the following: the rebroadcasting of their programs by whatever means; the showing of their television programs in places where entrance is permitted upon payment of an entrance fee; the recording of their programs on tangible material for commercial purposes; the copying of unauthorized recordings of their radio and television programs.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 42', 'Rights of Broadcasting Organizations', 'Intellectual Property Law'),
  ('LB-IP-001', '43', 'Rights of Producers of Sound Recordings: Producers of sound recordings shall have the right to authorize or prohibit direct and indirect copying as well as the rental of such recordings for commercial purposes.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 43', 'Rights of Producers of Sound Recordings', 'Intellectual Property Law'),
  ('LB-IP-001', '44', 'Moral Rights of Performers: Performers shall have the right, during their lifetime, to claim authorship of, and to object to any alteration or modification of, their performance. This right shall pass to the heirs of the performer after his death.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 44', 'Moral Rights of Performers', 'Intellectual Property Law'),
  ('LB-IP-001', '45', 'Rights of Publishers: Publishers of written or printed works shall have the right to authorize or prohibit the copying of such works by means of photocopying or commercial exploitation.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 45', 'Rights of Publishers', 'Intellectual Property Law'),
  ('LB-IP-001', '46', 'Form of Related Rights Agreements: Any agreement on related rights shall be concluded in writing.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 46', 'Form of Related Rights Agreements', 'Intellectual Property Law'),
  ('LB-IP-001', '47', 'Exceptions Apply to Related Rights: The exceptions set forth in Articles 23 to 34 of this Law shall apply to the rights provided for in Articles 35 to 45 of this Law.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 47', 'Exceptions Apply to Related Rights', 'Intellectual Property Law'),
  ('LB-IP-001', '48', 'Related Rights Non-Prejudice: The protection of related rights shall not affect any of the rights in respect of original and derivative works protected under this Law. Any interpretation of any of the rights granted under this Chapter shall not affect the rights of the original author.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 48', 'Related Rights Non-Prejudice', 'Intellectual Property Law'),
  ('LB-IP-001', '49', 'Term of Protection — Authors: The term of protection granted under this Law to the economic rights of the author, shall be the life of the author and 50 years after his death, to be computed from the end of the year in which the death has occurred.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 49', 'Term of Protection — Authors', 'Intellectual Property Law'),
  ('LB-IP-001', '50', 'Term of Protection — Joint Authorship: In the case of a work of joint authorship, the term of protection shall be the life of the joint authors and 50 years after the death of the last joint author, to be computed from the end of the year in which the death has occurred. Should one of the authors die without leaving heirs, his share shall pass to the co-authors or to their heirs, unless stated otherwise.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 50', 'Term of Protection — Joint Authorship', 'Intellectual Property Law'),
  ('LB-IP-001', '51', 'Term of Protection — Collective and Audiovisual Works: In the case of collective and audiovisual works, the term of protection shall be 50 years to be computed from the end of the year in which the work has been made available to the public or, failing such event, 50 years from the making of such work, to be computed from the end of the year in which the work has been completed.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 51', 'Term of Protection — Collective and Audiovisual Works', 'Intellectual Property Law'),
  ('LB-IP-001', '52', 'Term of Protection — Anonymous Works: In the case of anonymous or pseudonymous works, the term of protection shall expire 50 years after the work has been lawfully made available to the public. However, if the pseudonym adopted by the author leaves no doubt as to his identity, or if the identity of the author of an anonymous or pseudonymous work is disclosed before the expiration of the 50-year period, the provisions of Article 49 of this Law shall apply. In the case of posthumous works or works published in the name of a legal person, the term of protection shall be 50 years to be computed from the end of the year in which the work was published.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 52', 'Term of Protection — Anonymous Works', 'Intellectual Property Law'),
  ('LB-IP-001', '53', 'Perpetual Moral Rights: All moral rights of authors or performers shall enjoy perpetual protection that shall not be subject to prescription. They shall be transmitted to third parties by testamentary disposition or under inheritance laws.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 53', 'Perpetual Moral Rights', 'Intellectual Property Law'),
  ('LB-IP-001', '54', 'Term of Protection — Performers: All economic related rights of performers shall enjoy protection for a period of 50 years to be computed from the end of the year in which the performance has been carried out.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 54', 'Term of Protection — Performers', 'Intellectual Property Law'),
  ('LB-IP-001', '55', 'Term of Protection — Sound Recordings: The term of protection granted to producers of sound recordings shall be 50 years, to be computed from the end of the year in which the first fixation of sound on tangible material has taken place.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 55', 'Term of Protection — Sound Recordings', 'Intellectual Property Law'),
  ('LB-IP-001', '56', 'Term of Protection — Broadcasting Organizations: The term of protection granted to broadcasting organizations shall be 50 years, to be computed from the end of the year in which the broadcasting of their programs has taken place.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 56', 'Term of Protection — Broadcasting Organizations', 'Intellectual Property Law'),
  ('LB-IP-001', '57', 'Term of Protection — Publishing Houses: The term of protection granted to publishing houses shall be 50 years, to be computed from the end of the year in which the first publication has taken place.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 57', 'Term of Protection — Publishing Houses', 'Intellectual Property Law'),
  ('LB-IP-001', '58', 'Collective Management Associations: Authors and holders of related rights or their universal or particular successors may assign the management of their rights and the collection, in whole or in part, of royalties due to civil associations or companies formed among them.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 58', 'Collective Management Associations', 'Intellectual Property Law'),
  ('LB-IP-001', '59', 'Assignment of Management: Assignment shall be made by way of a written power of attorney drafted before a notary public and explicitly stating all the rights the management of which are assigned to the association or company. The power of attorney shall be limited in time and may include all or part of the present or future works of the author or the holder of related rights. If there is ground for doubt, all the works shall be considered as covered by the power of attorney.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 59', 'Assignment of Management', 'Intellectual Property Law'),
  ('LB-IP-001', '60', 'Requirements for Collective Management Entities: Any association or company willing to undertake the collective management of rights must, before carrying out any activity, deposit with the Ministry of Culture and Higher Education a legal attestation certifying the constitution of the association according to the Law of Associations, or a certificate of registration of the company with the competent registrar, in addition to the following documents: a copy of the Articles of Association; the name and address of the director in charge; the number of authors and holders of related rights that have assigned the management of their rights; a copy of the proxies granted to the association or company; the term of the proxies; the mode of distribution of the royalties collected; the annual budget of the association or company.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 60', 'Requirements for Collective Management Entities', 'Intellectual Property Law'),
  ('LB-IP-001', '61', 'Ministerial Control: The associations or companies for the collective management of rights shall be subject to the authority and control of the Ministry of Culture and Higher Education and they shall provide the Ministry with all necessary records and account books for ministerial control.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 61', 'Ministerial Control', 'Intellectual Property Law'),
  ('LB-IP-001', '62', 'Audit Requirements: Each association or company must appoint a certified accountant to audit its records and submit an annual report to the General Assembly. However, the association or company must obtain an annual report from another certified accountant.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 62', 'Audit Requirements', 'Intellectual Property Law'),
  ('LB-IP-001', '63', 'General Assembly: Each association or company must hold at least one general assembly a year to vote on the report of the president, the financial reports, the balance sheet of the previous year and the budget of the following year.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 63', 'General Assembly', 'Intellectual Property Law'),
  ('LB-IP-001', '64', 'Legal Consultant: Pursuant to the legislation regulating the legal profession, each association or company must appoint a lawyer from the Bar as its legal consultant.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 64', 'Legal Consultant', 'Intellectual Property Law'),
  ('LB-IP-001', '65', 'Prosecution for Infractions: If the association or company commits a serious infraction or in the event of a repetition of a legal or regulatory infraction, the Minister of Culture or Higher Education may refer the file to the public prosecutor for action.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 65', 'Prosecution for Infractions', 'Intellectual Property Law'),
  ('LB-IP-001', '66', 'Implementing Regulations: The Council of Ministers shall, within three months of the publication of this Law in the official gazette and upon the recommendation of the Minister of Culture and Higher Education, issue a decree prescribing the mode of establishment and functioning of the said associations and companies and the manner in which the Ministry of Culture and Higher Education shall monitor their activities and establish violations.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 66', 'Implementing Regulations', 'Intellectual Property Law'),
  ('LB-IP-001', '67', 'Responsibilities of Collective Management Entities: The associations or companies for the collective management of rights shall have the following responsibilities: to arrange contracts with the parties using the work and to determine the royalties to be collected; to distribute the royalties collected among the eligible parties; to take all administrative, judicial, arbitral and amicable measures to protect the legitimate rights of their clients and to collect royalties due; to obtain from the users of the work all necessary information for the computation, collection and distribution of royalties.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 67', 'Responsibilities of Collective Management Entities', 'Intellectual Property Law'),
  ('LB-IP-001', '68', 'Obligation to Contract: The associations or companies for the collective management of rights shall not have the right to refuse to arrange contracts under Article 67 of this Law with the users of the works without a legitimate reason.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 68', 'Obligation to Contract', 'Intellectual Property Law'),
  ('LB-IP-001', '69', 'User Reporting Obligations: The user of the work must submit to the association or company a list of the exploitations that he has undertaken such as the copying, sale, rental or television or radio broadcasting of the work and he shall indicate the number of copies, the number of public displays of the work or the number of television or radio broadcasts.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 69', 'User Reporting Obligations', 'Intellectual Property Law'),
  ('LB-IP-001', '70', 'Obligation to Administer Rights: Companies and associations shall not have the right to refuse to administer the rights of an author or collect the royalties owed to him without a legitimate reason.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 70', 'Obligation to Administer Rights', 'Intellectual Property Law'),
  ('LB-IP-001', '71', 'Annual Reports to Rights Holders: Each company or association must submit an annual report to the authors that have empowered it to administer their rights and collect royalties owed to them so that the authors can express their opinions as to the amounts collected, the method of collection and distribution and other administrative issues. The association must take these comments into account when formulating or modifying its methods of collection and administration.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 71', 'Annual Reports to Rights Holders', 'Intellectual Property Law'),
  ('LB-IP-001', '72', 'Right to Inspect Accounts: The authors, the holders of related rights and their representatives shall have the right to examine the accounts of the company or the association to which they are affiliated whenever they deem it necessary.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 72', 'Right to Inspect Accounts', 'Intellectual Property Law'),
  ('LB-IP-001', '73', 'Notification of Published Works: The authors and the holders of related rights which have empowered a specific association or company to administer their rights and collect their royalties must inform the association or the company in writing of the works they have published or those they intend to publish after the date on which they have authorized the company or the association to administer their rights and collect their royalties.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 73', 'Notification of Published Works', 'Intellectual Property Law'),
  ('LB-IP-001', '74', 'Distribution of Royalties: Collected amounts shall, at least once a year, be distributed among right holders in proportion to the actual use of their works.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 74', 'Distribution of Royalties', 'Intellectual Property Law'),
  ('LB-IP-001', '75', 'Cancellation of Power of Attorney: The power of attorney may be cancelled by the author, the holder of related rights or the association or company provided that there is a legitimate reason for such cancellation and that the other party is served notice three months before the end of the year. The cancellation shall have effect as of the end of the year in which the other party has been served notice of the intention to cancel.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 75', 'Cancellation of Power of Attorney', 'Intellectual Property Law'),
  ('LB-IP-001', '76', 'Deposit of Works: Works, sound recordings, performances, and radio or television programs shall be deposited with the Intellectual Property Protection Office at the Ministry of Economy and Trade. The deposit shall constitute a presumption as to the ownership by the depositor of the work, the sound recording, the performance or the radio or television program. Such presumption may be refuted by all available means.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 76', 'Deposit of Works', 'Intellectual Property Law'),
  ('LB-IP-001', '77', 'Deposit Application Requirements: Copyright holders, holders of related rights or their particular or universal successors who wish to make a deposit must submit to the Intellectual Property Protection Office an application signed by them or their agent containing the following information: the title and the type of work, sound recording, performance or radio or television program; the name, title and address of the author or the holder of related rights; if the depositor is a person other than the author or the holder of related rights, the type of document on the basis of which the depositor has submitted the application for deposit; where necessary, the name and address of the person responsible for the physical execution of the work (the printer, the molder, etc.). The application for deposit must be accompanied by: (a) if the applicant is a person other than the author, a copy or a summary of the document on the basis of which the deposit is made; (b) three copies of the work or the subject of the related right.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 77', 'Deposit Application Requirements', 'Intellectual Property Law'),
  ('LB-IP-001', '78', 'Deposit Fees: The application for deposit shall not be accepted unless it is accompanied by the prescribed fee set out in this Article. The fees charged by the Intellectual Property Protection Office shall be as follows: deposit of a printed work, LBP 50,000; deposit of a motion picture, video film or sound recording, LBP 175,000; deposit of a daily or periodic publication (for one year), LBP 75,000; deposit of a picture, drawing, map, post card, photograph or daily or periodic publication (1 copy), LBP 25,000; deposit of any other material not mentioned above, LBP 50,000; recordation of a contract of deposit with the Office, LBP 50,000; facsimile copy of a certificate of registration, LBP 25,000.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 78', 'Deposit Fees', 'Intellectual Property Law'),
  ('LB-IP-001', '79', 'Deposit Certificate: The application for deposit shall be registered at the Intellectual Property Protection Office. A certificate shall be delivered to the applicant mentioning the information stated in the application and it shall be accompanied by one of the three copies deposited with the Office. The certificate shall be dated, sealed and signed by the head of the said Office. The first certificate shall be granted free of charge and the Office shall charge the prescribed fee referred to in the previous Article for subsequent requested copies of this certificate.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 79', 'Deposit Certificate', 'Intellectual Property Law'),
  ('LB-IP-001', '80', 'Recordation of Contracts: Any contract concluded with regard to any work, sound recording, performance or radio or television program registered at the Intellectual Property Protection Office may also be recorded with the said Office.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 80', 'Recordation of Contracts', 'Intellectual Property Law'),
  ('LB-IP-001', '81', 'Provisional Measures: Where there is ground for suspecting an imminent infringement of copyright or a related right, the holder of these rights or his public or private successors, in particular the associations or companies for the collective administration of rights, shall have the right to take all necessary provisional measures to prevent such infringement. For this purpose, the judge of expedited matters may take all decisions authorized by the law, in particular, ex-parte decisions, in order to ensure the protection of the right or the work that is likely to be infringed and all the other works owned by the author or the holder of related rights. The judge of expedited matters may impose coercive measures to enforce his decisions. In addition, the president of the competent court of first instance or the competent public prosecutor shall have the right to take the provisional measures referred to above.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 81', 'Provisional Measures', 'Intellectual Property Law'),
  ('LB-IP-001', '82', 'Temporary Seizure: The judge of expedited matters, the president of the court of first instance or the public prosecutor may temporarily seize material constituting evidence of an infringement of copyright or a related right and shall leave it in the custody of the defendant.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 82', 'Temporary Seizure', 'Intellectual Property Law'),
  ('LB-IP-001', '83', 'Right to Sue for Infringement: In case of infringement of copyright or a related right, the holders of these rights may have recourse to the competent judicial authority and seek the cessation of the infringement and the prevention of any future infringement.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 83', 'Right to Sue for Infringement', 'Intellectual Property Law'),
  ('LB-IP-001', '84', 'Compensation for Infringement: Any person who infringes copyright or a related right shall be required to pay fair compensation to the right holder for the material or moral injury and damage incurred. The amount of such compensation shall be determined by the court based on the commercial value of the work, the damage and lost profit incurred by the right holder and the material profit realized by the infringer. The court may order the seizure of the subject matter in dispute and the equipment and devices used to commit the infringement.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 84', 'Compensation for Infringement', 'Intellectual Property Law'),
  ('LB-IP-001', '85', 'Criminal Sanctions — Forgery and Imitation: Irrespective of whether the work has fallen into the public domain or not, shall be liable to imprisonment for a term varying from one month to three years and/or to a fine varying from LBP 5 to 50 million, any person who: fraudulently puts or instructs another person to put a false name on a literary or artistic work; fraudulently imitates the signature or the logo of the author with intent to mislead the buyer; knowingly imitates a literary or artistic work; knowingly sells, possesses, offers for sale or makes available an imitated or a plagiarized work. The sanction shall be doubled in the event of a repetition of the offence.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 85', 'Criminal Sanctions — Forgery and Imitation', 'Intellectual Property Law'),
  ('LB-IP-001', '86', 'Criminal Sanctions — Willful Infringement: Any person who, knowingly and with intent to make a profit, infringes or attempts to infringe copyright or related rights provided for in this Law shall be liable to imprisonment for a term varying from one month to three years and/or to a fine varying from LBP 5 to 50 million. The sanction shall be doubled in the event of a repetition of the offence. The competent court may order the closure of the premises, the commercial establishment or the radio or television station that infringes copyright for a period varying from one week to one month and the destruction of all unauthorized copies and all the equipment and the devices used to produce such copies. The court may also order that its decision be published in two local newspapers at the expense of the defendant.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 86', 'Criminal Sanctions — Willful Infringement', 'Intellectual Property Law'),
  ('LB-IP-001', '87', 'Unauthorized Reception Devices: Any person who manufactures or imports for purposes of sale or rental, offers for sale or rental, possesses for the purpose of sale or rental, sells, installs or rents any device, equipment or machine manufactured in whole or in part to receive illicitly any radio or television broadcast or transmission destined to that section of the public that receives the said broadcast or transmission on payment of a set fee, shall be liable to imprisonment for a term varying from one month to three years and/or to a fine varying from LBP 5 to 50 million. The sanction shall be doubled in the event of a subsequent offence.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 87', 'Unauthorized Reception Devices', 'Intellectual Property Law'),
  ('LB-IP-001', '88', 'Facilitating Unauthorized Reception: Any person who arranges or facilitates for third parties the reception of the transmission or broadcast referred to in the previous Article shall be liable to imprisonment for a term varying from one month to three years and/or to a fine varying from LBP 5 to 50 million. The sanction shall be doubled in the event of a subsequent offence.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 88', 'Facilitating Unauthorized Reception', 'Intellectual Property Law'),
  ('LB-IP-001', '89', 'Initiation of Legal Action: With regard to the foregoing violations, legal action may be instituted by the public prosecutor ex officio or at the request of the person suffering damage or the president of the Intellectual Property Protection Office.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 89', 'Initiation of Legal Action', 'Intellectual Property Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-IP-001', '90', 'Communication of Judicial Decisions: The court shall communicate any judicial decision issued with regard to the foregoing infringements to the Intellectual Property Protection Office within 15 days of the date of the decision.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 90', 'Communication of Judicial Decisions', 'Intellectual Property Law'),
  ('LB-IP-001', '91', 'Prohibition on Import of Imitations: It shall be strictly prohibited to import, consign to a warehouse or a free zone or transit sound recordings, or works that are imitations of sound recordings or works enjoying legal protection in Lebanon. Such sound recordings and works shall be seized wherever they are found.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 91', 'Prohibition on Import of Imitations', 'Intellectual Property Law'),
  ('LB-IP-001', '92', 'Enforcement Powers: The persons mentioned below shall have authority to identify, inventory and sample suspect objects. These persons shall be: police and customs officers and employees of the Intellectual Property Protection Office sworn in to that effect. These employees shall perform their duties pursuant to an order or a mandate issued by the public prosecutor or the Intellectual Property Protection Office and they shall notify the Office of all violations of the provisions of this Law that come to their attention. Sworn-in employees of the Intellectual Property Protection Office shall have police powers with regard to the implementation of the provisions of this Law. Suspect articles may be seized, inventoried and sampled wherever they are found. A report must be drawn up of all sampling and inventorying containing: the name, surname, title and place of residence of the employee who has drawn up the report; the authority that has issued the order and the date it was communicated to the employee; the date, time and location of the operation; the name, surname, nationality, place of residence and profession of the person on whose premises the operation was carried out; a detailed list of the suspect articles stating their number, kind and specifications; the signature of the person in whose possession the articles or goods were found; the signature of the officer who has drawn up the report. Civil action or penal proceedings must be filed with the competent court within 15 days of the date of the report otherwise the whole operation will be considered as void.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 92', 'Enforcement Powers', 'Intellectual Property Law'),
  ('LB-IP-001', '93', 'Seizure by Court Order: The court may, at the request of the plaintiff and before rendering its final judgment order the seizure of all or some of the articles stated in the report and inventory. In such case, the court may order the plaintiff to deposit with the court, prior to the seizure, a guarantee fixed by the court based on the value of the articles to be seized. The order shall designate the employee mandated to carry out the seizure, the place where seized articles will be kept and the official receiver of such articles appointed by the court.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 93', 'Seizure by Court Order', 'Intellectual Property Law'),
  ('LB-IP-001', '94', 'Seizure Report: The officer who has carried out the seizure shall immediately draw up a report in two copies, one of which should be delivered to the person whose goods have been seized. The report shall be drawn up as prescribed in Article 92 and it shall be accompanied by an inventory of the articles seized. The person whose goods have been seized, shall sign both copies and if he refuses or fails to sign, his refusal or failure shall be mentioned in the space provided for the signature.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 94', 'Seizure Report', 'Intellectual Property Law'),
  ('LB-IP-001', '95', 'Documents Provided to Seized Party: The person whose goods have been seized must be provided with the following documents: 1. the order of seizure; 2. the document that establishes the deposit of the guarantee with the court if the court orders the deposit of such guarantee; 3. the inventory of the articles seized; 4. the report of seizure.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 95', 'Documents Provided to Seized Party', 'Intellectual Property Law'),
  ('LB-IP-001', '96', 'Investigation Fee: If the Intellectual Property Protection Office carries out an investigation at the request of the person suffering damages, it shall charge him a LBP 100,000 fixed fee.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 96', 'Investigation Fee', 'Intellectual Property Law'),
  ('LB-IP-001', '97', 'Complementary Penalties: The judgment rendered with regard to the above-mentioned proceedings shall provide for the imposition of the following complementary penalties: 1. the judgment shall be posted at the places designated by the court and it shall be published at the expense of the defendant in two local newspapers designated by the court that has rendered the judgment; 2. if the losing party represents a newspaper, a magazine or a radio or television station, the judgment must be published in this newspaper, magazine or radio or television station in addition to the two newspapers mentioned above.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 97', 'Complementary Penalties', 'Intellectual Property Law'),
  ('LB-IP-001', '98', 'Protection of Pre-Existing Works: All works, whether published or not, created before the entry into force of this Law, shall enjoy the period of protection prescribed in this Law provided that they have not fallen into the public domain by the effective date of this Law. The period of protection that has lapsed before the issuance of this Law shall be deducted from the period of protection provided for in this Law.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 98', 'Protection of Pre-Existing Works', 'Intellectual Property Law'),
  ('LB-IP-001', '99', 'Mandatory Deposit with Ministry of Culture: Any author, producer or publisher of any book or publication must send, free of charge, to the Ministry of Culture and Higher Education five copies of the said work.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 99', 'Mandatory Deposit with Ministry of Culture', 'Intellectual Property Law'),
  ('LB-IP-001', '100', 'Repeal of Earlier Provisions: Articles 137 to 180 inclusive of Decision No. 2385, dated January 17, 1924 (amended), and Articles 722 to 729 inclusive, of the Penal Code shall be repealed.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 100', 'Repeal of Earlier Provisions', 'Intellectual Property Law'),
  ('LB-IP-001', '101', 'Entry into Force: This law shall be published in the official gazette and it shall have effect two months after its publication.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999, Article 101', 'Entry into Force', 'Intellectual Property Law'),
  ('LB-IP-001', NULL, 'Lebanon''s principal copyright statute, enacted April 3, 1999 (Law No. 75). Replaced the Ottoman-era copyright provisions and aligned Lebanon with the Berne Convention and TRIPs Agreement requirements. Contains 101 articles covering definitions, protected works, copyright holders, economic and moral rights, exceptions and limitations, related rights (performers, producers, broadcasters, publishers), terms of protection, collective management associations, deposit requirements, and enforcement. Repealed Articles 137-180 of Resolution No. 2385/1924 and Articles 722-729 of the Penal Code.', 'en', 'Law on the Protection of Literary and Artistic Property No. 75/1999 — Historical Context', 'Historical context and overview', 'Intellectual Property Law'),
  ('LB-IP-002', '48', 'Right of Usufruct in Designs: Any inventor of a drawing or a design, or those who have rights thereto, shall alone have the right of usufruct thereto, and to sell, or offer it for sale, and to authorize its sale, provided that such drawing or design is, previously filed.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 48', 'Right of Usufruct in Designs', 'Intellectual Property'),
  ('LB-IP-002', '49', 'Eligible Designs: The Drawings and designs which contain the two advantages of being new and invented, that is, they include external characteristics to make them of special form which differentiates them from known drawings and designs may be filed.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 49', 'Eligible Designs', 'Intellectual Property'),
  ('LB-IP-002', '52', 'Registration Creates Presumption: The registration shall not grant the ownership of a drawing or a design, but it only creates a presumption of ownership in favour of the person who makes the registration; however the real ownership shall only be acquired through the use of the drawing or design.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 52', 'Registration Creates Presumption', 'Intellectual Property'),
  ('LB-IP-002', '53', 'Filing Application for Designs: The inventor of a drawing or design or his agent or official proxy shall send the filing application to the Director of the Protection Bureau. Such an application shall contain the following instructions, otherwise it is considered null and void: Name, title, nationality and domicile of the inventor. If necessary, the same information about the authorized agent or proxy. Number and type of the things needed to be filed, on condition this number does not exceed one hundred. The requested period of protection. When necessary, things to be advertised should be mentioned.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 53', 'Filing Application for Designs', 'Intellectual Property'),
  ('LB-IP-002', '62', 'Duration of Filing: The open or confidential filing requested to be effected before or on the lapsed of the first five years shall remain for the period of twenty five years, starting from the date of the first filing. At the lapsed of these twenty five years or before its lapsed the depositor or those who have rights therein, may ask for extension of filing for another twenty five years.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 62', 'Duration of Filing', 'Intellectual Property'),
  ('LB-IP-002', '68', 'Definition of Trademarks: Names written in a way which distinguishes them from others, titles, nomenclatures, symbols, stamps, letters, protruding marks and drawings, small drawings and figures, in general, any sign of any kind intended to bring benefit to the consumer, the factory owner and the dealer, by distinguishing between things and showing the identity, source, origin of goods, and the industrial, commercial or agricultural product, or the products of forests and metals shall be considered as trademarks for factories or trade.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 68', 'Definition of Trademarks', 'Intellectual Property'),
  ('LB-IP-002', '69', 'Optional Trademark: A trademark is optional unless there are legal provisions to the contrary.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 69', 'Optional Trademark', 'Intellectual Property'),
  ('LB-IP-002', '70', 'Individual or Collective Mark: A mark can be individual or collective; professional, regional, agricultural or industrial groupings authorized by the government, may acquire a collective mark to guarantee the good manufacture or the origin of their goods or products; only the members of these groupings will be able to use this collective mark independently of the individual mark that each one of them will be able to have.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 70', 'Individual or Collective Mark', 'Intellectual Property'),
  ('LB-IP-002', '71', 'Prohibited Content in Trademarks: The trademark shall not contain any national or foreign emblems. It shall not include, as well, a word, signal or symbol which is revolutionary or in breach of the public order or morality.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 71', 'Prohibited Content in Trademarks', 'Intellectual Property'),
  ('LB-IP-002', '72', 'Filing Required for Ownership: Personal ownership of a trademark shall not be claimed unless such a trademark has been previously filed in the Protection Bureau as per the provisions of Article (79) and subsequent articles thereto.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 72', 'Filing Required for Ownership', 'Intellectual Property'),
  ('LB-IP-002', '74', 'Right of First User: If a trademark legally filed does not cause an acknowledged true objection within the five years period following the filing, it shall not be possible to object afterwards to the first depositor concerning the right of ownership of this trademark due to precedence of its use, unless it is proved in written deeds that the depositor was not ignorant or unaware at the time of effecting the filing that the trademark belonged to the person who used it first.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 74', 'Right of First User', 'Intellectual Property'),
  ('LB-IP-002', '76', 'Transfer of Trademark: A filed trademark may be transferred by inheritance, sale and assignment with its price or free of charge, with or without the commercial business. Any transfer of a filed trademark, in order to be a pretext or excuse against others, shall be notified to the Bureau.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 76', 'Transfer of Trademark', 'Intellectual Property'),
  ('LB-IP-002', '78', 'Filing Duration for Trademarks: Filing duration shall be fifteen years, which may always be renewed for subsequent duration of fifteen years each provided that the payment of the fees mentioned herein under is made.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 78', 'Filing Duration for Trademarks', 'Intellectual Property'),
  ('LB-IP-002', '79', 'Trademark Filing Application: The trademark owner or his agent shall send a handwritten application to the Director of the Bureau, mentioning the following: Name, title, surname, nationality and domicile of the depositor. When necessary, same data about the agent or proxy. Type of trade or industry which is practiced by the depositor. A very brief description of the trademark. Products or goods on which the same trademark is put abroad. The application shall be accompanied with: Two copies of the trademark design. The original copy of the power of attorney. The Cliché of the trademark.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 79', 'Trademark Filing Application', 'Intellectual Property'),
  ('LB-IP-002', '97', 'Definition of Unfair Competition: The following shall be considered unfair competition: Any violation of the decision in which one of the necessary requirements for the application of the sanctions provided for in Section 6 below is missing. Any act subject to the free jurisdiction of courts and determined to be unfair competition.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 97', 'Definition of Unfair Competition', 'Intellectual Property'),
  ('LB-IP-002', '98', 'Unfair Competition Actions: Acts of unfair competition may only be subject to legal proceedings for cessation of competition or prejudice and for seeking indemnity except where such acts are considered violations subject to penalties under criminal codes or under the provisions of this decision.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 98', 'Unfair Competition Actions', 'Intellectual Property'),
  ('LB-IP-002', '105', 'Trademark Counterfeiting – Penalties: Any person who determines in whatever manner or way that an unregistered mark is registered; Any person who deliberately imitates or uses a registered mark without the authorization of the owner; Any person who affix to his goods or products a mark belonging to another person; Any person who deliberately sells or offers for sale a product bearing a counterfeited mark; Any person who delivers a product other than the one requested under a specific mark; Shall be liable to a fine varying from LBP 50 to LBP 500 and to imprisonment for a term varying from 3 months to 3 years or to one of the foregoing sanctions.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 105', 'Trademark Counterfeiting – Penalties', 'Intellectual Property'),
  ('LB-IP-002', '106', 'Fraudulent Imitation of Marks: Any person who makes a fraudulent imitation of a mark, without counterfeiting the mark, with the intent to deceive the public or uses a fraudulent imitation of a mark; Any person who uses a mark bearing fraudulent indications of such a nature as to mislead the public as to the nature of the product requested; Any person who deliberately sells or offers for sale a product bearing a fraudulent imitation; Shall be liable to a fine equivalent to LBP 50 to 250 and to imprisonment for a term varying from two months to two years or to one of the foregoing sanctions.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 106', 'Fraudulent Imitation of Marks', 'Intellectual Property'),
  ('LB-IP-002', '107', 'Assessment of Counterfeiting: Courts shall evaluate fraudulent imitation and counterfeit from the point of view of the ordinary consumer taking into account the overall similarity regardless of minor differences between the original mark and the disputed mark.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 107', 'Assessment of Counterfeiting', 'Intellectual Property'),
  ('LB-IP-002', '111', 'Industrial Design Infringement: Any deliberate injury to the industrial design rights guaranteed under this decision shall entail the imposition of a fine varying from LBP 25 to LBP 250. If the offender helps or has helped in the past in whatever manner the injured person, he shall be liable to imprisonment for a term varying from two to six months.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 111', 'Industrial Design Infringement', 'Intellectual Property'),
  ('LB-IP-002', '116', 'Seizure Even on Acquittal: Even in case of acquittal, seizure of the items that have caused or have been used to cause injury to the rights guaranteed by this decision should be made. The court shall in all cases order the destruction of the marks, symbols, signs and notices that are contrary to this decision.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 116', 'Seizure Even on Acquittal', 'Intellectual Property'),
  ('LB-IP-002', '118', 'Secondary Penalties: All verdicts pronounced with regard to any of the offences stipulated in this decision or in any other decision related to unfair competition shall entail the following secondary sanctions: Non-eligibility of the condemned for membership in chambers of commerce, associations, research committees, syndicates, cooperatives and any elective assembly in general. The verdict shall be posted in the places designated by the court and published in two different journals.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 118', 'Secondary Penalties', 'Intellectual Property'),
  ('LB-IP-002', '135', 'Repealing Provision: Shall be repealed as of the effective date of this Decision, all the previous laws, decrees, regulations and decisions dealing with the same issue, including: The Ottoman law of March 9/1880 on patentable inventions, the Ottoman law of May 11/1888, the Ottoman Decision of October 8, 1888 on trade marks and brand names, and various other prior decisions.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946), Article 135', 'Repealing Provision', 'Intellectual Property'),
  ('LB-IP-002', NULL, 'Resolution No. 2385 was promulgated on January 17, 1924 during the French Mandate period, establishing Lebanon''s first comprehensive framework for commercial and industrial property rights including patents, industrial designs, and trademarks. It was subsequently amended multiple times, most notably by Resolution No. 84 of December 30, 1926, Resolution No. 170 of December 6, 1937, and the Law of January 31, 1946. The resolution established the Protection Bureau as the registration authority.', 'en', 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946) — Historical Context', 'Historical context and overview', 'Intellectual Property'),
  ('LB-PROC-001', '1', 'Purpose of the Code: The purpose of the Code of Criminal Procedure is to regulate criminal justice and to define its scope and the measures to be taken in criminal investigations and trials. It also sets out the types of appeal available against judgements and decisions rendered. A further purpose is to regulate the procedures for bringing to light the facts and evidence of criminal offences in application of criminal legislation.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 1', 'Purpose of the Code', 'Procedural Law'),
  ('LB-PROC-001', '2', 'Criminal Courts: Ordinary criminal trials are divided into the following categories: (a) A Single Judge hears all cases concerning misdemeanours and contraventions unless special provision is made for exceptions. The Public Prosecution Service is not represented; (b) Each chamber of an Appeal Court is composed of a President and two Auxiliary Judges. The Public Prosecution Service is represented by an Appeal Court Prosecutor, an Appeal Court Advocate-General, the Financial Prosecutor or an Advocate-General attached to the Financial Prosecutor''s Office; (c) Each chamber of the Court of Cassation is composed of a President and two Auxiliary Judges. The Public Prosecution Service is represented by the Public Prosecutor at the Court of Cassation or an Advocate-General of the Court of Cassation.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 2', 'Criminal Courts', 'Procedural Law'),
  ('LB-PROC-001', '3', 'The Investigation Department in each governorate is composed of the First Investigating Judge and one or more Investigating Judges, depending on the provisions of the Administration of Justice Act. A chamber of the civil Appeal Court performs the functions of an Indictment Division in each governorate.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 3', 'Investigation Department', 'Procedural Law'),
  ('LB-PROC-001', '4', 'The Administration of Justice Act establishes the procedures governing the appointment of judges, the number of chambers of the Court of Cassation in the capital city, and the number of Appeal Court chambers, Single Judges, Investigating Judges and Advocates-General in the capital city, the governorates and the districts.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 4', 'Administration of Justice Act', 'Procedural Law'),
  ('LB-PROC-001', '5', 'Public Prosecution and Civil Actions: Responsibility for initiating a public prosecution, the purpose of which is to prosecute perpetrators of crimes and their accomplices and to subject them to penalties and other measures, lies with the Judges of the Public Prosecution Service in accordance with this Code. Every aggrieved person also has the right to bring a civil action for damages suffered as a result of an offence. Any person against whom a public prosecution is initiated shall be termed a defendant; a person charged with a misdemeanour shall be termed a charged person; and a person accused of committing a felony shall be termed an accused.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 5', 'Public Prosecution and Civil Actions', 'Procedural Law'),
  ('LB-PROC-001', '6', 'The Public Prosecutor''s Office shall be responsible for exercising the public prosecution. It may not discontinue the proceedings or arrange an amicable settlement. A civil action may be initiated following the public prosecution before the judicial authority responsible for the latter. Such an action may also be brought separately before the competent civil authority.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 6', 'Public Prosecutor''s Office', 'Procedural Law'),
  ('LB-PROC-001', '7', 'Civil Party Status: Any aggrieved person may assume the status of a civil party before the First Investigating Judge in the case of a felony or misdemeanour or before the Single Judge in the case of a misdemeanour or contravention. A civil party may also be joined to the public prosecution before the Criminal Court. An aggrieved person may file suit to bring a public prosecution if the Public Prosecutor''s Office has not done so. The party may withdraw the civil action or reach an amicable settlement without thereby affecting the public prosecution unless the circumstances are such that the extinction of the civil action entails the extinction of the public prosecution.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 7', 'Civil Party Status', 'Procedural Law'),
  ('LB-PROC-001', '8', 'Priority Between Civil and Criminal Courts: An aggrieved person who has brought an action before the competent civil court may not abandon the case and bring an action before a criminal court unless the Public Prosecutor''s Office initiated a public prosecution on a date subsequent to that on which the party brought the action before the civil court, provided that a final judgement has not been delivered in the civil proceedings. The competent civil authority shall not proceed with a civil action until the public prosecution has been finally disposed of; a court of summary jurisdiction shall be authorized to take summary measures even if a civil action has been brought before the criminal court.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 8', 'Priority Between Civil and Criminal Courts', 'Procedural Law'),
  ('LB-PROC-001', '9', 'Jurisdiction: The public prosecution shall be initiated before the criminal authority which has jurisdiction in the area in which the crime was committed, the place of residence of the defendant, or the place in which the defendant was arrested.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 9', 'Jurisdiction', 'Procedural Law'),
  ('LB-PROC-001', '10', 'Extinction of Public Prosecution: The public prosecution shall be extinguished under the following circumstances: (a) Death of the defendant; (b) A general amnesty; (c) Expiry of a prescription period of ten years in the case of a felony, three years in the case of a misdemeanour, and one year in the case of a contravention; (d) Extinction of the civil action in the cases specified by law. The prescription period shall begin to run in the case of one-time offences on the date of their occurrence. In the case of continuing, persistent or successive offences, the prescription period shall begin to run on the date on which the criminal situation comes to an end. The expiry of the prescription period for the public prosecution shall entail the suspension of all acts of prosecution, investigation or trial. The prescription period shall be suspended if it proves impossible, because of force majeure, to perform any act of prosecution, investigation or trial, and it shall resume as soon as the impediment is eliminated.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 10', 'Extinction of Public Prosecution', 'Procedural Law'),
  ('LB-PROC-001', '11', 'Public Prosecution Service Structure: Public prosecutions at the Court of Cassation are conducted by the Public Prosecutor with the assistance of Advocates-General. The duties of the Financial Prosecutor''s Office at the Court of Cassation are performed by the Public Prosecutor with the assistance of Advocates-General. The duties of the Public Prosecutor''s Office at the Appeal Court are performed by the Public Prosecutor with the assistance of one or more Advocates-General. The work of the Public Prosecutor''s Office at the Military Court is carried out by a Government Commissioner, who is subject to the authority of the Public Prosecutor at the Court of Cassation and is assisted by one or more Advocates-General.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 11', 'Public Prosecution Service Structure', 'Procedural Law'),
  ('LB-PROC-001', '12', 'Department Heads: Each Public Prosecutor heads a department and assigns activities falling within his remit to the Advocates-General who assist him in his duties.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 12', 'Department Heads', 'Procedural Law'),
  ('LB-PROC-001', '13', 'Public Prosecutor at Court of Cassation: The Public Prosecutor''s Office at the Court of Cassation is headed by a Public Prosecutor who is appointed by a decree of the Council of Ministers based on a proposal by the Minister of Justice. He is assisted by Advocates-General. The authority of the Public Prosecutor at the Court of Cassation extends to all Judges of the Public Prosecution Service, including the Government Commissioner at the Military Court. He shall provide them with written or oral instructions for the conduct of the public prosecution. They shall be free, however, to make statements at trial hearings. The prosecutor shall refer to them, depending on their area of jurisdiction, the reports and records produced with respect to any offence, and request them to conduct the requisite public prosecution. (As amended by Act No. 359/2001)', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 13', 'Public Prosecutor at Court of Cassation', 'Procedural Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-PROC-001', '14', 'Minister of Justice — Prosecution Requests: The Minister of Justice may request the Public Prosecutor at the Court of Cassation to prosecute any offences of which he has knowledge. The latter shall be entitled, if necessary, to undertake the investigation directly or through his assistants – the Judges of the Public Prosecution Service assigned to assist him or members of the Judicial Police force subject to his authority – but he shall not be entitled to lay charges. (As amended by Act No. 359/2001)', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 14', 'Minister of Justice — Prosecution Requests', 'Procedural Law'),
  ('LB-PROC-001', '15', 'Oversight of Judicial Police: The Public Prosecutor at the Court of Cassation oversees the actions of Judicial Police officers in the performance of their duties as assistants to the Public Prosecutor''s Office. He may make such observations as he sees fit to their supervisors regarding the work referred to above, and may request the Appeal Court Prosecutor, the Financial Prosecutor or the Government Commissioner at the Military Court to take action against any officer who commits a criminal offence during the performance of his duties or in connection with their performance, without having to obtain prior permission.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 15', 'Oversight of Judicial Police', 'Procedural Law'),
  ('LB-PROC-001', '16', 'Reporting to Public Prosecutor: The Appeal Court Prosecutor, the Financial Prosecutor, the Government Commissioner at the Military Court, the Director-General of the Internal Security Forces, the Director-General of General Security and the Director-General of State Security shall inform the Public Prosecutor at the Court of Cassation of serious offences of which they have knowledge and shall comply with his instructions in this regard. The Public Prosecutor at the Court of Cassation may inspect the file pertaining to an investigation being conducted by an Investigating Judge and ask the responsible Public Prosecutor to show that the submissions comply with his written instructions. He may admonish a members of the Public Prosecution Service for any shortcomings in their work, or he may recommend to the Judicial Inspectorate that they be referred to the Disciplinary Board.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 16', 'Reporting to Public Prosecutor', 'Procedural Law'),
  ('LB-PROC-001', '17', 'Duties of Public Prosecutor at Court of Cassation: The Public Prosecutor at the Court of Cassation shall undertake the following activities: (a) Apply for the setting aside of judgements and decisions in criminal proceedings in accordance with the procedures laid down in this Code; (b) Demand that a judicial authority be designated and that a case be transferred from one court to another; (c) Prosecute offences referred to the Judicial Council; (d) Prosecute offences committed by members of the national legal service either within or outside the context of their judicial office; (e) Represent the Public Prosecutor''s Office at the Court of Cassation and before the Judicial Council; (f) Deal with requests for the extradition of criminals and forward them to the Minister of Justice together with his observations; (g) Compile a detailed report for insertion in the case file of persons sentenced to death when the case is referred to the Pardon Commission; (h) Any other duties and powers mentioned in this Code and in any other legislation.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 17', 'Duties of Public Prosecutor at Court of Cassation', 'Procedural Law'),
  ('LB-PROC-001', '18', 'The Financial Prosecutor is appointed by a decree of the Council of Ministers based on a proposal by the Minister of Justice. The Financial Prosecutor shall exercise, within the limits of the duties specified in this Code, the same powers as those of the Public Prosecutor at the Court of Cassation.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 18', 'Financial Prosecutor', 'Procedural Law'),
  ('LB-PROC-001', '19', 'Jurisdiction of Financial Prosecutor: The Financial Prosecutor has the authority to prosecute the following offences: (a) Offences arising from breaches of the provisions of the legislation relating to duties and taxes in the various public utilities and establishments and municipalities, including state and municipal taxes, customs duties, and telecommunication and wireless communication fees; (b) Offences arising from breaches of the legislation concerning banks, financial institutions and the stock exchange, particularly those defined in the Currency and Credit Act; (c) Offences arising from breaches of the legislation on joint-stock companies and offences by multinational companies; (d) Offences that adversely affect the State''s financial standing, or Lebanese or foreign banknotes circulating by law or by custom in Lebanon, and offences involving the counterfeiting, forgery and circulation of currency, public securities, stamps and stamped papers; (e) Offences involving the embezzlement of public funds; (f) Offences pertaining to bankruptcy.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 19', 'Jurisdiction of Financial Prosecutor', 'Procedural Law'),
  ('LB-PROC-001', '20', 'Conditions for Prosecution by Financial Prosecutor: Banking offences arising from breaches of the Law on Currency and Credit may be prosecuted only on the basis of a written request from the Governor of the Banque du Liban. Offences pertaining to customs duties may be prosecuted only on the basis of a written request from the Director-General of Customs. In cases where the administration concerned is entitled to reach an amicable settlement with the defendant, the public prosecution shall be extinguished if the settlement is reached prior to the delivery of a judgement. Enforcement of the penalty shall be suspended if the settlement is reached thereafter, provided that no contrary legal provision is applicable.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 20', 'Conditions for Prosecution by Financial Prosecutor', 'Procedural Law'),
  ('LB-PROC-001', '21', 'Financial Prosecutor''s Authority: The Financial Prosecutor shall exercise the powers vested in him by this Code under the authority of the Public Prosecutor at the Court of Cassation and subject to the rules and regulations applied by the Appeal Court Prosecutor on the basis of this Code and financial legislation. These powers of the Financial Prosecutor shall extend throughout the Lebanese territory. In this connection, he may request, through the Public Prosecutor at the Court of Cassation, the Appeal Court Prosecutor in any governorate to initiate a public prosecution before the Investigating Judges or to initiate proceedings directly before the courts exercising jurisdiction.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 21', 'Financial Prosecutor''s Authority', 'Procedural Law'),
  ('LB-PROC-001', '22', 'Financial Experts: The Financial Prosecutor may seek the assistance of experts in banking, fiscal and financial affairs in performing technical tasks, after they take the oath of legal expertise, unless they are sworn experts. The Public Prosecutor at the Court of Cassation may, of his own motion or at the request of the Financial Prosecutor, request the Prime Minister through the Minister of Justice to instruct the Central Inspectorate to undertake an investigation into any financial matters that he is authorized to have examined.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 22', 'Financial Experts', 'Procedural Law'),
  ('LB-PROC-001', '23', 'Companies Register: The Financial Prosecutor''s Office shall maintain a special legal record of all companies to which Decree No. 3094 of 25 January 1993 is applicable. He shall record all criminal judgements delivered against them. The registrars at the courts exercising jurisdiction shall inform the Financial Prosecutor''s Office of any criminal judgement that has been or is being delivered against a company so that it may be recorded in the special legal register of companies within three months of the date of the judgement.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 23', 'Companies Register', 'Procedural Law'),
  ('LB-PROC-001', '24', 'Duties of Public Prosecutor at Appeal Court: The duties of the Public Prosecutor''s Office at the Appeal Court are as follows: (a) To investigate offences characterized as misdemeanours or felonies and to prosecute those who participated in their commission. The office may apply directly for assistance from the law enforcement authorities in the performance of its duties; Where it obtains knowledge of the commission of a serious offence, it shall immediately inform the Public Prosecutor at the Court of Cassation and carry out his instructions. (b) To initiate and exercise public prosecutions; (c) To represent the Public Prosecution Service at appeal courts and criminal courts and to enforce their judgements; (d) To issue a wanted notice if the person named in a complaint or a suspect cannot be found or if his domicile is unknown; (e) To set aside criminal judgements or to stay or suspend their enforcement pursuant to Article 147 of the Criminal Code; (f) To carry out any other duties assigned to it under this Code and any other legislation.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 24', 'Duties of Public Prosecutor at Appeal Court', 'Procedural Law'),
  ('LB-PROC-001', '25', 'Sources of Information for Prosecutors: The Public Prosecutor''s Office obtains information regarding offences by one or more of the following means: (a) Investigations conducted by the office itself; (b) Reports from the official authority or an officer who obtained knowledge of an offence during the performance of his duties; (c) Preliminary inquiries conducted by the Judicial Police force where it has been instructed to investigate offences, and the reports it submits relating thereto; (d) Complaints or reports filed with it directly or through the Public Prosecutor''s Office at the Court of Cassation or its assistants; (e) Any lawful means that enables it to obtain information regarding the offence.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 25', 'Sources of Information for Prosecutors', 'Procedural Law'),
  ('LB-PROC-001', '26', 'Bringing of Charges: The Public Prosecutor''s Office at the Appeal Court brings charges and names those charged with the offence. It may bring charges against an unknown person before the Investigating Judge, thereby initiating a public prosecution.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 26', 'Bringing of Charges', 'Procedural Law'),
  ('LB-PROC-001', '27', 'Complaints and Reports: A complaint is filed by a victim or his legal representative and a report is submitted by an informant who knew of the offence or heard about it. A report is admissible only if it is submitted in writing and signed by the informant or his legal representative. Every complaint or report shall state, clearly and in full, the name of the complainant or informant and his place of residence.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 27', 'Complaints and Reports', 'Procedural Law'),
  ('LB-PROC-001', '28', 'Duty to Report: Any person who witnesses a breach of the peace or an offence against a person''s safety, life or property is required to report the matter to the Appeal Court Prosecutor or one of his assistants in the place where the offence occurred, the place where the perpetrator was apprehended, or his place of residence. Anyone who fails to comply with this requirement without lawful excuse shall be prosecuted before the Single Criminal Judge responsible for the area where the offence occurred and shall be sentenced to a fine of between two hundred thousand and two million Lebanese pounds.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 28', 'Duty to Report', 'Procedural Law'),
  ('LB-PROC-001', '29', 'Flagrant Offences: An offence discovered during its commission or immediately afterwards is: (a) An offence discovered as it occurs; (b) An offence where the perpetrator is apprehended during or immediately after its commission; (c) An offence following which the suspected perpetrator is chased by hue and cry; (d) An offence detected immediately after being committed with clearly discernible signs of its commission; (e) An offence where a person is caught in possession of articles, weapons or documents indicating that he is the perpetrator within twenty-four hours of the commission of the offence.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 29', 'Flagrant Offences', 'Procedural Law'),
  ('LB-PROC-001', '30', 'Offences Within Dwellings: Felonies and misdemeanours shall have the status of offences discovered during their commission or immediately afterwards if they occur within a dwelling whose owner or occupier requests the Public Prosecutor''s Office to conduct an investigation within twenty-four hours of their discovery.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 30', 'Offences Within Dwellings', 'Procedural Law'),
  ('LB-PROC-001', '31', 'Prosecutor''s Duties at Scene of Flagrant Felony: In the case of a felony discovered during its commission or immediately afterwards, the Public Prosecutor or the Advocate-General shall proceed forthwith, on receiving the information, to the scene of the crime and shall inform the First Investigating Judge or the Investigating Judge on duty thereof, without being required to wait for him to arrive in order to take the following steps: (a) Prepare a report describing the traces left in connection with the crime, the scene and the apparent circumstances of the crime; (b) Seizure of weapons and other items used in the commission of the offence as well as any items that may assist in establishing the facts, and questioning of the suspect about the seized items shown to him; (c) Interview of persons who witnessed the offence or obtained information concerning it after they swear an oath as legal witnesses.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 31', 'Prosecutor''s Duties at Scene of Flagrant Felony', 'Procedural Law'),
  ('LB-PROC-001', '32', 'Prohibition Against Departure — Detention: The Public Prosecutor or the Advocate-General may prohibit persons present at the scene of the felony from leaving it. Anyone who breaches the prohibition decision shall be prosecuted before the Single Criminal Judge responsible for the area where the offence occurred and shall be sentenced to a fine of between two hundred thousand and two million Lebanese pounds. If there are strong suspicions regarding one of the persons present, the prosecutor or his deputy shall order his arrest for questioning and the person shall remain in custody for the purposes of the investigation for a period not exceeding forty-eight hours unless additional time is required for the investigation, in which case his custody shall be extended for a further forty-eight hours. The person being questioned may appoint an advocate to be present during the questioning. During the period of custody, he, his advocate, or a member of his family may request a medical examination, and the Public Prosecutor or the Advocate-General shall appoint a doctor as soon as the request is made. (As amended by Act No. 359/2001)', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 32', 'Prohibition Against Departure — Detention', 'Procedural Law'),
  ('LB-PROC-001', '33', 'Search Powers of Public Prosecutor: The Public Prosecutor may enter a suspect''s home to search for items that he believes will help to shed light on the investigation. He may seize such items, which shall be described clearly and in detail in his report. He may also decide to retain the seized items, depending on their nature. The search shall be conducted in the presence of the suspect or the defendant. If the suspect or defendant is not present or refuses to take part, if he is unable to be present or if he has absconded, the search shall be conducted in the presence of his advocate, two adult members of his family, or two witnesses selected by the Public Prosecutor. It is permissible to enter homes to conduct a search or to look for a perpetrator only between 5 a.m. and 8 p.m. unless the homeowner explicitly agrees to such actions outside that time period.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 33', 'Search Powers of Public Prosecutor', 'Procedural Law'),
  ('LB-PROC-001', '34', 'Expert Assistance: If the nature of the crime or its impact requires the assistance of one or more experts to clarify technical points, the Public Prosecutor shall appoint the expert and clearly specify his assignment. If the victim''s condition necessitates medical assistance or an autopsy, the Public Prosecutor shall send for a forensic or specialist physician and give him clear and detailed instructions regarding his assignment. The expert or doctor shall carry out the assignment only after swearing an oath to act truly and faithfully. He may not exceed the bounds of the assignment.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 34', 'Expert Assistance', 'Procedural Law'),
  ('LB-PROC-001', '35', 'Investigative Measures: The Public Prosecutor shall take any other investigative measures he deems necessary to gather useful information regarding the felony, to collect evidence and to identify the perpetrators or accomplices. The measures must be lawful and must not be vitiated by moral or material coercion. He shall record in his reports all measures taken, the time of their commencement and completion, and all means employed in their implementation.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 35', 'Investigative Measures', 'Procedural Law'),
  ('LB-PROC-001', '36', 'Suspension of Investigation Upon Arrival of Investigating Judge: The Public Prosecutor shall suspend his investigation of an offence discovered during its commission or immediately afterwards when the Investigating Judge arrives, and he shall provide the judge with his reports and the items seized, except for those which are unrelated to the offence and were seized on the ground that they are prohibited items. The Public Prosecutor shall inform the Investigating Judge of the offence that has been committed and shall name any persons whose involvement in the offence appears to be supported by evidence or suspicions.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 36', 'Suspension of Investigation Upon Arrival of Investigating Judge', 'Procedural Law'),
  ('LB-PROC-001', '37', 'Single Judge''s Role in Flagrant Offences: When an offence discovered during its commission or immediately afterwards occurs within his area of jurisdiction, the Single Judge shall proceed to the scene to undertake an investigation if the Public Prosecutor or the Investigating Judge is not present. He shall observe the rules applicable to the Public Prosecutor in this regard. He shall suspend his inquiries as soon as either of them arrives. On completion of his investigation, he shall forward the file to the Public Prosecutor.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 37', 'Single Judge''s Role in Flagrant Offences', 'Procedural Law'),
  ('LB-PROC-001', '38', 'Members of the Judicial Police: The duties of the Judicial Police are performed, under the supervision of the Public Prosecutor at the Court of Cassation, by Public Prosecutors and Advocates-General. The persons listed below assist the Public Prosecution Service and work under its supervision in performing the duties of the Judicial Police within their fields of competence: 1. Governors and district commissioners; 2. The Director-General of the Internal Security Forces, officers of the Internal Security Forces, the Judicial Police, non-commissioned officers serving in the regional sectors, and the heads of Internal Security Forces police stations; 3. The Director-General of General Security, General Security officers and non-commissioned General Security investigators; the Director-General of State Security, the Deputy Director-General, State Security officers and non-commissioned State Security investigators; 4. Village mayors; 5. Captains of ships and aircraft.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 38', 'Members of the Judicial Police', 'Procedural Law'),
  ('LB-PROC-001', '39', 'Additional Judicial Police Functions: Village guards, supervisory officials at the Ministry of Health, forest and consumer protection supervisors, customs supervisors, tobacco control supervisors, supervisors at ports and airports and at the Ministry of Tourism and night watchmen may keep an account of all infringements within their fields of competence and in accordance with the regulations they are required to apply, record them in rigorously compiled reports and submit them to the competent Single Judge.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 39', 'Additional Judicial Police Functions', 'Procedural Law'),
  ('LB-PROC-001', '40', 'Judicial Police Powers — General: Judicial Police officers shall take the same measures in the case of an offence discovered at the time of its commission or immediately afterwards as are taken by the Public Prosecutor when he is unable to do so himself. In undertaking such measures, the Judicial Police officer shall comply with the legal rules applicable to the Public Prosecutor when he investigates an offence discovered at the time of its commission or immediately afterwards. Moreover, in the case of offences not discovered at the time of their commission or immediately afterwards, the Judicial Police, acting on the instructions of the Public Prosecutor''s Office, shall investigate felonies or misdemeanours that are the subject of complaints and reports referred to them by the Public Prosecutor''s Office.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 40', 'Judicial Police Powers — General', 'Procedural Law'),
  ('LB-PROC-001', '41', 'Judicial Police Duties at Scene: If an offence discovered at the time of its commission or immediately afterwards occurs, the Judicial Police officer shall proceed forthwith to the place where it occurred and shall inform the competent Public Prosecutor thereof. He shall preserve any clues, traces and evidence that might disappear and anything that might assist in shedding light on the facts. He shall look for and seize weapons and materials used in or resulting from the commission of the offence. He shall interview witnesses without requiring them to take an oath. He shall make inquiries, arrest anyone who is strongly suspected of having committed the offence or of having participated in its commission, conduct a search of his home and seize any incriminating materials or prohibited items that he finds.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 41', 'Judicial Police Duties at Scene', 'Procedural Law'),
  ('LB-PROC-001', '42', 'Extended Custody in Felony Cases: If the offence discovered at the time of its commission or immediately afterwards is a felony, and the requirements of the investigation demand that the suspect be held in custody for a longer period, the time limit may be extended up to a maximum period of four days upon a reasoned decision in writing by the Appeal Court Prosecutor, who shall issue it after examining the file and verifying the justifications provided. During the extended period, the suspect, his advocate or a member of his family may request that he be examined by a doctor. The Public Prosecutor shall appoint a doctor as soon as the petition is filed and the doctor shall carry out the examination without a Judicial Police officer being present and shall submit his report to the Public Prosecutor within twenty-four hours. In all circumstances, this period of custody shall be deducted from any sentence imposed. (As amended by Act No. 359/2001)', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 42', 'Extended Custody in Felony Cases', 'Procedural Law'),
  ('LB-PROC-001', '43', 'Home Searches by Judicial Police: If the Judicial Police officer believes that a person who is not under strong suspicion possesses documents or materials that are useful for the investigation, the Public Prosecutor or the Investigating Judge shall carry out a search of the person''s home instead of the Judicial Police officer unless the person concerned consents without coercion to a search by the latter. Any house search carried out by the Judicial Police in breach of the rules of procedure legally applicable to the Public Prosecutor in the case of felonies discovered during their commission or immediately afterwards shall be declared null and void.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 43', 'Home Searches by Judicial Police', 'Procedural Law'),
  ('LB-PROC-001', '44', 'Suspension of Operations on Arrival of Superior: If the Public Prosecutor or the Investigating Judge is present, the Judicial Police officer shall suspend his operations unless he receives written instructions from either of them to continue. Under such circumstances, he may also be tasked with questioning the suspect. Once the situation pertaining to offences discovered during their commission or immediately afterwards has come to an end, the Judicial Police officer may not carry out any additional inquiries but shall transmit the records he has compiled to the Public Prosecutor forthwith, together any items seized during the search.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 44', 'Suspension of Operations on Arrival of Superior', 'Procedural Law'),
  ('LB-PROC-001', '45', 'Citizen''s Arrest: In the event of a felony or misdemeanour discovered at the time of its commission or immediately afterwards being punishable by imprisonment, any person is entitled to arrest the perpetrator caught in the act and to take him to the nearest Judicial Police station.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 45', 'Citizen''s Arrest', 'Procedural Law'),
  ('LB-PROC-001', '46', 'Judicial Police Powers in Misdemeanours: If the offence discovered at the time of its commission or immediately afterwards is a misdemeanour punishable by imprisonment of at least one year, the Judicial Police officer may arrest the suspect and investigate the misdemeanour under the authority of the Public Prosecutor. The Public Prosecutor may decide to detain a person charged with a misdemeanour and to bring him forthwith before the Single Judge so that he may be prosecuted in accordance with the rules laid down in this Code.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 46', 'Judicial Police Powers in Misdemeanours', 'Procedural Law'),
  ('LB-PROC-001', '47', 'Judicial Police Duties in Non-Flagrant Offences: Judicial Police officers, acting as assistants to the Public Prosecutor''s Office, shall perform the duties assigned to them by the Public Prosecutor''s Office. They investigate offences not discovered at the time of their commission or immediately afterwards, gather information, make inquiries aimed at identifying the perpetrators and accomplices and gather evidence against them, and carry out actions necessitated by these duties, such as the seizure of incriminating items, the conduct of physical searches of crime scenes, scientific and technical analyses of any samples, and taking statements from witnesses without requiring them to take an oath. Judicial Police officers may not detain a suspect at the police station without a decision by the Public Prosecutor''s Office and the period of detention shall not exceed forty-eight hours. This period may be extended by a similar period subject to the consent of the Public Prosecutor''s Office. The suspect or person complained of shall enjoy the following rights from the time of his arrest for the purposes of the investigation: 1. To contact a member of his family, his employer, an advocate of his choosing or an acquaintance; 2. To meet with the advocate he appoints by a declaration noted in the record; 3. To request a sworn interpreter if he is not proficient in the Arabic language; 4. To submit a request for a medical examination to the Public Prosecutor. (As amended by Act No. 359/2001)', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 47', 'Judicial Police Duties in Non-Flagrant Offences', 'Procedural Law'),
  ('LB-PROC-001', '48', 'Unlawful Detention by Judicial Police: If the Judicial Police officer breaches the rules concerning the detention of the defendant or suspect, he shall be liable to prosecution for the offence of unlawful detention set out in Article 367 of the Criminal Code and punishable by virtue of the same Article, irrespective of whether or not the offence was discovered during its commission or immediately afterwards.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 48', 'Unlawful Detention by Judicial Police', 'Procedural Law'),
  ('LB-PROC-001', '49', 'Preliminary Investigation by Public Prosecutor: The Public Prosecutor may carry out the preliminary investigation himself. If he does, the suspect''s advocate may be present with his client during the questioning. If he does not carry out the investigation himself, the investigation shall be referred to the competent Investigating Judge.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001), Article 49', 'Preliminary Investigation by Public Prosecutor', 'Procedural Law'),
  ('LB-PROC-001', NULL, 'Lebanon''s modern Code of Criminal Procedure enacted August 7, 2001 (Law No. 328), replacing the earlier 1948 code. Immediately amended by Act No. 359 of August 16, 2001. Introduces comprehensive rules for the Public Prosecution Service, Judicial Police, investigating judges, pretrial detention, trials, appeals, and cassation proceedings. Notable for strengthening suspect rights including the right to counsel, right to medical examination during detention, and limits on custody periods. Contains provisions for the Financial Prosecutor''s Office with specialized jurisdiction over banking, customs, and corporate offences.', 'en', 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001) — Historical Context', 'Historical context and overview', 'Procedural Law'),
  ('LB-FIN-001', '1', 'Scope of Application: Banks established in Lebanon in the form of joint-stock companies and banks that are branches of foreign companies are subject to professional secrecy. The provisions of this Law shall not govern the Agricultural, Industrial, and Real Estate Credit Bank.', 'en', 'Law on Banking Secrecy of September 3, 1956 (as amended by Law 306 of October 28, 2022), Article 1', 'Scope of Application', 'Financial Law'),
  ('LB-FIN-001', '2', 'Banking Secrecy Obligation and Exceptions: a- The managers and employees of the banks mentioned in Article 1, and any person who, owing to his/her capacity or position, has any means of access to the banks'' book entries, operations and correspondence, are bound by banking secrecy in the interest of the customers of these banks, and may not disclose any information known to them about the customers'' names, funds, and personal matters to any party, be it an individual or a public authority, whether administrative, military or judicial, unless they are authorized in writing by the concerned customer, his/her heirs or legatees, or if the customer is declared bankrupt, or there is a lawsuit over a banking operation between banks and their customers, or pursuant to the exceptions mentioned in Article 7 of this Law. b- The banking secrecy provisions shall not apply to: 1- The civil servant: any person who has the obligation to submit the Declaration of Assets specified in Law 189/2020 and who performs a public function or public service; 2- The heads of associations and administrative bodies that engage in political activity, and of civil society organizations, as well as their spouses and minor children; 3- The current or former Chairmen and members of the Board of Directors of banks, the executive directors and auditors of these banks, and the Chairmen and members of the Board of Directors of companies that manage or own audio, visual, written and electronic media. The provisions of Paragraph (b) shall remain enforceable on the persons mentioned therein, even after their resignation, termination of services, or retirement, for their whole assignment period and for the following five years.', 'en', 'Law on Banking Secrecy of September 3, 1956 (as amended by Law 306 of October 28, 2022), Article 2', 'Banking Secrecy Obligation and Exceptions', 'Financial Law'),
  ('LB-FIN-001', '3', 'Numbered Accounts – Prohibition: 1- It is prohibited to open numbered deposit accounts and to rent safe deposit boxes to customers that are only known by the bank''s managers or their agents. 2- Customers'' numbered accounts and rented safe deposit boxes should be converted into regular accounts and safes that are subject to all AML/CFT requirements, laws and implementing decrees, within six months at most from the enforcement of this Law. 3- Any withdrawal of funds from numbered deposit accounts or from rented safe deposit boxes shall be postponed until the bank completes the adoption and implementation of all necessary AML/CFT measures.', 'en', 'Law on Banking Secrecy of September 3, 1956 (as amended by Law 306 of October 28, 2022), Article 3', 'Numbered Accounts – Prohibition', 'Financial Law'),
  ('LB-FIN-001', '4', 'No Seizure Without Authorization: Funds and assets deposited with the banks mentioned in Article 1 may not be seized without a written authorization from their owners. a- Funds are frozen by a decision from the Special Investigation Commission, as per the Law on Fighting Money Laundering and Terrorist Financing. b- Funds are seized by a decision from the competent judicial authority, as per Article 7 of this Law.', 'en', 'Law on Banking Secrecy of September 3, 1956 (as amended by Law 306 of October 28, 2022), Article 4', 'No Seizure Without Authorization', 'Financial Law'),
  ('LB-FIN-001', '5', 'Prior Agreement on Authorization: The above-mentioned authorization may be previously agreed upon for any type of contract, and may not be revoked without the consent of all contracting parties.', 'en', 'Law on Banking Secrecy of September 3, 1956 (as amended by Law 306 of October 28, 2022), Article 5', 'Prior Agreement on Authorization', 'Financial Law'),
  ('LB-FIN-001', '6', 'Inter-Bank Information Sharing: To safeguard their invested funds, banks mentioned in Article 1 may share between each other only, and under confidentiality, information about their customers'' debit accounts.', 'en', 'Law on Banking Secrecy of September 3, 1956 (as amended by Law 306 of October 28, 2022), Article 6', 'Inter-Bank Information Sharing', 'Financial Law'),
  ('LB-FIN-001', '7', 'Exceptions to Secrecy: Without prejudice to the provisions of Article 2 of this Law, banks mentioned in Article 1 may not invoke the professional secrecy or banking secrecy specified in this Law, and they must promptly provide all requested information upon receiving a request from: a- The competent judicial authority in lawsuits for corruption offences and money-related offences; b- The Special Investigation Commission as per the Law on Fighting Money Laundering and Terrorist Financing; c- The National Anti-Corruption Commission, as per Law 175 of 8 May 2020; d- The Tax Administration, for combating tax evasion, and for tax compliance and auditing; e- Banque du Liban and the Banking Control Commission; f- In order to restructure the banking sector and to exercise supervisory role thereon, the entities mentioned in Subparagraph (e) may request information protected by banking secrecy, without specifying any particular account or customer.', 'en', 'Law on Banking Secrecy of September 3, 1956 (as amended by Law 306 of October 28, 2022), Article 7', 'Exceptions to Secrecy', 'Financial Law'),
  ('LB-FIN-001', '8', 'Penalties for Violation: Any intentional violation of the provisions of this Law shall be punished as follows: a- To disclose information: 1- Any person who discloses or attempts to disclose information protected by banking secrecy or data obtained in the context of the implementation of this Law or in violation of its provisions, is punishable by imprisonment for a period of one to three months, and by a fine ranging between 150 and 300 times the minimum wage. The fine shall be doubled in case of recurrent or persistent violation. b- To refrain from providing information: 1- Any person who refuses to respond to the requests issued as per Article 7 of this Law shall incur the sanction specified in Article 3(1) of Law 44 of 24 November 2015. Prosecution shall not prevent the obtaining of the information duly requested.', 'en', 'Law on Banking Secrecy of September 3, 1956 (as amended by Law 306 of October 28, 2022), Article 8', 'Penalties for Violation', 'Financial Law'),
  ('LB-FIN-001', '9', 'Repealing Conflicting Provisions: All legal texts that are contrary to, or at variance with the provisions of this Law, shall be considered null and void.', 'en', 'Law on Banking Secrecy of September 3, 1956 (as amended by Law 306 of October 28, 2022), Article 9', 'Repealing Conflicting Provisions', 'Financial Law'),
  ('LB-FIN-001', '10', 'Entry into Force: This Law shall enter into force two months after its publication in the Official Gazette.', 'en', 'Law on Banking Secrecy of September 3, 1956 (as amended by Law 306 of October 28, 2022), Article 10', 'Entry into Force', 'Financial Law'),
  ('LB-FIN-001', NULL, 'Lebanon''s Banking Secrecy Law of 1956 was one of the strictest in the world, positioning Lebanon as a regional banking hub. The law imposed an absolute duty of banking secrecy on all bank employees and prohibited seizure of deposits without client authorization. It was significantly amended in 2022 by Law 306, following the Lebanese financial crisis of 2019-2020, to lift banking secrecy for public officials, politically exposed persons, and in specific legal proceedings, as part of anti-corruption and anti-money laundering reforms.', 'en', 'Law on Banking Secrecy of September 3, 1956 (as amended by Law 306 of October 28, 2022) — Historical Context', 'Historical context and overview', 'Financial Law'),
  ('LB-FIN-002', '1', 'Definition of Illicit Funds: For the purpose of this Law, illicit funds include assets, tangible and intangible, movable and immovable, including any legal documents or instruments evidencing title to, or interest in, such assets, resulting from the commission of, or the punishable attempted commission of, or the participation in any of the following offences, whether in Lebanon or abroad: 1. The growing, manufacturing, or illicit trafficking of narcotic drugs and/or psychotropic substances. 2. The participation in illegal associations with the intention of committing crimes and misdemeanors. 3. Terrorism, according to the provisions of Lebanese laws. 4. The financing of terrorism or terrorist acts and any other related activities. 5. Illicit arms trafficking. 6. Kidnapping, using weapons or any other means. 7. Insider trading, breach of confidentiality, hindering of auctions, and illegal speculation. 8. Incitation to debauchery and offence against ethics and public decency by way of organized gangs. 9. Corruption, including bribery, trading in influence, embezzlement, abuse of functions, abuse of power, and illicit enrichment. 10. Theft, breach of trust, and embezzlement. 11. Fraud, including fraudulent bankruptcy. 12. The counterfeiting of public and private documents and instruments. 13. Smuggling, according to the provisions of the Customs Law. 14. The counterfeiting of goods and fraudulent trading in counterfeit goods. 15. Air and maritime piracy. 16. Trafficking in human beings and smuggling of migrants. 17. Sexual exploitation, including sexual exploitation of children. 18. Environmental crimes. 19. Extortion. 20. Murder. 21. Tax evasion, in accordance with the Lebanese laws.', 'en', 'Law No. 44 of November 24, 2015 on Fighting Money Laundering and Terrorist Financing, Article 1', 'Definition of Illicit Funds', 'Financial Law'),
  ('LB-FIN-002', '2', 'Definition of Money Laundering: Money laundering is any act committed with the purpose of: 1. Concealing the real source of illicit funds, or giving, by any means, a false justification regarding the said source, while being aware of the illicit nature of these funds. 2. Transferring or transporting funds, or substituting or investing the latter in purchasing movable or immovable assets or in carrying out financial transactions for the purpose of concealing or disguising such funds'' illicit source, or assisting a person involved in the commission of any of the offences mentioned in Article 1 to avoid prosecution, while being aware of the illicit nature of these funds. Money laundering is a separate offence that does not necessitate a charge with the underlying predicate offence.', 'en', 'Law No. 44 of November 24, 2015 on Fighting Money Laundering and Terrorist Financing, Article 2', 'Definition of Money Laundering', 'Financial Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-FIN-002', '3', 'Penalties for Money Laundering: Whoever undertakes or attempts to undertake or incites or facilitates or intervenes or participates in: 1- Money-laundering operations, shall be punishable by imprisonment for a period of three to seven years, and by a fine not exceeding twice the amount laundered. 2- Terrorist financing operations or any related activities, shall incur the penalties stipulated in Article 316 bis and Articles 212 to 222 of the Penal Code.', 'en', 'Law No. 44 of November 24, 2015 on Fighting Money Laundering and Terrorist Financing, Article 3', 'Penalties for Money Laundering', 'Financial Law'),
  ('LB-FIN-002', '4', 'Obligations of Financial Institutions: Banks, financial institutions, leasing companies, institutions that issue and promote credit or charge cards, institutions that perform money transfers electronically, exchange institutions, financial intermediation institutions, collective investments schemes, and any other institution requiring a license or supervised by Banque du Liban, must comply with the obligations specified below: 1- To implement Customer Due Diligence measures on permanent customers, in order to check their identity on the basis of reliable documents or information or data. 2- To implement Customer Due Diligence measures on transient customers to verify their identity, if the amount of a single operation or series of operations exceeds the threshold designated by Banque du Liban. 3- To determine the identity of the economic right owner and take the steps needed to verify this identity. 4- To retain copies of related documents of all operations, and to retain information or data for at least five years. 5- To continuously monitor and review the business relationship. 6- To apply these measures whenever there are doubts regarding the accuracy of declared customer identification data, or whenever there is a suspicion of money laundering or terrorist financing. 7- To take into account the indicators that flag the likelihood of a money laundering or terrorist financing operation.', 'en', 'Law No. 44 of November 24, 2015 on Fighting Money Laundering and Terrorist Financing, Article 4', 'Obligations of Financial Institutions', 'Financial Law'),
  ('LB-FIN-002', '5', 'Obligations of Non-Financial Institutions: Institutions not subjected to the Banking Secrecy Law of September 3, 1956, particularly insurance companies, casinos, real estate dealers and agents, and merchants of valuables (jewelry, precious stones, gold, works of art, antiques), must keep records of operations that exceed the threshold designated by the Special Investigation Commission. Certified accountants and notaries must implement these obligations, when preparing or carrying out on behalf of their customers any of the following activities: Buying and selling of real estate; Management of customers'' movable and immovable assets; Management of bank accounts and securities accounts; Organization of contributions for the establishment or management of companies; Establishment or management of legal persons or unique legal arrangements.', 'en', 'Law No. 44 of November 24, 2015 on Fighting Money Laundering and Terrorist Financing, Article 5', 'Obligations of Non-Financial Institutions', 'Financial Law'),
  ('LB-FIN-002', '6', 'An independent, legal entity with judicial status shall be established at Banque du Liban, referred to as ''the Special Investigation Commission'' or ''the Commission'', which shall discharge its functions without being subject to Banque du Liban''s authority. 1. The Commission shall consist of: The Governor of Banque du Liban (Chairman); A judge appointed to the Higher Banking Commission (Member); The Chairman of the Banking Control Commission (Member); A principal member and an alternate member appointed by the Council of Ministers with at least 15 years'' experience in financial or banking law. 2. The mission of the Commission is: To receive suspicious transaction reports (STRs); To investigate operations suspected to be money-laundering or terrorist financing offences; To decide on the seriousness of evidence; To take precautionary and temporary freezing of suspicious accounts and/or transactions; To ensure compliance by reporting entities; To collect and retain information received. 3. After conducting the necessary audit and analysis, the Commission is the solely certified to decide: To permanently freeze the concerned accounts and/or transactions; To lift banking secrecy in favor of the competent judicial authorities; To keep suspicious accounts as traceable accounts.', 'en', 'Law No. 44 of November 24, 2015 on Fighting Money Laundering and Terrorist Financing, Article 6', 'Special Investigation Commission', 'Financial Law'),
  ('LB-FIN-002', '7', 'Suspicious Transaction Reporting: The parties referred to in Articles 4 and 5 of this Law, including certified accountants and notaries, when preparing or carrying out on behalf of their customers any of the activities mentioned in Article 5 above must promptly report to the Chairman of the Commission the details of operations undertaken or attempted to be undertaken that are suspected to be related to money laundering or terrorist financing. The same obligations shall apply to lawyers, according to a mechanism to be set by the Beirut Bar Association and the Tripoli Bar Association.', 'en', 'Law No. 44 of November 24, 2015 on Fighting Money Laundering and Terrorist Financing, Article 7', 'Suspicious Transaction Reporting', 'Financial Law'),
  ('LB-FIN-002', '11', 'Prohibition on Tipping Off: Reporting entities, as well as their Board members, officers and employees, are prohibited from disclosing or insinuating to anyone that a suspicious transaction report or other relevant information is submitted or intended to be submitted to the Commission, or that the Commission is inquiring about customers or auditing their operations or accounts.', 'en', 'Law No. 44 of November 24, 2015 on Fighting Money Laundering and Terrorist Financing, Article 11', 'Prohibition on Tipping Off', 'Financial Law'),
  ('LB-FIN-002', '12', 'Immunity: Within the scope of their work, the Chairman, members, staff and delegates of the Commission, shall enjoy immunity. Thus, they may not be prosecuted or sued, neither collectively nor individually, for any civil or criminal liability related to the performance of their duties. The parties referred to in Articles 4 and 5 above and their staff shall also enjoy the same immunity when they report in good faith to the Commission the details of operations they suspect to be related to money laundering or terrorist financing.', 'en', 'Law No. 44 of November 24, 2015 on Fighting Money Laundering and Terrorist Financing, Article 12', 'Immunity', 'Financial Law'),
  ('LB-FIN-002', '13', 'Penalties for Non-Compliance: Any party that violates the provisions of Articles 4, 5, 7, 10, and 11 of this Law shall be punishable by imprisonment for a period of two months to one year and by a fine not exceeding one hundred million Lebanese pounds, or by either penalties. The Commission may address a warning to the parties who are in violation of the provisions of the regulations issued for the purpose of implementing this Law. The Higher Banking Commission may impose on the parties that were referred to it a fine for non-compliance, provided this fine does not exceed two hundred times the official minimum wage.', 'en', 'Law No. 44 of November 24, 2015 on Fighting Money Laundering and Terrorist Financing, Article 13', 'Penalties for Non-Compliance', 'Financial Law'),
  ('LB-FIN-002', '14', 'Confiscation: The movable or immovable assets that are proved, by a final Court ruling, to be related to, or derived from, a money-laundering or terrorist financing offence, shall be confiscated to the benefit of the State, unless the owners of the said assets prove in a Court of Law their legal rights thereupon. The confiscated assets may be shared with other countries, whenever the confiscation results directly from coordinated investigations or cooperation between the concerned Lebanese authorities and the concerned foreign body(ies).', 'en', 'Law No. 44 of November 24, 2015 on Fighting Money Laundering and Terrorist Financing, Article 14', 'Confiscation', 'Financial Law'),
  ('LB-FIN-002', '18', 'Entry into Force: This Law shall enter into force upon its publication in the Official Gazette. Beirut, November 24, 2015. Promulgated by the Council of Ministers. The President of the Council of Ministers. Signed: Tammam Salam.', 'en', 'Law No. 44 of November 24, 2015 on Fighting Money Laundering and Terrorist Financing, Article 18', 'Entry into Force', 'Financial Law'),
  ('LB-FIN-002', NULL, 'Lebanon''s Law No. 44 of 2015 replaced the earlier Law No. 318 of 2001 on Fighting Money Laundering. The 2015 law expanded predicate offences to include 21 categories of crimes (including tax evasion, environmental crimes, and human trafficking), created a broader framework for the Special Investigation Commission (SIC), and aligned Lebanon''s AML/CFT regime with FATF recommendations. The law requires all financial institutions, insurance companies, casinos, real estate dealers, and designated non-financial businesses to implement Customer Due Diligence and report suspicious transactions.', 'en', 'Law No. 44 of November 24, 2015 on Fighting Money Laundering and Terrorist Financing — Historical Context', 'Historical context and overview', 'Financial Law'),
  ('LB-DIGITAL-001', '1', 'Definitions: For the purposes of the present law: Writing: The process of writing or recording letters, numbers, characters or symbols, provided that they are legible and comprehensible, regardless of the format used. Electronic Document: An ordinary or official document issued in an electronic form pursuant to Article 8 herein. Signature: The signature required to complete a legal process in order to identify the party thereto and confirm their consent. Service Provider: A public or private law enforcement officer who issues the certificates of authentication. Electronic Commerce: An activity whereby a person provides or remotely offers goods and services to another person. Bank Card: An instrument issued by a bank allowing its holder to withdraw cash money or perform electronic payments or any other banking or financial services. Electronic Money: Electronic monetary units stored in electronic form. Network Service Provider: A business or organization that enables the user to access an electronic communication network. Data Host: A system used to store third-party information of any type and make it accessible to the public. Traffic Data: Any data relating to a communication by means of a computer connected to the network, generated by a computer system and indicating the communication''s origin, destination, route, format, intent, time, date, size, duration. Domain Name: The system used to translate the alphanumeric domain name of a website into an Internet Protocol number. Personal Data: Any information that helps to directly or indirectly identify a natural person. Processing of Personal Data: Any action or set of actions performed on the data regardless of the medium used, including data collection, recording, organization, storage, adaptation, modification, extraction, reading, use, transmission, copy, dissemination, deletion, destruction or otherwise disposing of it.', 'en', 'Law No. 81 of October 10, 2018 Relating to Electronic Transactions and Personal Data, Article 1', 'Definitions', 'Digital and Technology Law'),
  ('LB-DIGITAL-001', '2', 'Principle: The information technology is at the service of the people, provided that it does not prejudice their individual identity, rights, private life, or individual or public freedoms.', 'en', 'Law No. 81 of October 10, 2018 Relating to Electronic Transactions and Personal Data, Article 2', 'Principle', 'Digital and Technology Law'),
  ('LB-DIGITAL-001', '4', 'Legal Effect of Electronic Writing: Electronic writings and signatures shall have the same legal effect as the writings and signatures made on paper or any other medium, provided that the person producing them is identifiable and that they are organized and stored in a way that preserves their safety. Any electronic writing that does not meet the criteria above shall be considered as introduction of written evidence.', 'en', 'Law No. 81 of October 10, 2018 Relating to Electronic Transactions and Personal Data, Article 4', 'Legal Effect of Electronic Writing', 'Digital and Technology Law'),
  ('LB-DIGITAL-001', '7', 'Electronic Documents as Evidence: The electronic document shall be accepted as evidence and is deemed to have the same significance and power of proof as the written paper-based document, provided that it is possible to identify the person issuing the document and that the latter is organized and stored in a way that ensures its integrity.', 'en', 'Law No. 81 of October 10, 2018 Relating to Electronic Transactions and Personal Data, Article 7', 'Electronic Documents as Evidence', 'Digital and Technology Law'),
  ('LB-DIGITAL-001', '8', 'Official Electronic Documents: Official electronic documents do not produce any legal effects unless they are organized and governed by virtue of a decree issued by the Council of Ministers upon a proposal by the Minister of Justice.', 'en', 'Law No. 81 of October 10, 2018 Relating to Electronic Transactions and Personal Data, Article 8', 'Official Electronic Documents', 'Digital and Technology Law'),
  ('LB-DIGITAL-001', '9', 'Electronic Signature: The electronic signature is issued through the use of a safe medium that identifies the signatory and provides a guarantee that the signature corresponds to the legal process in question. If the signature is linked to the protection measures authenticated by the authorized authentication service provider, it shall be presumed to have satisfied the criteria set forth in this Article, unless proven otherwise.', 'en', 'Law No. 81 of October 10, 2018 Relating to Electronic Transactions and Personal Data, Article 9', 'Electronic Signature', 'Digital and Technology Law'),
  ('LB-DIGITAL-001', '14', 'Freedom of Electronic Writing: Electronic writing is a free act, and no person shall be bound to resort to protection means unless otherwise stipulated by the law.', 'en', 'Law No. 81 of October 10, 2018 Relating to Electronic Transactions and Personal Data, Article 14', 'Freedom of Electronic Writing', 'Digital and Technology Law'),
  ('LB-DIGITAL-001', '15', 'Protection Measures: The protection measures are used in electronic writings and signatures to make them more reliable. The protection measures help perform several functions, such as verifying the identity of the document organizer, assigning a correct date to the document, and/or ensuring its storage and the integrity of its content. Any and all functions above are provided by one or more authentication service provider who shall, upon performance of said functions, deliver a certificate of authentication to the concerned person.', 'en', 'Law No. 81 of October 10, 2018 Relating to Electronic Transactions and Personal Data, Article 15', 'Protection Measures', 'Digital and Technology Law'),
  ('LB-DIGITAL-001', '20', 'COLIBAC Accreditation: COLIBAC accredits those authentication service providers who issue certificates to electronic writings and signature provided they meet the requirements outlined in Articles (7) and (9) above. COLIBAC decisions regarding the implementation of the present Law may be challenged before the State Council.', 'en', 'Law No. 81 of October 10, 2018 Relating to Electronic Transactions and Personal Data, Article 20', 'COLIBAC Accreditation', 'Digital and Technology Law'),
  ('LB-DIGITAL-001', '30', 'Freedom of Electronic Commerce: Electronic commerce shall be free to the extent permissible by law. All matters related to e-commerce and not mentioned in the present law shall be governed by the applicable laws, particularly the Code of Commerce, the Code of Obligations and Contracts, the Civil Procedure Law and the Consumer Protection Law.', 'en', 'Law No. 81 of October 10, 2018 Relating to Electronic Transactions and Personal Data, Article 30', 'Freedom of Electronic Commerce', 'Digital and Technology Law'),
  ('LB-DIGITAL-001', '31', 'Disclosure Obligations in E-Commerce: All persons practicing e-commerce as a business must ensure to the persons they deal with an easy and direct access to the following information at all times: 1- For natural persons, their first name, last name and place of residence. 2- For legal entities, their name, the name of their legal representative, their headquarters and their commercial address. 3- The detailed address, email, website, and telephone number. 4- Number and Place of registration at the Commercial Registry and the competent tax department. 5- Their professional capacity and the professional rules governing their business. 6- A detailed statement outlining the price and any payable tax, fee or expenses.', 'en', 'Law No. 81 of October 10, 2018 Relating to Electronic Transactions and Personal Data, Article 31', 'Disclosure Obligations in E-Commerce', 'Digital and Technology Law'),
  ('LB-DIGITAL-001', '32', 'Prohibition on Spam: Promotional ads that are accessible online through any electronic device should contain a reference to indicate that the material is a promotional ad. It is forbidden to communicate unsolicited marketing and advertising emails (SPAM) using a real person''s name and address, unless that person has consented to such type of advertising, except for cases where the sender of the unsolicited advertisement has legally obtained the client''s address through a previous engagement with them. Every promotional or marketing email should contain a reference to an email which the recipient can reply to in order to request that they stop receiving such emails permanently and free of charge.', 'en', 'Law No. 81 of October 10, 2018 Relating to Electronic Transactions and Personal Data, Article 32', 'Prohibition on Spam', 'Digital and Technology Law'),
  ('LB-DIGITAL-001', '33', 'Electronic Contract Formation Requirements: Any person who offers, as part of their business, goods or services by electronic means shall include the following in their offerings: 1- Steps to follow to sign the contract electronically. 2- The contract terms and conditions in a form that can be saved and duplicated. 3- Technical features that allow the addressee to double check the electronic contract for errors and correct the same before submitting the final approval. 4- To which extent the offeror undertakes to store the digital traces. 5- The contract official language.', 'en', 'Law No. 81 of October 10, 2018 Relating to Electronic Transactions and Personal Data, Article 33', 'Electronic Contract Formation Requirements', 'Digital and Technology Law'),
  ('LB-DIGITAL-001', '38', 'Contract Formation in Civil and Commercial Matters: The acceptance of the electronic means to be used in civil or commercial contracts shall not be considered sufficient to originate the contract. The addressee may re-examine the parties'' contractual obligations before confirming their will to proceed with the contract. When bargains in civil and commercial contracts are made electronically, the contract shall only be originated when the offeror receives the addressee''s consent. An electronic communication is taken to be dispatched when it enters the first information system outside the sender''s control.', 'en', 'Law No. 81 of October 10, 2018 Relating to Electronic Transactions and Personal Data, Article 38', 'Contract Formation in Civil and Commercial Matters', 'Digital and Technology Law'),
  ('LB-DIGITAL-001', '41', 'Electronic Payment Definition: An electronic payment or money transfer is an operation carried out, partly or entirely, by electronic means. In order to perform such operation, the client authorizes the bank, the financial institution or any institution legally authorized or licensed by Banque du Liban to perform an electronic payment operation.', 'en', 'Law No. 81 of October 10, 2018 Relating to Electronic Transactions and Personal Data, Article 41', 'Electronic Payment Definition', 'Digital and Technology Law'),
  ('LB-DIGITAL-001', '43', 'Client Consent for Electronic Payments: The client shall give his prior written consent to the conditions governing electronic payments, transfers or cancellation thereof, provided that such conditions are clear, explicit and compliant with Banque du Liban regulations, include the rights and obligations relating to electronic banking services and determine the fees, expenses, commissions and taxes, if any.', 'en', 'Law No. 81 of October 10, 2018 Relating to Electronic Transactions and Personal Data, Article 43', 'Client Consent for Electronic Payments', 'Digital and Technology Law'),
  ('LB-DIGITAL-001', '46', 'Client Liability for Unauthorized Transactions: Except in cases of serious error, gross negligence or bad faith, the client shall not be responsible for any electronic payment or transfer transaction made to their account provided that they promptly notify in writing the institutions referred to in Article (41) above within 90 days of the date of the transaction resulting from: A third party might have accessed their account illegally; A third party might have known their account personal identification number (PIN); The client knows that an operation was performed through their account either without their consent or knowledge, or by mistake, or illegally.', 'en', 'Law No. 81 of October 10, 2018 Relating to Electronic Transactions and Personal Data, Article 46', 'Client Liability for Unauthorized Transactions', 'Digital and Technology Law'),
  ('LB-DIGITAL-001', '48', 'Written Form for Payment Orders: The orders to perform electronic payments and transfers shall be made in writing and shall be manually or electronically signed, under penalty of nullity. If orders are electronically signed, the signature shall be authenticated in accordance with the rules issued by the Banque du Liban.', 'en', 'Law No. 81 of October 10, 2018 Relating to Electronic Transactions and Personal Data, Article 48', 'Written Form for Payment Orders', 'Digital and Technology Law'),
  ('LB-DIGITAL-001', NULL, 'Lebanon''s Electronic Transactions and Personal Data Law was enacted on October 10, 2018 (effective three months after publication). It was based on a draft law issued by Decree No. 9341 of November 17, 2012. The law establishes the legal framework for electronic writing and signatures, electronic commerce and contracts, electronic banking and financial services, electronic government, and personal data protection. It created COLIBAC (Lebanese Accreditation Council) as the body responsible for accrediting electronic authentication service providers.', 'en', 'Law No. 81 of October 10, 2018 Relating to Electronic Transactions and Personal Data — Historical Context', 'Historical context and overview', 'Digital and Technology Law'),
  ('LB-CR-001', '1', 'Incriminating Torture – Amendment to Article 401 of the Penal Code: Article 401 of the Criminal Code shall be amended to read as follows: a- ''Torture under the present Law shall include any act inflicted by or at the instigation of or with the consent or acquiescence of a public official or other person acting in an official capacity during the preliminary survey and investigations, judicial investigation, trials and punishments resulting in severe pain or suffering, whether physical or mental, intentionally inflicted on a person for the purposes below: obtaining from him/her or a third person information or a confession; punishing him/her for an act he/she or a third person has committed or is suspected of having committed; intimidating or coercing him/her or a third person into engaging in an act or refraining therefrom; inflicting such pain or suffering for any reason based on discrimination of any kind. The definition above does not include pain or suffering arising only from, inherent in or incidental to, lawful sanctions.'' b- Anyone who practices torture shall be liable to imprisonment as follows: One to three years in prison for cases that do not result in physical or psychological harm; Three to seven years if it leads to temporary disability, harm, or physical or psychological impairment; Five to ten years if the harm is permanent; Ten to twenty years if it leads to death. c- Court shall determine the measure of rehabilitating the victims of torture in addition to personal compensation.', 'en', 'Law No. 65/2017 on the Punishment of Torture and Other Cruel, Inhuman or Degrading Treatment (Anti-Torture Law), Article 1', 'Incriminating Torture – Amendment to Article 401 of the Penal Code', 'Criminal Law'),
  ('LB-CR-001', '2', 'Special Provisions on Illegal Orders – Amendment to Article 185 of the Penal Code: The following two paragraphs shall be added to Article 185 of the Criminal Code: ''Whoever is prosecuted for any of the crimes under Article 401 of the present law, shall, on no account, allege necessity, national security requirements, orders of the supreme hierarchy or any other pretext.'' ''The orders of torture issued by a public officer, of any rank, agency of authority, shall not be considered legitimate orders in any case.''', 'en', 'Law No. 65/2017 on the Punishment of Torture and Other Cruel, Inhuman or Degrading Treatment (Anti-Torture Law), Article 2', 'Special Provisions on Illegal Orders – Amendment to Article 185 of the Penal Code', 'Criminal Law'),
  ('LB-CR-001', '3', 'Statute of Limitations – Amendment to Code of Criminal Procedure: By virtue of this Article and Article 10 of the Code of Criminal Procedure, the crime of torture is subjected to the ten-year statute of limitation (felony prescription period), which starts to run upon the victim''s release from custody or detention.', 'en', 'Law No. 65/2017 on the Punishment of Torture and Other Cruel, Inhuman or Degrading Treatment (Anti-Torture Law), Article 3', 'Statute of Limitations – Amendment to Code of Criminal Procedure', 'Criminal Law'),
  ('LB-CR-001', '4', 'Inadmissibility of Evidence Obtained Under Duress: Any evidence or confession obtained through the use of torture, coercion or any form of duress shall be inadmissible in any judicial proceedings. Courts are required to exclude such evidence and to refer the matter for investigation of the alleged torture.', 'en', 'Law No. 65/2017 on the Punishment of Torture and Other Cruel, Inhuman or Degrading Treatment (Anti-Torture Law), Article 4', 'Inadmissibility of Evidence Obtained Under Duress', 'Criminal Law'),
  ('LB-CR-001', '5', 'Obligations of Judicial Authorities: Judicial authorities are required to promptly and impartially consider complaints of torture. In accordance with Article 13 of the UN Convention against Torture, the bill proposes a set of provisions aimed at ensuring the effectiveness of complaints submitted by all those who claim to be subjected to torture and that the competent judicial authorities shall consider such complaints promptly and impartially. Victims of torture are entitled to file complaints and to have access to full reparation including rehabilitation and compensation independent of criminal proceedings.', 'en', 'Law No. 65/2017 on the Punishment of Torture and Other Cruel, Inhuman or Degrading Treatment (Anti-Torture Law), Article 5', 'Obligations of Judicial Authorities', 'Criminal Law'),
  ('LB-CR-001', '6', 'Entry into Force: This Law shall enter into force upon its publication in the Official Gazette.', 'en', 'Law No. 65/2017 on the Punishment of Torture and Other Cruel, Inhuman or Degrading Treatment (Anti-Torture Law), Article 6', 'Entry into Force', 'Criminal Law'),
  ('LB-CR-001', NULL, 'Law No. 65/2017 was adopted by the Lebanese Parliament on September 19, 2017, marking the first time that Lebanese legislation explicitly criminalized torture. Lebanon had ratified the UN Convention against Torture (CAT) in 2000 and its Optional Protocol (OPCAT) in 2008. The law amended Articles 401 and 185 of the Penal Code and Article 10 of the Code of Criminal Procedure. However, the law has been criticized by international human rights bodies for having an overly narrow definition of torture, setting a statute of limitations, imposing insufficiently grave penalties, and failing to explicitly require torture cases to be heard in civilian (rather than military) courts.', 'en', 'Law No. 65/2017 on the Punishment of Torture and Other Cruel, Inhuman or Degrading Treatment (Anti-Torture Law) — Historical Context', 'Historical context and overview', 'Criminal Law'),
  ('LB-LABOR-001', '1', 'Establishment of National Social Security Fund: 1 - A Social Security National Fund shall be set up, referred to in the present law by the term ''Fund''. Its terms of reference shall be the management of the whole of the social security system including its various branches. 2 - The Fund shall be an autonomous institution of a social character, governed by the provisions of the present law. It shall be vested with corporate personality as well as with financial and managerial autonomy. Its registered office shall be in Beirut, and it shall be authorised to set up regional and local offices. 3 - Within the limitations set out in Article 3 of the present law, the Fund shall be subject to: A - The guardianship of the Ministry of Labour and Social Affairs, through a Government Commissioner; B - The prior guardianship of the Council of Ministers; C - The subsequent control of the Audit Office, to the exclusion of any prior control. 4 - The machinery of the Fund shall be made up of the Board of Directors, the Technical Commission and the Secretariat. 5 - The Fund shall be subject to the control of neither the Civil Service Council nor of Central Inspectorate.', 'en', 'Social Security Law (Decree-Law No. 13955 of September 26, 1963), Article 1', 'Establishment of National Social Security Fund', 'Labor and Social Law'),
  ('LB-LABOR-001', '2', 'Board of Directors Composition: The Board of Directors shall be composed of the following delegates: A - Six delegates representing the State; B - Ten delegates from professional organisations most representative of employers; C - Ten delegates from professional organisations most representative of wage-earners and salary-earners (workmen and employees); D - Delegates from agricultural organisations. Decisions shall be taken by the Board of Directors and by the Office Committee by absolute majority vote. Each delegate shall have one vote, and in case of a tie, the President''s vote shall have casting power. The majority voting for the decision in the Board of Directors, must consist of the absolute majority of each group of representatives.', 'en', 'Social Security Law (Decree-Law No. 13955 of September 26, 1963), Article 2', 'Board of Directors Composition', 'Labor and Social Law'),
  ('LB-LABOR-001', '3', 'Powers of the Board of Directors: Powers of the Fund''s Board of Directors shall notably be the following: 1 - Without prejudice to any decree from the Council of Ministers: organization and nomination of the Financial Commission; vesting the Director General with authority to acquire real estate for internal operation of the Fund. 2 - Activities which require the approval of the guardianship Authority: issuance of Internal Regulations; producing the administrative budget; closing the accounts; setting priorities for social investments; laying down the ground-work for creation of new local and regional offices. 3 - Activities within the competence of the Office Committee: decisions which need not be submitted to the Council of Ministers; decisions related to administrative or technical matters.', 'en', 'Social Security Law (Decree-Law No. 13955 of September 26, 1963), Article 3', 'Powers of the Board of Directors', 'Labor and Social Law'),
  ('LB-LABOR-001', '5', '1 - The Fund''s Secretariat shall be headed by a Director General. The latter shall be appointed by decree emanating from the Council of Ministers, on the proposal of the Minister of Labour and Social Affairs after approval of the Board of Directors. 2 - Only a university graduate holding a recognised degree, and duly qualified in social, administrative or financial matters and with some banking and insurance experience may be appointed. 3 - The Director General shall be held for the implementation of the resolutions adopted by the Board, as well as for the management of the Fund''s Secretariat.', 'en', 'Social Security Law (Decree-Law No. 13955 of September 26, 1963), Article 5', 'Director General', 'Labor and Social Law'),
  ('LB-LABOR-001', '7', 'Branches of Social Security: Social Security shall comprise the following branches: A - Sickness-maternity insurance. B - Labour accidents-occupational diseases insurance. C - Family allowance regime. D - End-of-service indemnity regime. It shall be applied in three stages.', 'en', 'Social Security Law (Decree-Law No. 13955 of September 26, 1963), Article 7', 'Branches of Social Security', 'Labor and Social Law'),
  ('LB-LABOR-001', '9', 'Scope of Application: Shall be subject to the provisions of the present law, as from the first stage, on condition that activity is exercised on the Lebanese territory: A - Lebanese wage-earners and salary-earners, permanent, temporary, apprentices, seasonal, and trainees, working for the account of one or several Lebanese or foreign employers, whatever may be the duration, kind, nature, form or validity of the contracts binding them to their employer; B - Lebanese wage-earners and salary-earners unattached to any particular employer, and who work in the maritime sector, ports, enterprises, building, transport and unloading; C - Members of the teaching staff in Lebanese higher education establishments; D - Lebanese nationals who work for the account of the State or Municipalities or any other Administration, Public Establishment or Autonomous Office.', 'en', 'Social Security Law (Decree-Law No. 13955 of September 26, 1963), Article 9', 'Scope of Application', 'Labor and Social Law'),
  ('LB-LABOR-001', NULL, 'Lebanon''s Social Security Law was promulgated by Decree-Law No. 13955 of September 26, 1963, establishing the National Social Security Fund (NSSF or CNSS in French). The law created a comprehensive social protection system covering four branches: sickness-maternity insurance, labor accidents and occupational diseases insurance, family allowances, and end-of-service indemnity. The Fund is governed by a Board of Directors with tripartite representation from the state, employers, and workers. The law has been amended numerous times, most significantly by Laws No. 9/74 (1974), 12/78 (1978), 15/69 (1969), and 27/88 (1988).', 'en', 'Social Security Law (Decree-Law No. 13955 of September 26, 1963) — Historical Context', 'Historical context and overview', 'Labor and Social Law'),
  ('LB-LABOR-002', '1', 'Definition of Collective Employment Contract: A collective employment contract is an instrument governing employment terms that is concluded between a party representing one or more workers'' trade union and another party, who may be an individual employer, a group of employers, a representative of one or more professional body or union of employers. Collective employment contracts are designed to regulate the conditions of employment stipulated in individual contracts between the parties bound by the agreement.', 'en', 'Law on Collective Labor Contracts, Mediation and Arbitration (Decree-Law No. 17386/1964), Article 1', 'Definition of Collective Employment Contract', 'Labor and Social Law'),
  ('LB-LABOR-002', '2', 'Representative Authority: The employee representative must be vested with the authorisation of at least 60% of the relevant employees in order to negotiate a collective agreement.', 'en', 'Law on Collective Labor Contracts, Mediation and Arbitration (Decree-Law No. 17386/1964), Article 2', 'Representative Authority', 'Labor and Social Law'),
  ('LB-LABOR-002', '3', 'Written Form and Registration: The collective agreement shall be executed in writing and becomes binding upon the earlier of: publication in the Official Gazette by the Ministry of Labour; or one month after its registration at the Ministry of Labour.', 'en', 'Law on Collective Labor Contracts, Mediation and Arbitration (Decree-Law No. 17386/1964), Article 3', 'Written Form and Registration', 'Labor and Social Law'),
  ('LB-LABOR-002', '4', 'Adhesion to Existing Agreements: Any trade union, professional body or employer that is not a party to the collective agreement can unilaterally decide to join the collective agreement without the consent of the initial signatories, by virtue of a written request submitted to the Ministry of Labour.', 'en', 'Law on Collective Labor Contracts, Mediation and Arbitration (Decree-Law No. 17386/1964), Article 4', 'Adhesion to Existing Agreements', 'Labor and Social Law'),
  ('LB-LABOR-002', '5', 'Mediation for Collective Disputes: The Collective Agreements Law encourages alternative dispute resolution and provides for mediation as a first attempt to settle collective labor disputes. A dispute is considered a collective labour dispute where a party to the dispute is a group of employees and the dispute pertains to a collective interest.', 'en', 'Law on Collective Labor Contracts, Mediation and Arbitration (Decree-Law No. 17386/1964), Article 5', 'Mediation for Collective Disputes', 'Labor and Social Law'),
  ('LB-LABOR-002', '6', 'If the mediation process is wholly or partially unsuccessful, the parties may resort to arbitration before the Arbitration Commission for the Resolution of Collective Labour Disputes, established pursuant to this Law. The commission consists of representatives of employees, employers and the Ministry of Labour. The commission''s decision is final.', 'en', 'Law on Collective Labor Contracts, Mediation and Arbitration (Decree-Law No. 17386/1964), Article 6', 'Arbitration Commission', 'Labor and Social Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-LABOR-002', '7', 'Special Committee Arbitration: The parties can agree in a collective agreement or private contract to resolve the dispute before a special committee other than the Arbitration Commission for the Resolution of Collective Labour Disputes (except in certain cases where it is mandatory to refer the matter to the commission). The decision of the special committee may be subject to appeal to the arbitration commission, which must issue its decision within one month of the date of the first session – a timeframe which the arbitration commission can extend by two weeks where necessary.', 'en', 'Law on Collective Labor Contracts, Mediation and Arbitration (Decree-Law No. 17386/1964), Article 7', 'Special Committee Arbitration', 'Labor and Social Law'),
  ('LB-LABOR-002', NULL, 'Lebanon''s Collective Labor Contracts, Mediation and Arbitration Law was enacted by Decree-Law No. 17386 in 1964, providing the legal framework for collective bargaining alongside the individual employment framework under the 1946 Labour Law. The law establishes mechanisms for negotiating, registering, and enforcing collective employment contracts between trade unions and employers, and provides for mediation and arbitration as dispute resolution mechanisms for collective labor disputes.', 'en', 'Law on Collective Labor Contracts, Mediation and Arbitration (Decree-Law No. 17386/1964) — Historical Context', 'Historical context and overview', 'Labor and Social Law'),
  ('LB-PROP-001', '159/1992-1', 'Freedom of Contract for New Leases (Art. 1 of Law 159/1992): The leases of both residential and non-residential property shall be subject to freedom of contract and to the will of the contracting parties in all that does not contradict the following binding provisions: First: if the lease period specified in the lease agreement is less than three years, the lease shall still be considered for a period of three years. Second: excluded from the previous provision are all the seasonal leases concerned with summer and winter vacation premises and the leases of property granted by employers to employees with or without a charge. Third: if the period of the lease agreement, whether of built property or land, exceeds three years, the property may not be passed to a third party unless it is first registered in the cadastral registry.', 'en', 'Rent Laws: Law No. 159/1992 (New Leases), Law No. 160/1992 (Old Leases), and Law No. 9/2014 (New Tenancy Law), Article 159/1992-1', 'Freedom of Contract for New Leases (Art. 1 of Law 159/1992)', 'Property Law'),
  ('LB-PROP-001', '160/1992-1', 'Rental Increases for Old Leases (Art. 1 of Law 160/1992): For lease agreements signed prior to July 22, 1990: Raising rental fees by half the successive wage hikes affecting the first salary bracket and determined by the decrees pertaining to the cost of living and the pay of employees as of July 1, 1987 and successively upon every future rise. Law No. 160 also postulated doubling the rental fees according to the year of the lease agreement in favor of landlords and granted them the right to regain their property should they or a member of their family need the dwelling for personal use, provided that they pay the tenant a compensation estimated by the courts of not less than 25% and not more than 50% of the property value.', 'en', 'Rent Laws: Law No. 159/1992 (New Leases), Law No. 160/1992 (Old Leases), and Law No. 9/2014 (New Tenancy Law), Article 160/1992-1', 'Rental Increases for Old Leases (Art. 1 of Law 160/1992)', 'Property Law'),
  ('LB-PROP-001', '9/2014-1', 'Scope of New Tenancy Law: Subject to the provisions of this law are all the lease agreements regarding built property signed prior to July 23, 1992 with the exception of: 1) the leases of agricultural land and the facilities on it; 2) the seasonal leases concerned with summer and winter vacation premises; 3) the leases of property granted by employers to employees for accommodation; 4) the leases on villas fulfilling certain specifications established by the law; 5) the leases on the state and the municipal public properties.', 'en', 'Rent Laws: Law No. 159/1992 (New Leases), Law No. 160/1992 (Old Leases), and Law No. 9/2014 (New Tenancy Law), Article 9/2014-1', 'Scope of New Tenancy Law', 'Property Law'),
  ('LB-PROP-001', '9/2014-2', 'Transition Period and Extension: The newly approved Rent Act extended lease agreements by nine years starting on the date of its entry into force and permitted a further extension of three additional years upon expiry of the first nine year period at the same rental rates paid during the ninth year.', 'en', 'Rent Laws: Law No. 159/1992 (New Leases), Law No. 160/1992 (Old Leases), and Law No. 9/2014 (New Tenancy Law), Article 9/2014-2', 'Transition Period and Extension', 'Property Law'),
  ('LB-PROP-001', '9/2014-3', 'Rent Increase Formula: During the period of the lease agreement extension, rents increase by a gradual percentage – a percentage of the dwelling''s rental value in the free market – that is either agreed upon by the mutual consent of the contracting parties or determined, in case of disagreement, by two court experts. The free market rental value is determined on the basis of 5% of the sale value of the rented dwelling in its current condition if vacant. Increases proceed: by 15% of the difference between old and new rental value for each of the first four extended years; by 20% of the difference for each of the fifth and sixth years, until fees reach the full rental value; after this time, between the seventh and the ninth extended years, the property will be rented at free market prices.', 'en', 'Rent Laws: Law No. 159/1992 (New Leases), Law No. 160/1992 (Old Leases), and Law No. 9/2014 (New Tenancy Law), Article 9/2014-3', 'Rent Increase Formula', 'Property Law'),
  ('LB-PROP-001', '9/2014-4', 'Eviction in Case of Necessity: If the landlord wishes to recover his property for family-related reasons during the first year of the nine-year extension period, he shall pay the tenant a compensation equivalent to the rental cost sustained over four years on the basis of the specified free market rental value. However, if he plans to evict the tenant in the first year in order to demolish the building and replace it with a newer one, he shall pay the tenant a compensation amounting to the annual rents paid within six years.', 'en', 'Rent Laws: Law No. 159/1992 (New Leases), Law No. 160/1992 (Old Leases), and Law No. 9/2014 (New Tenancy Law), Article 9/2014-4', 'Eviction in Case of Necessity', 'Property Law'),
  ('LB-PROP-001', '9/2014-5', 'Rent Assistance Fund: A rent assistance fund is established to support needy tenants unable to afford the rent increases. The fund excludes foreign tenants and Lebanese tenants who rent property deemed luxurious. The implementation of the provisions related to the rent increases and the applications submitted to the fund for assistance will be entrusted to a judicial committee consisting of a judge – active or retired – and four members, one representing landlords, one tenants and two representing the Ministry of Finance and the Ministry of Social Affairs. The committee specifies the size of contributions depending on the income of the tenant and his household. If the average household income is not at least twice the minimum wage, the assistance of the fund covers the entire difference between the old and revised rental fees.', 'en', 'Rent Laws: Law No. 159/1992 (New Leases), Law No. 160/1992 (Old Leases), and Law No. 9/2014 (New Tenancy Law), Article 9/2014-5', 'Rent Assistance Fund', 'Property Law'),
  ('LB-PROP-001', NULL, 'Post-civil war Lebanon enacted two complementary rent laws in July 1992. Law No. 159 of July 22, 1992 introduced ''freedom of contract'' for new leases (signed after July 22, 1992), replacing the previous mandatory renewal system. Law No. 160 of July 22, 1992 governed old leases (signed before July 23, 1992), providing a phased rent increase framework and limited landlord rights to reclaim property. Law No. 160 was extended 12 times over the following decades. In April 2014, the New Tenancy Law (Law 9/2014) was enacted to gradually liberalize all old rent contracts through a 9-year transition period with annual rent increases tied to property market values, supported by a rent assistance fund for vulnerable tenants.', 'en', 'Rent Laws: Law No. 159/1992 (New Leases), Law No. 160/1992 (Old Leases), and Law No. 9/2014 (New Tenancy Law) — Historical Context', 'Historical context and overview', 'Property Law'),
  ('LB-ADMIN-001', '1', 'Role of Supreme Judicial Council: The Supreme Judicial Council shall ensure the good conduct and independence of the judicial process and the proper functioning in courts and shall take the necessary decisions in this regard.', 'en', 'Judicial Organization Decree-Law No. 150/1983 (Draft Amending Law as submitted to the Venice Commission in 2022), Article 1', 'Role of Supreme Judicial Council', 'Administrative Law'),
  ('LB-ADMIN-001', '2', 'Council Composition: The Supreme Judicial Council shall be composed of ten members as follows: A- Statutory Members: First President of Court of Cassation (''President''); Attorney-General before Court of Cassation (''Vice-President''); President of Judicial Inspection Authority (''Member''). Such Statutory Members shall be appointed for four renewable years. B- Elected Members, who are: Accredited Judge as one of the Chamber Presidents in Court of Cassation; Accredited Judge as one of the Counsellors in Court of Cassation; Accredited Judge as one of the Chamber Presidents in Courts of Appeal; Accredited Judge as one of the Counsellors in Courts of Appeal; Accredited Judge as one of the Investigation Judges; Accredited Judge as one of the Chambers Presidents in Courts of First Instance; Accredited Judge as one of the Duty Judges and Sole Judges.', 'en', 'Judicial Organization Decree-Law No. 150/1983 (Draft Amending Law as submitted to the Venice Commission in 2022), Article 2', 'Council Composition', 'Administrative Law'),
  ('LB-ADMIN-001', '4', 'Election of Members: The electing authority composed of all judges shall meet in the Palace of Justice in Beirut on the calling date. The election shall be made by the secret ballot, and every judge shall elect two candidates from the declared candidates list; conditioned that a judge shall choose at least one candidate from his original category.', 'en', 'Judicial Organization Decree-Law No. 150/1983 (Draft Amending Law as submitted to the Venice Commission in 2022), Article 4', 'Election of Members', 'Administrative Law'),
  ('LB-ADMIN-001', '5', 'Term of Office: The nomination period of the elected members shall be three non-renewable years, except after passing a full period of their leaving the membership of the Supreme Judicial Council. The employment period of the Supreme Judicial Council members shall expire in case of death, resignation, and retirement or of issuance of a resolution related to applying a conduct penalty.', 'en', 'Judicial Organization Decree-Law No. 150/1983 (Draft Amending Law as submitted to the Venice Commission in 2022), Article 5', 'Term of Office', 'Administrative Law'),
  ('LB-ADMIN-001', '7', 'Obligations of Members: Neither member of the Supreme Judicial Council nor any of his relatives of Judges shall be transferred from one office to another till the second degree throughout his office period. A member may not, even after expiration of his office period, be candidate for the presidential, prosecution or municipal elections, nor be appointed as a minister or member in the constitutional council. The Bank Confidentiality of the Supreme Judicial Council members, their wives and minors shall be disclosed for the benefit of the National Authority for Combating Corruption and the Judicial Inspection Authority, immediately after the beginning of the Council''s works.', 'en', 'Judicial Organization Decree-Law No. 150/1983 (Draft Amending Law as submitted to the Venice Commission in 2022), Article 7', 'Obligations of Members', 'Administrative Law'),
  ('LB-ADMIN-001', '8', 'General Power of the Council: The Council shall ensure the moral and material rights of judges, their fairness, and everything related to their independence, appointment, formation, transfer and discipline. The Council exercises this authority in accordance with the provisions of this law and other laws in force.', 'en', 'Judicial Organization Decree-Law No. 150/1983 (Draft Amending Law as submitted to the Venice Commission in 2022), Article 8', 'General Power of the Council', 'Administrative Law'),
  ('LB-ADMIN-001', '10', 'Complaints: Any person may file a complaint with the Supreme Judicial Council; provided that it is related to the functioning of the public service of justice, the conduct of the judge, or the independence of the judiciary. The complaint shall be in writing, signed, and shall contain the full name of the complainant, the date and a brief description of the facts.', 'en', 'Judicial Organization Decree-Law No. 150/1983 (Draft Amending Law as submitted to the Venice Commission in 2022), Article 10', 'Complaints', 'Administrative Law'),
  ('LB-ADMIN-001', '17', 'Council Meetings and Decisions: The Council meets at the call of its president. The call requires convening the Council at least once a week. The sessions of the Council shall not be deemed to be legal unless two thirds of its members are present. Except for cases in which the law provides for a special majority, the decisions of the Council shall be taken by a majority vote of those present. In the event of equality, the vote of the chairman shall be deemed the casting vote. In all cases and regardless of the number of attending members, no decision is taken for the Supreme Council with less than five votes.', 'en', 'Judicial Organization Decree-Law No. 150/1983 (Draft Amending Law as submitted to the Venice Commission in 2022), Article 17', 'Council Meetings and Decisions', 'Administrative Law'),
  ('LB-ADMIN-001', '21', 'Right of Appeal Against Council Decisions: Individual and non-organizational decisions issued by the Council are subject to appeal before the General Assembly of the Court of Cassation. The review of the challenge shall be submitted according to the emergency procedures, within two weeks from the date of its notification to the person concerned. The review shall not suspend the implementation of the challenged decisions unless the General Authority of the Court of Cassation decides to suspend the execution.', 'en', 'Judicial Organization Decree-Law No. 150/1983 (Draft Amending Law as submitted to the Venice Commission in 2022), Article 21', 'Right of Appeal Against Council Decisions', 'Administrative Law'),
  ('LB-ADMIN-001', '22', 'Court System Structure: The Courts of Justice include: A- Courts of First Instance. B- Courts of Appeal. C- Court of Cassation. In addition to the specialized courts established by law, which consist of court judges or in which a court judge participates.', 'en', 'Judicial Organization Decree-Law No. 150/1983 (Draft Amending Law as submitted to the Venice Commission in 2022), Article 22', 'Court System Structure', 'Administrative Law'),
  ('LB-ADMIN-001', '23', 'Courts of First Instance: Courts of the First Instance are composed of chambers that pass judgments on a president and two members. The number of courts of First Instance, their chambers and sections, the centres of these chambers and sections, and the scope of their spatial jurisdiction shall be specified in the relevant Table.', 'en', 'Judicial Organization Decree-Law No. 150/1983 (Draft Amending Law as submitted to the Venice Commission in 2022), Article 23', 'Courts of First Instance', 'Administrative Law'),
  ('LB-ADMIN-001', '24', 'Courts of Appeal are composed of chambers whose judgments are ruled by a president and two counsellors. Each Court of Appeal shall have a Public Prosecution presided by an Appellate Attorney-General assisted by one or more public attorneys, and an investigation department composed of a first investigative judge assisted by one or more investigative judges.', 'en', 'Judicial Organization Decree-Law No. 150/1983 (Draft Amending Law as submitted to the Venice Commission in 2022), Article 24', 'Courts of Appeal', 'Administrative Law'),
  ('LB-ADMIN-001', '25', 'The Court of Cassation has a General authority composed of the presidents of Court Chambers. The Court of Cassation shall have a Public Prosecution presided by the Public Prosecutor at the Court of Cassation, assisted by Public Attorneys. Each chamber consists of a chairman and two counsellors exclusively.', 'en', 'Judicial Organization Decree-Law No. 150/1983 (Draft Amending Law as submitted to the Venice Commission in 2022), Article 25', 'Court of Cassation', 'Administrative Law'),
  ('LB-ADMIN-001', '36', 'Headquarters of the Court of Cassation: The headquarters of the Court of Cassation shall be in Beirut.', 'en', 'Judicial Organization Decree-Law No. 150/1983 (Draft Amending Law as submitted to the Venice Commission in 2022), Article 36', 'Headquarters of the Court of Cassation', 'Administrative Law'),
  ('LB-ADMIN-001', '39', 'First President of Court of Cassation: First President, President of the Supreme Judicial Council, shall preside over the Court of Cassation and its general authority, and the Judicial Council in accordance with the provisions of Article (2) of this law, and he shall also preside over the Judicial Council.', 'en', 'Judicial Organization Decree-Law No. 150/1983 (Draft Amending Law as submitted to the Venice Commission in 2022), Article 39', 'First President of Court of Cassation', 'Administrative Law'),
  ('LB-ADMIN-001', NULL, 'Decree-Law No. 150 of September 16, 1983 governs the organization of Lebanon''s ordinary courts (distinct from religious/personal status courts and the State Council for administrative courts). It establishes the structure of the court system, the composition and powers of the High Judicial Council (HJC), the appointment and discipline of judges, and related matters. The original decree has been criticized by international bodies including the ICJ and Venice Commission for allowing executive influence over judicial appointments and transfers. A draft law amending Decree-Law 150/83 was submitted to the Venice Commission in April 2022 and is reflected in the articles below.', 'en', 'Judicial Organization Decree-Law No. 150/1983 (Draft Amending Law as submitted to the Venice Commission in 2022) — Historical Context', 'Historical context and overview', 'Administrative Law'),
  ('LB-BANK-001', NULL, 'Inspired by the Swiss banking system, this law established Lebanon as a banking secrecy haven, attracting regional deposits and earning Lebanon the title ''Switzerland of the Middle East.'' Absolute secrecy binds bank managers and employees from disclosing client names, assets, and transactions to any authority. Code-numbered accounts permitted. The law has been progressively weakened since 2001 through anti-money laundering legislation and the 2022 partial lifting during the financial crisis. However, significant secrecy protections remain, making forensic investigations of the banking sector challenging.', 'en', 'Banking Secrecy Law — Historical Context', 'Historical context and overview', 'Banking & Financial'),
  ('LB-BANK-001', NULL, 'Created Special Investigation Commission with authority to lift banking secrecy for money laundering investigations.', 'en', 'Banking Secrecy Law — Amendment: Law No. 318/2001 (Anti-Money Laundering)', 'Amendment', 'Banking & Financial'),
  ('LB-BANK-001', NULL, 'Updated anti-money laundering framework; expanded grounds for lifting secrecy.', 'en', 'Banking Secrecy Law — Amendment: Law No. 44/2015 (replaced Law 318)', 'Amendment', 'Banking & Financial'),
  ('LB-BANK-001', '2, 3, 7', 'Partially lifted banking secrecy for the benefit of forensic audit of the central bank and public institutions. Major reform in response to the financial crisis.', 'en', 'Banking Secrecy Law — Amendment: Law No. 306/2022 (Partial Lifting)', 'Amendment', 'Banking & Financial'),
  ('LB-BANK-002', NULL, 'Established the Banque du Liban (BDL / مصرف لبنان) as Lebanon''s central bank and defined the monetary policy framework. Replaced the previously existing currency board arrangement. Defines BDL''s role in monetary stability, bank supervision, exchange rate policy, and lender of last resort functions. The Code became the subject of intense scrutiny during the post-2019 financial crisis, with debates about BDL''s financial engineering operations, loss allocation, and the need for fundamental reform of the monetary system.', 'en', 'Code of Money and Credit — Historical Context', 'Historical context and overview', 'Banking & Financial'),
  ('LB-BANK-002', 'various', 'Amended bank licensing and capital requirements. Required Central Bank authorization for new banks.', 'en', 'Code of Money and Credit — Amendment: Decree-Law No. 77/1977', 'Amendment', 'Banking & Financial'),
  ('LB-BANK-002', NULL, 'Amended provisions related to central bank operations.', 'en', 'Code of Money and Credit — Amendment: Law No. 67/2017', 'Amendment', 'Banking & Financial'),
  ('LB-BANK-003', NULL, 'Replaced Law No. 318/2001 (which itself replaced initial AML provisions). Expanded the mandate of the Special Investigation Commission (SIC), broadened predicate offenses, enhanced know-your-customer requirements, and aligned Lebanon with FATF recommendations. The SIC has exclusive authority to decide on lifting banking secrecy for AML/CFT investigations.', 'en', 'Law on Fighting Money Laundering and Terrorist Financing — Historical Context', 'Historical context and overview', 'Banking & Financial'),
  ('LB-BANK-004', NULL, 'Requires declaration of cash above a threshold when entering or leaving Lebanon. Part of the 2015 package of financial reform laws addressing FATF requirements.', 'en', 'Law on Declaring Cross-Border Transportation of Money — Historical Context', 'Historical context and overview', 'Banking & Financial'),
  ('LB-BANK-005', NULL, 'Prohibited insider trading using material non-public information. Part of efforts to develop Lebanon''s capital markets framework.', 'en', 'Law Prohibiting Insider Trading — Historical Context', 'Historical context and overview', 'Banking & Financial'),
  ('LB-BANK-006', NULL, 'Established the Capital Markets Authority (CMA / هيئة الأسواق المالية) to regulate and supervise Lebanon''s financial markets. Governs the Beirut Stock Exchange (BSE), broker-dealer operations, and securities issuance.', 'en', 'Financial Markets Law / Capital Markets Law — Historical Context', 'Historical context and overview', 'Banking & Financial'),
  ('LB-BANK-007', NULL, 'Established a banking free zone exempting non-resident foreign currency deposits from certain taxes and reserve requirements. Designed to attract offshore banking activity to Beirut.', 'en', 'Banking Free Zone — Historical Context', 'Historical context and overview', 'Banking & Financial'),
  ('LB-BANK-007', NULL, 'Removed income tax exemption on deposit interest for non-resident accounts.', 'en', 'Banking Free Zone — Amendment: Law No. 497/2003 (Budget Law, Art. 51)', 'Amendment', 'Banking & Financial'),
  ('LB-BANK-008', NULL, 'Authorized banks to open joint accounts with single-signature operation. Important for banking convenience and asset planning.', 'en', 'Joint Bank Accounts Law — Historical Context', 'Historical context and overview', 'Banking & Financial'),
  ('LB-BANK-009', NULL, 'Partially lifted banking secrecy for benefit of forensic audit of the Central Bank (BDL) and public institutions. A key reform demanded by the international community (IMF, World Bank, FATF) in the context of Lebanon''s financial crisis. Also lifted secrecy for tax authorities, anti-corruption bodies, and judicial investigations into public funds. Landmark legislation representing a significant shift in Lebanon''s banking secrecy tradition.', 'en', 'Amendment to Banking Secrecy Law (Partial Lifting) — Historical Context', 'Historical context and overview', 'Banking & Financial'),
  ('LB-BANK-010', NULL, 'In the context of Lebanon''s 2019 financial crisis, banks imposed de facto capital controls without legal basis. Multiple draft capital controls laws were debated in Parliament from 2020 onward. The absence of a formal capital controls law while banks restricted withdrawals was widely criticized as illegal and unconstitutional. Note: actual passage/status of this law requires verification as multiple versions were debated.', 'en', 'Capital Controls Law (Draft/Debated) — Historical Context', 'Historical context and overview', 'Banking & Financial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-2006-98', 'The Lebanese Court of Cassation held that the criteria for determining whether arbitration is international in nature are economic, specifically whether the underlying dispute involves a cross-border flow of goods or funds, as defined by Article 809 NCPC. The Court further ruled that interest awarded by arbitral tribunals may exceed the value of legal interest as determined by Lebanese law and that such awards are not subject to review in annulment proceedings. Legal principles established: International arbitration is determined by economic criteria: cross-border flow of goods or funds; Arbitral interest awards may exceed the statutory legal interest rate; Interest awards by arbitral tribunals are not reviewable in annulment proceedings Articles cited: Article 809 NCPC, Article 767 COC', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-2006-98', '[CASE LAW] Lebanese Court of Cassation - Decision 98/2006 (2006-04-27)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-2014-14', 'The Lebanese Court of Cassation confirmed that the doctrine of competence-competence applies to international arbitration proceedings in Lebanon, meaning an arbitral tribunal has priority to rule on its own jurisdiction before courts intervene. The Court also extended the binding effect of an arbitration agreement to a non-signatory company by virtue of the economic unity existing between that company and the signatories, without requiring the non-signatory to have participated in the drafting or execution of the agreement, or even to have knowledge of it. Legal principles established: Competence-competence doctrine applies to international arbitration in Lebanon; Non-signatory bound by arbitration agreement through economic unity principle; Economic unity test does not require participation in drafting, execution, or knowledge of the agreement Articles cited: Article 785 NCPC, Articles 766, 763 NCPC', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-2014-14', '[CASE LAW] Lebanese Court of Cassation - Decision 14/2014 (2014-01-25)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-1999-77', 'The Lebanese Court of Cassation established the conflict-of-law rule for determining the law governing arbitration agreements. The Court held that proof of an arbitration agreement and its extension over time is governed either by the law applicable to the effects of the agreement or by the law of the place where the agreement was concluded, as codified in Article 139(1) of the NCPC. This confirms that Lebanese courts apply classic conflict-of-law rules regardless of the place of arbitration. Legal principles established: Governing law of arbitration agreement is either law of effects or law of place of conclusion; Classic conflict-of-law rules apply regardless of seat of arbitration Articles cited: Article 139(1) NCPC', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-1999-77', '[CASE LAW] Lebanese Court of Cassation - Decision 77/99 (1999-06-17)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-2004-150', 'The Lebanese Court of Cassation ruled that judges may act as arbitrators without legal restrictions, finding no statutory prohibition on active judges serving as arbitrators in private disputes. This decision confirmed Lebanese law''s permissive approach to arbitrator eligibility. Legal principles established: No restriction on judges serving as arbitrators under Lebanese law; Permissive approach to arbitrator eligibility', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-2004-150', '[CASE LAW] Lebanese Court of Cassation - Decision 150/2004 (2004-11-09)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-2002-136', 'The Lebanese Court of Cassation held that an arbitral award cannot be annulled on the ground of violation of public policy merely because the arbitrator misinterpreted the law. The annulment process is not an appeal on the merits; errors of legal interpretation do not by themselves constitute a public policy violation sufficient to invalidate an award. Legal principles established: Annulment is not appeal on merits; Legal misinterpretation by arbitrator does not constitute public policy violation; Narrow scope of review in annulment proceedings', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-2002-136', '[CASE LAW] Lebanese Court of Cassation - Decision 136/2002 (2002-10-31)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-2007-159', 'The Lebanese Court of Cassation reaffirmed that proceedings to set aside an arbitral award do not constitute an appeal on the merits or legality of the award. Courts reviewing annulment applications are precluded from examining the correctness of the arbitrator''s factual or legal determinations. This decision solidified the boundary between annulment and appellate review. Legal principles established: Set-aside proceedings are not merits review; Courts cannot examine factual or legal correctness of arbitral awards in annulment; Clear separation between annulment and appeal', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-2007-159', '[CASE LAW] Lebanese Court of Cassation - Decision 159/2007 (2007-12-18)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-2001-146', 'The Lebanese Court of Cassation ruled that the 1958 New York Convention on Recognition and Enforcement of Foreign Arbitral Awards applies in Lebanon only when its provisions are more favorable to the party seeking enforcement than the provisions of the Lebanese New Code of Civil Procedure. Under the NCPC''s international public policy standard, the NCPC was deemed more favorable, limiting the automatic application of the New York Convention. Legal principles established: New York Convention applies only when more favorable than NCPC; More-favorable-right rule applies to enforce arbitral awards; NCPC public policy standard is narrower than Convention''s Articles cited: Article VII(1) New York Convention, Article 814 NCPC', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-2001-146', '[CASE LAW] Lebanese Court of Cassation - Decision 146/2001 (2001-11-29)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-2002-29', 'The Lebanese Court of Cassation held that the disqualification or recusal of an arbitrator does not invalidate the underlying arbitration agreement. The agreement survives the removal of a particular arbitrator, and proceedings may continue with a replacement arbitrator. Legal principles established: Arbitration agreement survives recusal/disqualification of arbitrator; Recusal does not annul the arbitration agreement Articles cited: Article 770(3) NCPC', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-2002-29', '[CASE LAW] Lebanese Court of Cassation - Decision 29/2002 (2002-02-28)', 'commercial');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-2004-60', 'The Lebanese Court of Cassation ruled that when an arbitrator is disqualified, his mandate is revoked retroactively, and any awards rendered by that arbitrator in the proceedings are annulled as a consequence. This is the converse of Decision 29/2002, which protected the agreement itself, but here the Court addressed the effect on awards already issued. Legal principles established: Arbitrator disqualification revokes mandate retroactively; Awards rendered by disqualified arbitrator are annulled', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-2004-60', '[CASE LAW] Lebanese Court of Cassation - Decision 60/2004 (2004-04-01)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-2006-61', 'The Lebanese Court of Cassation held that Lebanese courts cannot raise the lack of arbitral jurisdiction on their own motion (ex officio). The existence of an arbitration clause is not a matter of public policy requiring courts to intervene spontaneously; parties must affirmatively invoke the arbitration agreement. If a party fails to raise the objection in a timely manner, it is deemed waived. Legal principles established: Arbitral jurisdiction is not a public policy issue courts must raise ex officio; Parties must affirmatively invoke arbitration agreements; Waiver of jurisdictional objection if not raised timely', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-2006-61', '[CASE LAW] Lebanese Court of Cassation - Decision 61/2006 (2006-03-22)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2003-464', 'The Beirut Court of Appeal affirmed that an arbitration agreement is legally independent and separable from the underlying contract in which it is contained. This means the invalidity, termination, or rescission of the main contract does not automatically render the arbitration clause null and void. The Court also held that parties may appoint a legal entity (as opposed to an individual) to serve in the role of appointing arbitrators. Legal principles established: Arbitration agreement is independent and separable from the main contract; Invalidity of main contract does not affect validity of arbitration clause; Legal entities may be appointed as arbitrator-appointing authorities', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2003-464', '[CASE LAW] Court of Appeal of Beirut - Decision 464/2003 (2003-04-03)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2008-767', 'The Beirut Court of Appeal confirmed the separability doctrine by ruling that the invalidity of the main contract does not entail the invalidity of the arbitration agreement it contains. This is a landmark restatement of the separability principle in Lebanese arbitration law, ensuring parties cannot avoid arbitration by challenging the underlying contract. Legal principles established: Invalidity of main contract does not invalidate arbitration clause (separability); Parties cannot avoid arbitration by challenging the main contract', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2008-767', '[CASE LAW] Court of Appeal of Beirut - Decision 767/2008 (2008-05-20)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2000-1417', 'The Beirut Court of Appeal held that Lebanese courts generally refrain from excluding a matter from arbitration solely on the basis that it involves a question of public policy. The Court rejected an expansive interpretation of Article 1037 of the Code of Obligations and Contracts as a bar to arbitration, affirming that arbitration can resolve most commercial disputes even those touching on regulatory or public interest considerations. Legal principles established: Public policy alone does not render a dispute non-arbitrable; Narrow interpretation of non-arbitrability exceptions Articles cited: Articles 762, 765 NCPC, Article 1037 COC', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2000-1417', '[CASE LAW] Court of Appeal of Beirut - Decision 1417/2000 (2000-12-19)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CFI-COMM-2015-376', 'The Beirut Court of First Instance ruled that Article 5 of Decree-Law 34/67, which grants Lebanese courts jurisdiction over commercial agency disputes, confers exclusive jurisdiction over other state courts (foreign courts) but not over arbitral tribunals. Therefore, disputes arising from commercial representation agreements are arbitrable and may be resolved by arbitration, reversing prior approaches that treated such disputes as non-arbitrable. Legal principles established: Article 5 of DL 34/67 grants exclusive jurisdiction over other state courts, not arbitral tribunals; Commercial agency disputes are arbitrable; Relevant to anti-suit injunctions in commercial representation contexts Articles cited: Article 5 of Decree-Law 34/67', 'en', 'Case Law Collection - Commercial, Article LB-CFI-COMM-2015-376', '[CASE LAW] Court of First Instance of Beirut - Decision 376/74/2013 (2015-07-14)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2004-9CH', 'The 9th Chamber of the Beirut Court of Appeal ruled that an arbitration clause in a commercial agency agreement is null and void under Article 5 of Decree-Law No. 34/67, which was interpreted to render all such disputes non-arbitrable. The Court held that the 1958 New York Convention only applies to disputes capable of arbitration under the lex fori, and since Lebanese law excluded commercial agency disputes under Article 5, the clause was invalid and the court retained jurisdiction. Legal principles established: Pre-dispute arbitration clause in agency agreement is null and void; Article 5 of DL 34/67 rendered agency disputes non-arbitrable (pre-2015 interpretation); New York Convention limited to disputes arbitrable under the law of the seised court Articles cited: Article 5 of Decree-Law 34 of August 5, 1967, 1958 New York Convention', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2004-9CH', '[CASE LAW] Court of Appeal of Beirut, 9th Chamber - Published: Al Adl Review 2005, Vol. 3, p. 540 (2004-10-07)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-2005-4', 'The Lebanese Court of Cassation drew a critical distinction between an arbitration clause (signed before or during agency agreement) and an arbitration agreement (concluded after the dispute arises). It ruled that while a pre-dispute arbitration clause in a commercial agency contract is void under Article 5 of DL 34/67, a post-dispute arbitration agreement is valid. After the dispute arises, the Lebanese representative is no longer in a subordinate position and can freely waive the statutory protections of Article 5. Legal principles established: Post-dispute arbitration agreement in agency context is valid; Pre-dispute arbitration clause in agency agreement remains void; After dispute arises, representative is free to agree to arbitration; Protective purpose of Article 5 DL 34/67 no longer applies once dispute has arisen Articles cited: Article 5 of Decree-Law 34 of August 5, 1967', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-2005-4', '[CASE LAW] Lebanese Court of Cassation, 5th Chamber - Decision No. 4/2005 (2005-01-11)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-2013-9-51', 'The Beirut Court of First Instance held that a company''s insolvency or entry into liquidation does not render its arbitration agreements null and void. The liquidator is bound to enforce outstanding arbitration agreements. The Court also confirmed that the absence of an express provision specifying the number of arbitrators in an arbitration agreement does not invalidate that agreement. Legal principles established: Insolvency does not nullify pre-existing arbitration agreements; Liquidator must enforce arbitration agreements; Absence of express arbitrator number does not nullify agreement', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-2013-9-51', '[CASE LAW] Court of First Instance of Beirut - Decision 9/51 (2013-02-13)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CFI-COMM-2013-2-44', 'The Beirut Court of First Instance held that a party who did not sign an arbitration agreement may nonetheless be bound by it if that party participated in the negotiation or implementation of the underlying agreement. This extends the reach of arbitration clauses to parties who are functionally part of the contractual relationship even if not formal signatories. Legal principles established: Participation in negotiation or implementation of agreement can bind non-signatories; Non-signatory test: substantive participation, not just formal signature', 'en', 'Case Law Collection - Commercial, Article LB-CFI-COMM-2013-2-44', '[CASE LAW] Court of First Instance of Beirut - Decision 2/44 (2013-01-14)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2003-1404', 'The Beirut Court of Appeal confirmed that arbitral proceedings and awards are confidential by nature, unlike public court judgments. The private nature of arbitration, combined with Article 553 NCPC and Article 788 NCPC, ensures that deliberations are secret and awards are not subject to the general principle of public access to justice that applies in state court proceedings. Legal principles established: Arbitral proceedings and awards are confidential; Confidentiality distinguishes arbitration from public court process; Deliberations of arbitral tribunals are secret Articles cited: Article 553 NCPC, Article 788 NCPC', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2003-1404', '[CASE LAW] Court of Appeal of Beirut - Decision 1404/2003 (2003-10-09)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2014-890', 'The Beirut Court of Appeal reaffirmed the principle that courts reviewing applications to set aside arbitral awards may not review the grounds, reasoning, or legal compliance of the award. The review is strictly limited to jurisdictional issues and procedural public policy, not the substantive correctness of the arbitral decision. Legal principles established: No review of award grounds or legal compliance in set-aside proceedings; Set-aside limited to jurisdictional and procedural public policy issues', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2014-890', '[CASE LAW] Court of Appeal of Beirut - Decision 890/2014 (2014-06-18)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2001-1778', 'The Beirut Court of Appeal ruled that the domestic NCPC procedural rules for challenging arbitrators apply to international ad hoc arbitration proceedings seated in Lebanon. The Court rejected arguments that international arbitration should follow different challenge procedures, applying the same standards for impartiality and independence that apply in domestic cases. Legal principles established: Domestic NCPC challenge rules apply to international ad hoc arbitration in Lebanon; Same impartiality and independence standards apply regardless of international or domestic nature Articles cited: Articles 770, 787(2) NCPC', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2001-1778', '[CASE LAW] Court of Appeal of Beirut - Decision 1778/2001 (2001-12-10)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-1973-16', 'The Lebanese Court of Cassation established early precedent that in commercial matters, parties are free to determine the interest rate applicable to their contractual relationship by agreement. There is no legal cap on interest rates in commercial transactions, and courts cannot modify interest rates agreed upon by sophisticated commercial parties. Legal principles established: Commercial parties may freely determine interest rates in their agreements; No statutory cap on interest rates in commercial matters', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-1973-16', '[CASE LAW] Lebanese Court of Cassation - Decision No. 16 (1973-02-22)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2010-294', 'The Beirut Court of Appeal (First Chamber) extended the binding effect of an arbitration clause to a third party based on the concept of ''economic unity'' or a single economic operation (''opération économique unique''). Even though the third party had not signed the main agreement containing the arbitration clause, the economic unity linking the chain of contracts rendered the arbitration clause applicable to it. Legal principles established: Arbitration clause may extend to third party via economic unity principle; Single economic operation can bind non-signatories to arbitration', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2010-294', '[CASE LAW] Court of Appeal of Beirut, First Chamber - Decision No. 294/2009 (2010-07-21)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2009-1100', 'The Beirut Court of Appeal held that courts do not have concurrent jurisdiction with arbitral tribunals for interim payment orders that would involve examining the merits of the dispute. Courts may assist with enforcement-type interim measures pre-tribunal formation, but provisional payment requests that require substantive assessment fall within the exclusive competence of the arbitral tribunal. Legal principles established: No concurrent court jurisdiction for interim payments requiring merits analysis; Courts may assist with enforcement-type interim measures pre-tribunal; Substantive interim relief falls within arbitral tribunal''s domain', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2009-1100', '[CASE LAW] Court of Appeal of Beirut - Decision 1100/2009 (2009-07-30)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-2012-832', 'The Beirut Court of Appeal granted enforcement (exequatur) to an arbitral award issued by an even-numbered tribunal in an international arbitration. Under the domestic NCPC rules for domestic arbitration, odd-numbered tribunals are standard, but the Court confirmed that for international arbitration, even-numbered panels are permissible and their awards can be enforced. Legal principles established: Even-numbered arbitral tribunals are permissible in international arbitration; Awards from even-numbered tribunals are enforceable in Lebanon Articles cited: Article 810 NCPC', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-2012-832', '[CASE LAW] Court of Appeal of Beirut - Decision 832/2012 (2012-05-16)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-2018-41', 'The Beirut Court of Appeal held that a state-owned or state-related entity (including an Iraqi bank with state interference) that conducts commercial operations subject to private law cannot claim immunity from execution when a judgment or arbitral award is entered against it. The court distinguished between governmental functions (which may attract immunity) and commercial activities (which do not). Legal principles established: State-related entities conducting commercial operations cannot claim immunity from execution; Commercial activities are subject to private law enforcement; State interference does not transform commercial entity into immune state actor Articles cited: Article 860 LCCP', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-2018-41', '[CASE LAW] Court of Appeal of Beirut - Decision no. 41/2018 (2018-01-10)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2012-ARBIT', 'The Beirut Court of Appeal held that when granting exequatur (recognition and enforcement) to an arbitral award, the court''s review is strictly limited to verifying manifest conformity with international public policy. No merits review of the award''s factual findings, legal analysis, or procedural correctness may take place in exequatur proceedings. This decision reinforced the minimal-intervention principle in the enforcement of international arbitral awards. Legal principles established: Exequatur review limited to manifest international public policy violation; No merits review permitted in exequatur of international arbitral awards; Strong pro-enforcement policy in Lebanon for international arbitral awards', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2012-ARBIT', '[CASE LAW] Court of Appeal of Beirut - Decision 1786/2011 (2012-12-21)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2010-28', 'The Court of Appeal of Mount Lebanon confirmed that a decision by an arbitral tribunal on its own jurisdiction cannot be challenged or appealed before a final award is issued. Following the Court of Cassation''s Decision 13/2007, this ruling confirmed that Article 615 NCPC (which lists challengeable interlocutory decisions in court proceedings) must be transposed to arbitration, and jurisdictional decisions are not on that list. Challenges to jurisdiction must wait until the final award is rendered. Legal principles established: Arbitral tribunal''s jurisdiction decision not appealable before final award; Article 615 NCPC applied by analogy to arbitration proceedings; Jurisdictional challenges must be raised at annulment/enforcement stage Articles cited: Articles 615, 804 NCPC', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2010-28', '[CASE LAW] Court of Appeal of Mount Lebanon - Decision 28/2010 (2010-03-04)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2010-ML', 'The Court of Appeal of Mount Lebanon held that in multiparty arbitration proceedings, separate respondents with distinct legal personalities and different interests cannot be forced to share a single arbitrator between them. Such a requirement would violate the principle of equality between the parties in the appointment of arbitrators, which constitutes a matter of public policy. Each party with distinct interests has the right to participate in the constitution of the arbitral tribunal. Legal principles established: Equality principle in arbitrator appointment is public policy; Separate respondents with distinct interests cannot be compelled to share one arbitrator; Multiparty arbitration must respect equality in tribunal constitution', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2010-ML', '[CASE LAW] Court of Appeal of Mount Lebanon - Decision (unspecified) (2010-10-19)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-1996-8', 'The Lebanese Court of Cassation ruled that courts have jurisdiction to grant interim relief before an arbitral tribunal has been constituted, unless the parties have agreed otherwise in their arbitration agreement. This confirms a concurrent jurisdiction framework for pre-arbitration interim measures, ensuring parties can seek urgent court protection before arbitrators can be appointed and organized. Legal principles established: Courts have jurisdiction for interim relief before arbitral tribunal constituted; Parties may contractually limit court''s interim jurisdiction; Concurrent jurisdiction framework for pre-arbitration urgent measures', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-1996-8', '[CASE LAW] Lebanese Court of Cassation - Decision 8/2006 (1996-01-19)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2009-454', 'The Beirut Court of Appeal reaffirmed that annulment proceedings do not permit a review of the grounds, reasoning, or legal compliance of an arbitral award. The court''s role in annulment is strictly supervisory and procedural, not substantive. Any error in law or fact by the arbitral tribunal does not constitute a ground for annulment unless it rises to the level of a violation of public policy or breach of due process. Legal principles established: Annulment courts cannot review grounds or law compliance of arbitral awards; Strict separation between annulment and appellate review; Legal/factual errors by arbitrators are not annulment grounds unless public policy breached', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2009-454', '[CASE LAW] Court of Appeal of Beirut - Decision 454/2009 (2009-03-26)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2011-308', 'In an exceptional and rarely cited decision, the Beirut Court of Appeal reviewed the arbitrator''s application of law in an annulment proceeding, treating compliance with the applicable law as part of the arbitrator''s mandate. This decision represents a departure from the standard no-merits-review rule and has been noted as exceptional in Lebanese arbitration jurisprudence. Legal principles established: Exceptional case where court reviewed law application as mandate compliance issue; Departure from general no-merits-review principle in annulment; Not representative of the dominant approach in Lebanese arbitration law', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2011-308', '[CASE LAW] Court of Appeal of Beirut - Decision 308/2011 (2011-03-03)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CFI-COMM-2013-24-63', 'The Beirut Court of First Instance ruled that the presence of an invalid or void term in an arbitration agreement does not automatically render the entire arbitration agreement null and void. Courts should apply severance principles to preserve the valid components of the arbitration agreement, treating the invalid provision as severable. This upholds the general pro-arbitration presumption in Lebanese law. Legal principles established: Severability applies to arbitration agreements - invalid term does not void entire agreement; Pro-arbitration presumption favors preserving valid components; Courts sever invalid provisions rather than nullifying entire arbitration agreement', 'en', 'Case Law Collection - Commercial, Article LB-CFI-COMM-2013-24-63', '[CASE LAW] Court of First Instance of Beirut - Decision 24/63 (2013-06-05)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-1993-766', 'The Beirut Court of Appeal established an early and foundational precedent that arbitrators must be impartial and independent as a condition of their appointment and throughout the arbitral proceedings. Failure to maintain these qualities provides grounds for challenge and removal. The Court applied the same standards of conduct to arbitrators as those applied to judicial officers under Lebanese procedural law. Legal principles established: Impartiality and independence are mandatory qualities for arbitrators; Failure to maintain impartiality/independence is ground for challenge; Arbitrators held to same standard as judges in terms of conduct', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-1993-766', '[CASE LAW] Court of Appeal of Beirut - Decision 766/93 (1993-12-27)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CFI-COMM-2014-194', 'The Beirut Court of First Instance, applying Article II(3) of the New York Convention and Article 764 NCPC, ruled that when a party disputes the court''s jurisdiction by invoking an arbitration agreement, the court''s review is limited to a prima facie or manifest validity assessment of the agreement. The court should only decline to stay proceedings and refer parties to arbitration if the arbitration agreement is manifestly invalid, not upon a full merits analysis of the agreement''s validity. Legal principles established: Court''s review of arbitration agreement validity limited to prima facie/manifest invalidity test; Article II(3) NYC requires courts to refer to arbitration unless agreement is manifestly null and void; Full merits analysis of arbitration agreement validity not appropriate at this stage Articles cited: Article II(3) New York Convention, Article 764 NCPC', 'en', 'Case Law Collection - Commercial, Article LB-CFI-COMM-2014-194', '[CASE LAW] Court of First Instance of Beirut - Decision 194/2014 (2014-02-26)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2001-492', 'The Beirut Court of Appeal established that the criteria for determining whether arbitration is international in nature are economic rather than formal or legal. An arbitration is international if the underlying transaction involves cross-border flows of goods, services, or funds. This economic test, later confirmed by the Court of Cassation in Decision 98/2006, remains the controlling standard for classifying arbitrations under the NCPC''s different domestic and international arbitration regimes. Legal principles established: Internationality of arbitration determined by economic criteria; Cross-border flow of goods, services, or funds establishes international character; Formal or national/legal criteria not determinative of international arbitration status Articles cited: Article 809 NCPC', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2001-492', '[CASE LAW] Court of Appeal of Beirut - Decision 492/2001 (2001-03-21)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2008-192', 'The Third Chamber of the Beirut Court of Appeal extended an arbitration clause to a third party who was part of a chain of contracts forming a single economic operation (''opération économique unique''). The Court held that where contracts are economically linked as part of a single operation, parties to related contracts in the chain may be bound by the arbitration agreement even if they did not directly sign it. Legal principles established: Economic unity/single economic operation extends arbitration agreement to related parties; Third parties in chain of contracts may be bound by arbitration clause; Economic linkage test for extending arbitration agreements', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2008-192', '[CASE LAW] Court of Appeal of Beirut, Third Chamber - Decision No. 192/2008 (2008-02-05)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-2011-1725', 'The Beirut Court of Appeal confirmed that interest awards made by arbitral tribunals are not subject to review in annulment proceedings. The Court held that arbitral tribunals have autonomy in awarding interest, including at rates that may differ from the statutory legal interest rate under Lebanese law, and courts cannot second-guess these determinations in an annulment context. Legal principles established: Interest awards by arbitral tribunals not subject to annulment review; Arbitral autonomy on interest rate determination; No review of compliance with statutory interest rate limitations in annulment Articles cited: Article 767 COC', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-2011-1725', '[CASE LAW] Court of Appeal of Beirut - Decision 1725/2001 (2011-11-29)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CFI-ML-2001-25', 'The Court of First Instance of Mount Lebanon confirmed that courts should refrain from declaring matters non-arbitrable solely on the basis that they involve public policy issues. This decision reinforces the Beirut Court of Appeal''s Decision 1417/2000, establishing a consistent jurisprudential line that public policy is not an automatic bar to arbitration in Lebanon. Legal principles established: Public policy issues alone do not render disputes non-arbitrable; Consistent pro-arbitration policy across Lebanese courts; Narrow interpretation of non-arbitrability based on public policy Articles cited: Articles 762, 765 NCPC, Article 1037 COC', 'en', 'Case Law Collection - Commercial, Article LB-CFI-ML-2001-25', '[CASE LAW] Court of First Instance of Mount Lebanon - Decision 25/2001 (2001-06-25)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2011-1786', 'The Beirut Court of Appeal issued a comprehensive ruling on the standard of review in both set-aside and enforcement proceedings for international arbitral awards. The Court reaffirmed that no merits review is permitted in either context, and that exequatur proceedings are limited to verifying that the award does not manifestly violate international public policy. This decision is frequently cited as the leading authority on Lebanese enforcement standards. Legal principles established: No merits review in set-aside or enforcement proceedings; Exequatur limited to manifest international public policy verification; Award validity not assessed on legal correctness in enforcement proceedings', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2011-1786', '[CASE LAW] Court of Appeal of Beirut - Decision 1786/2011 (2011-12-21)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CFI-COMM-1991-197', 'The Beirut Court of First Instance established an early precedent that the exequatur judge reviewing an arbitral award for enforcement purposes conducts only an administrative, summary review. The judge does not review the merits of the underlying dispute or the correctness of the award. This case, along with Decision 123/95 of Mount Lebanon, forms the foundation of Lebanon''s pro-enforcement approach to arbitral awards. Legal principles established: Exequatur review is administrative and summary in nature; No merits review by exequatur judge; Early foundation of Lebanon''s pro-enforcement arbitration policy Articles cited: Articles 796(2), 800 NCPC', 'en', 'Case Law Collection - Commercial, Article LB-CFI-COMM-1991-197', '[CASE LAW] Court of First Instance of Beirut - Decision 197/3 (1991-07-17)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CFI-COMM-1984-777', 'The Beirut Judge of Expedited Matters established that in Lebanese arbitration law, the powers of an arbitral tribunal to order interim measures are concurrent with those of the court''s expedited matters judge (juge des référés). Both can be approached for urgent interim relief, and there is no exclusivity of jurisdiction in favor of either. This early decision laid the groundwork for Lebanon''s dual-track approach to interim measures in arbitration. Legal principles established: Concurrent jurisdiction: arbitral tribunal and expedited judge for interim measures; No exclusivity of jurisdiction for interim relief in favor of tribunal or court; Dual-track approach to urgent measures in arbitral proceedings Articles cited: Article 789 NCPC', 'en', 'Case Law Collection - Commercial, Article LB-CFI-COMM-1984-777', '[CASE LAW] Judge of Expedited Matters (Juge des Référés), Beirut - Decision 777/84 (1984-09-07)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2009-454-2', 'The Court of Appeal confirmed that the economic nature of an arbitration is determined by the substance of the underlying transaction. Where the parties'' relationship involves cross-border economic elements, the arbitration is classified as international under Article 809 NCPC. This decision is part of a consistent line of authority on the international/domestic classification issue. Legal principles established: Economic substance of transaction determines international arbitration classification; Cross-border economic elements trigger international arbitration regime Articles cited: Article 809 NCPC', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2009-454-2', '[CASE LAW] Court of Appeal of Beirut - Decision 492/2001 (2011-03-21)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-2002-132', 'The Lebanese Court of Cassation confirmed that arbitral tribunals in Lebanon have broad powers to grant any remedy in resolving contractual disputes, including ordering specific performance of contractual obligations or addressing consequences of non-performance. The Lebanese Arbitration Law does not limit arbitral remedies, and courts consistently recognize arbitral tribunals'' power to issue performance orders. Legal principles established: Arbitral tribunals have unlimited remedial powers including specific performance; No restriction on types of remedies available to arbitral tribunals in Lebanon; Specific performance and non-performance consequences within arbitral jurisdiction Articles cited: Articles 762-821 NCPC (Lebanese Arbitration Law)', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-2002-132', '[CASE LAW] Lebanese Court of Cassation - Decision 132/2002 (2002)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-2006-22', 'The Lebanese Court of Cassation held that a party waives its right to invoke an arbitration agreement if it does not raise the arbitration objection at the outset of court proceedings (in limine litis - at the first available opportunity). Courts do not raise arbitration agreements ex officio; the objection must be timely raised by the interested party or it is deemed waived. Procedural delay in asserting the arbitration agreement results in submission to court jurisdiction. Legal principles established: Arbitration agreement must be invoked in limine litis to avoid waiver; Courts do not raise arbitration agreements on their own motion; Failure to timely invoke arbitration agreement = waiver of right', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-2006-22', '[CASE LAW] Lebanese Court of Cassation - Decision 61/2006 (2006-03-22)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2013-ARBIT', 'The Beirut Court of Appeal held that entering into an arbitration agreement constitutes an act within the ordinary day-to-day management of a company, and therefore does not require prior board authorization. Company management has authority to sign arbitration agreements as part of normal commercial operations without seeking specific approval from the board of directors. Legal principles established: Signing arbitration agreement falls within ordinary management powers; No prior board approval required for arbitration agreement; Arbitration agreement is routine commercial act, not extraordinary decision', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2013-ARBIT', '[CASE LAW] Beirut Court of Appeal - Decision (recent, unspecified) (2013-05-16)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2011-CONF', 'The Beirut Court of First Instance extended an arbitration agreement to non-signatory sellers by applying the doctrine of economic unity, finding that the sellers participated in the conclusion and execution of the underlying contract. The Court held that substantive participation in the formation and performance of the contractual relationship creates a basis for extension even without formal signature of the arbitration clause. Legal principles established: Economic unity extension to non-signatory parties based on participation in conclusion/execution; Substantive contractual participation can substitute for formal signature; Seller participating in contract conclusion bound by arbitration clause', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2011-CONF', '[CASE LAW] Court of First Instance of Beirut - Decision of 27 June 2011 (2011-06-27)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CFI-ML-1995-123', 'The Court of First Instance of Mount Lebanon confirmed that the exequatur procedure for recognition and enforcement of arbitral awards is administrative and summary in character. The judge granting exequatur does not conduct a substantive review of the award''s merits, legal conclusions, or factual findings. This early decision is part of the consistent Lebanese approach to pro-enforcement arbitration. Legal principles established: Exequatur procedure is administrative and summary; No substantive review of award in exequatur proceedings; Pro-enforcement bias in Lebanese approach to arbitral award recognition', 'en', 'Case Law Collection - Commercial, Article LB-CFI-ML-1995-123', '[CASE LAW] Court of First Instance of Mount Lebanon - Decision 123/95 (1995-10-12)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-2001-163', 'The Lebanese Court of Cassation ruled that international arbitral awards are not subject to ordinary appeal on the merits or law. The only available recourse is an application to annul (set aside) the award on the specific, limited grounds provided in the NCPC. This bars appellate review of international awards and restricts post-award judicial intervention to the annulment process. Legal principles established: International arbitral awards are not subject to ordinary appeal; Only annulment/set-aside available for international awards; NCPC annulment grounds are exclusive and exhaustive Articles cited: Article 819 NCPC', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-2001-163', '[CASE LAW] Lebanese Court of Cassation - Decision 163/2001 (2001)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-1999-ARBCL', 'The Beirut Court of Appeal held that Lebanese courts retain jurisdiction to rule on the validity of arbitration agreements in international arbitration proceedings, alongside the arbitral tribunal''s competence-competence jurisdiction. Courts may review whether an international arbitration agreement is manifestly null and void before referring parties to arbitration under Article 764 NCPC. Legal principles established: Lebanese courts may review validity of arbitration agreements in international proceedings; Parallel jurisdiction of court and tribunal on arbitration agreement validity; Manifest nullity standard governs court review Articles cited: Article 764 NCPC', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-1999-ARBCL', '[CASE LAW] Court of Appeal of Beirut - Decision (unspecified) (1999-02-02)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-2001-142', 'The Lebanese Court of Cassation held that jurisdictional objections to an arbitral tribunal''s competence are waived if not raised at the appropriate time during the proceedings. A party who participates in arbitral proceedings without objecting to the tribunal''s jurisdiction in a timely manner cannot later challenge jurisdiction at the annulment stage. This doctrine promotes efficiency and good faith participation in arbitral proceedings. Legal principles established: Jurisdictional objections must be raised promptly or they are waived; Participation in arbitration without jurisdictional challenge waives later challenges; Good faith and estoppel principles apply to arbitral jurisdiction', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-2001-142', '[CASE LAW] Lebanese Court of Cassation - Decision 142/2001 (2001)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-2001-141', 'The Lebanese Court of Cassation ruled that an arbitral award cannot be annulled on the ground that evidence was misinterpreted or that the principle of equality was violated, unless the violation amounts to a breach of due process. Mere substantive disagreement with the arbitrator''s evidentiary findings or the outcome of the equality assessment is insufficient for annulment. Procedural due process must be specifically violated. Legal principles established: Evidence misinterpretation alone insufficient for annulment; Equality violation insufficient unless it rises to due process breach; Substantive review of evidentiary findings prohibited in annulment proceedings', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-2001-141', '[CASE LAW] Lebanese Court of Cassation - Decision 141/2001 (2001)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2010-1', 'The Beirut Court of Appeal held that immunity from execution does not extend to commercial activities of state-related or state-owned entities operating under private law. Even where there is some governmental interference or control, if the entity''s activities are commercial in nature, the entity cannot invoke state immunity to resist enforcement of judgments or arbitral awards. This decision is important for enforcement against foreign state-owned enterprises. Legal principles established: Commercial activities of state entities not shielded by sovereign immunity from execution; State interference does not transform commercial operations into immune public activities; Immunity from execution limited to genuinely governmental/public activities Articles cited: Article 860 LCCP', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2010-1', '[CASE LAW] Beirut Court of Appeal - Decision no. 41/2018 (2010-01-21)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CASS-COMM-2013-EXEC', 'The President of the Beirut Executive Bureau ruled that an international organization acting as a private party in a private law commercial transaction (not in the exercise of a public service function) cannot claim immunity from execution under Article 860(2) NCPC. The distinction between private commercial activities and public/institutional functions is key to determining whether execution immunity applies to international organizations. Legal principles established: International organizations lose execution immunity when acting as private commercial parties; Distinction between public/institutional and private/commercial activities governs immunity; Article 860(2) NCPC immunity limited to genuine public service activities Articles cited: Article 860(2) NCPC', 'en', 'Case Law Collection - Commercial, Article LB-CASS-COMM-2013-EXEC', '[CASE LAW] President of the Beirut Executive Bureau - Decision dated 18 July 2013 (2013-07-18)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-CFI-BEI-2010-12', 'The Beirut Court of First Instance ruled that the specific rules governing the validity and formalities of domestic arbitration agreements under the NCPC do not apply to international arbitration. International arbitration agreements are governed by the more flexible standards applicable to international commercial relations, not the stricter domestic requirements. Legal principles established: Domestic arbitration validity requirements do not apply to international arbitration; International arbitration agreements governed by international commercial standards; More flexible rules applicable to international agreements Articles cited: Articles 763, 812 NCPC', 'en', 'Case Law Collection - Commercial, Article LB-CFI-BEI-2010-12', '[CASE LAW] Court of First Instance of Beirut - Decision 12/42 (2010-04-28)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-BEIT-2000-UFFE', 'The Beirut Court of Appeal (10th Chamber) held that when a contract is transferred (assigned or subrogated) to a third party, the arbitration agreement contained in that contract may bind the transferee. The transfer of the main contract carries with it the arbitration clause as an ancillary element of the contractual relationship, subject to applicable transfer principles. Legal principles established: Transfer of contract may carry along the arbitration agreement to the transferee; Arbitration clause as ancillary element transfers with main contract; Third party accepting transferred contract accepts dispute resolution mechanism', 'en', 'Case Law Collection - Commercial, Article LB-COA-BEIT-2000-UFFE', '[CASE LAW] Beirut Court of Appeal, 10th Chamber - Société UFFE v. Compagnie de développement des bâtiments (2000-12-28)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', 'LB-COA-COMM-2004-763', 'The Third Chamber of the Beirut Court of Appeal confirmed that a third party who accepts a transferred contract is bound by the arbitration agreement in that contract. This complements the Société UFFE decision and forms part of the consistent line of jurisprudence on the extension of arbitration agreements to third parties through contract transfer mechanisms. Legal principles established: Contract transfer carries arbitration agreement to third-party transferee; Third party bound by arbitration agreement upon accepting transferred contract', 'en', 'Case Law Collection - Commercial, Article LB-COA-COMM-2004-763', '[CASE LAW] Beirut Court of Appeal, 3rd Chamber - Decision No. 763 (2004-04-02)', 'commercial'),
  ('LB-CASELAW-COMMERCIAL', NULL, 'Collection of 57 judicial decisions and court rulings in Commercial law from Lebanese courts including the Court of Cassation, Courts of Appeal, Constitutional Council, Council of State, and specialized tribunals. These decisions establish important legal precedents in Lebanese jurisprudence.', 'en', 'Case Law Collection - Commercial — Historical Context', 'Historical context and overview', 'commercial');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-CASELAW-LABOR', 'LB-CASS-COMM-2012-79', 'The Lebanese Court of Cassation ruled that individual labor disputes and social security matters fall under the exclusive jurisdiction of the Lebanese Labour Arbitration Boards and constitute a matter of public policy. Any pre-dispute arbitration clause in individual employment contracts is therefore null and void. The Court clarified that this exclusivity does not extend to collective labor agreements. Legal principles established: Labor Arbitration Boards have exclusive public-policy jurisdiction over individual labor disputes; Arbitration clauses in individual labor contracts are void; Exclusivity does not apply to collective labor agreements Articles cited: Article 79 Lebanese Code of Labour', 'en', 'Case Law Collection - Labor, Article LB-CASS-COMM-2012-79', '[CASE LAW] Lebanese Court of Cassation - Decision 79/2012 (2012-04-26)', 'labor'),
  ('LB-CASELAW-LABOR', NULL, 'Collection of 1 judicial decisions and court rulings in Labor law from Lebanese courts including the Court of Cassation, Courts of Appeal, Constitutional Council, Council of State, and specialized tribunals. These decisions establish important legal precedents in Lebanese jurisprudence.', 'en', 'Case Law Collection - Labor — Historical Context', 'Historical context and overview', 'labor'),
  ('LB-CASELAW-CIVIL', 'LB-CASS-CIV-2009-MH', 'The Lebanese Court of Cassation considered whether companies can recover moral harm damages in a contractual context. The case arose from a construction supply contract where defective cement caused the claimant company to face difficulties with third parties. The Court upheld the Court of Appeal''s award of moral damages to the claimant company, ruling that compensation for moral harm is available in the contractual context (not only in tort) and that a legal person (company) can suffer and recover moral harm. Quantification of moral harm is within the lower court''s sole discretion. The Court of Appeal had awarded USD 22,000. Legal principles established: Moral harm compensation is available in contractual context, not only in tort; A company (legal person) may suffer and recover moral harm; Quantification of moral harm is within lower court''s sole discretion; No legal basis to prevent moral damages from being awarded to companies Articles cited: Article 263 Code of Obligations and Contracts (COC), Article 134 COC', 'en', 'Case Law Collection - Civil, Article LB-CASS-CIV-2009-MH', '[CASE LAW] Lebanese Court of Cassation - Decision of 11 June 2009 (exact number unspecified) (2009-06-11)', 'civil'),
  ('LB-CASELAW-CIVIL', 'LB-COA-EXPR-2023-BBA', 'The Beirut Court of Appeals dismissed petitions by 13 lawyers challenging the Beirut Bar Association''s (BBA) March 2023 amendments to the code of ethics, which required lawyers to obtain prior permission from the BBA President before engaging in public or media appearances and banned criticism of BBA leadership. The petitioners argued the BBA lacked authority to restrict freedom of expression (reserved for the legislature), that the amendments violated the UN Basic Principles on the Role of Lawyers, and breached proportionality. The Court''s dismissal was widely criticized by human rights organizations as a setback for freedom of expression. Legal principles established: Court upheld BBA authority to impose prior permission requirements on lawyers'' public speech; Professional regulatory bodies may impose media restrictions on members; Decision criticized as failing to apply proportionality and necessity tests Articles cited: Lebanese Bar Association Code of Ethics (2023 amendments), Lebanese Constitution Article 13', 'en', 'Case Law Collection - Civil, Article LB-COA-EXPR-2023-BBA', '[CASE LAW] Beirut Court of Appeals - Decision dismissing petitions (exact number unspecified) (2023-05-01)', 'civil'),
  ('LB-CASELAW-CIVIL', NULL, 'Collection of 2 judicial decisions and court rulings in Civil law from Lebanese courts including the Court of Cassation, Courts of Appeal, Constitutional Council, Council of State, and specialized tribunals. These decisions establish important legal precedents in Lebanese jurisprudence.', 'en', 'Case Law Collection - Civil — Historical Context', 'Historical context and overview', 'civil'),
  ('LB-CASELAW-CRIMINAL', 'LB-STL-2020-AYYASH', 'The Special Tribunal for Lebanon Trial Chamber issued its long-awaited judgment in the assassination of former Lebanese Prime Minister Rafiq Hariri and 21 others on 14 February 2005. The Trial Chamber, comprising Judge David Re (Presiding), Judge Janet Nosworthy, and Lebanese Judge Micheline Braidy, found Salim Jamil Ayyash guilty beyond reasonable doubt on all five counts: conspiracy to commit a terrorist act, committing a terrorist act by explosive device, and three counts of intentional homicide/attempted homicide. Ayyash was convicted in absentia, primarily on circumstantial evidence from mobile phone records linking him to surveillance and coordination. The three co-accused (Hassan Habib Merhi, Hussein Hassan Oneissi, and Assad Hassan Sabra) were acquitted. On 11 December 2020, the sentencing chamber imposed five concurrent life sentences on Ayyash. Legal principles established: Conspiracy to commit terrorist act proven through mobile phone circumstantial evidence; In absentia trials permissible when accused has absconded (Article 22 STL Statute); Lebanese criminal law applied with international law interpretive assistance; No direct evidence required for conviction if circumstantial evidence is compelling Articles cited: Articles 314, 315, 316 Lebanese Criminal Code (terrorism), Article 22 STL Statute (in absentia trials), Article 3 STL Statute (modes of liability)', 'en', 'Case Law Collection - Criminal, Article LB-STL-2020-AYYASH', '[CASE LAW] Special Tribunal for Lebanon, Trial Chamber - STL-11-01/T/TC (2020-08-18)', 'criminal'),
  ('LB-CASELAW-CRIMINAL', 'LB-STL-2011-APPEALS', 'In a landmark pre-trial decision, the STL Appeals Chamber (presided by Judge Antonio Cassese) issued groundbreaking rulings on the definition of terrorism under customary international law and modes of criminal participation. The Chamber held that terrorism requires: (i) commission of a criminal act or threat thereof; (ii) intent to spread fear or coerce an authority; and (iii) a transnational element. The ruling established that attacks using ordinary firearms can constitute terrorism if they meet these criteria, contrary to prior Lebanese case law. The Chamber adopted Joint Criminal Enterprise I and II as modes of liability for terrorism but rejected JCE III (recklessness) and ICC ''perpetration by means'' as incompatible with terrorism''s specific intent requirement, preferring aiding and abetting instead. Legal principles established: Customary international law definition of terrorism: criminal act + intent to spread fear or coerce + transnational element; Ordinary firearms attacks can constitute terrorism if elements met; JCE I and II applicable to terrorism; JCE III incompatible with specific intent requirement; States have duty under customary law to prosecute terrorism; Lebanese terrorism law to be read in light of international treaty and customary law obligations Articles cited: Article 3 STL Statute (modes of liability), Lebanese Penal Code Articles 314-316 (terrorism), UN Security Council Resolution 1757 (2007)', 'en', 'Case Law Collection - Criminal, Article LB-STL-2011-APPEALS', '[CASE LAW] Special Tribunal for Lebanon, Appeals Chamber - STL-11-01/I/AC/R176bis (2011-02-16)', 'criminal'),
  ('LB-CASELAW-CRIMINAL', 'LB-STL-2012-ABSENTIA', 'The STL Trial Chamber authorized proceedings in absentia against all four accused (Salim Jamil Ayyash, Mustafa Amine Badreddine, Hussein Hassan Oneissi, and Assad Hassan Sabra) after finding that all reasonable steps had been taken to secure their appearance, that they had been informed of charges, and that they had absconded or could not be found. The decision established procedural standards for in absentia trials at the STL. Legal principles established: In absentia trial permissible when reasonable steps taken to secure appearance; Accused must be informed of charges before trial in absentia proceeds; Absconding satisfies conditions for Rule 106(A)(iii) proceedings Articles cited: Article 22 STL Statute, Rule 106 STL Rules of Procedure and Evidence', 'en', 'Case Law Collection - Criminal, Article LB-STL-2012-ABSENTIA', '[CASE LAW] Special Tribunal for Lebanon, Trial Chamber - STL-11-01/I/TC (2012-02-01)', 'criminal'),
  ('LB-CASELAW-CRIMINAL', 'LB-PUBCRT-2019-NIDAA', 'The Beirut Publications Court of Appeal, composed of President Judge Hiba Abdallah and Consultants Judges Nadia Jadayel and Manal Fares, revoked proceedings against Nidaa Al Watan Newspaper arising from a 12 September 2019 headline ''New Ambassadors in Baabda...Welcome to the Republic of Khamenei,'' which criticized Hezbollah''s influence over the Lebanese presidency. The Prosecutor charged the newspaper with libel, slander, and degrading the dignity of the Lebanese President under Legislative Decree 104/1977. The Court found no defamation, ruling the article constituted permissible political criticism. It prioritized press freedom and public interest over presidential privilege, citing Lebanon''s Constitution, the Universal Declaration of Human Rights, and European Court of Human Rights jurisprudence. The ruling significantly expanded the scope of permissible press criticism of public officials in Lebanon. Legal principles established: Political criticism of public officials, including the President, is permissible even if severe; Defamation requires factual insults; opinion-based criticism on public matters is not libel; Press freedom is fundamental to democracy and protected by Lebanese Constitution; Presidential privilege does not immunize against job-related public interest criticism; Public interest overrides individual reputation in political debate context Articles cited: Legislative Decree No. 104/1977 Articles 23, 26, Lebanese Penal Code Articles 210, 387, Lebanese Constitution Preamble (B), Article 13, UDHR Article 19, ECHR Article 10', 'en', 'Case Law Collection - Criminal, Article LB-PUBCRT-2019-NIDAA', '[CASE LAW] Publications Court of Appeal, Beirut - Case before Publications Court of Appeal (number unspecified) (2019-11-21)', 'criminal'),
  ('LB-CASELAW-CRIMINAL', 'LB-MILIT-2024-SAUD', 'The Lebanese Military Court sentenced five State Security officers to time already served after reducing the charges against them from felony (under the 2017 Anti-Torture Law) to misdemeanor. The officers had been indicted on 29 November 2022 for the torture that led to the death in custody of Syrian refugee Bashar Abd Saud on 5 November 2024. The court dropped Anti-Torture Law charges and substituted them with Article 166 of the Code of Military Justice (violating regulations/orders). Amnesty International condemned the decision as a ''missed opportunity'' that perpetuated impunity for torture-related deaths in custody. Legal principles established: Court downgraded torture charges to violation of military regulations; Anti-torture law charges dropped in favor of lesser military code charges; Time-served sentence for alleged torture leading to death in custody Articles cited: Anti-Torture Law No. 65/2017, Article 166 Code of Military Justice', 'en', 'Case Law Collection - Criminal, Article LB-MILIT-2024-SAUD', '[CASE LAW] Lebanese Military Court - Military court case (number unspecified) (2024-11-01)', 'criminal'),
  ('LB-CASELAW-CRIMINAL', NULL, 'Collection of 5 judicial decisions and court rulings in Criminal law from Lebanese courts including the Court of Cassation, Courts of Appeal, Constitutional Council, Council of State, and specialized tribunals. These decisions establish important legal precedents in Lebanese jurisprudence.', 'en', 'Case Law Collection - Criminal — Historical Context', 'Historical context and overview', 'criminal'),
  ('LB-CASELAW-CONSTITUTIONAL', 'LB-CONST-2018-2', 'The Lebanese Constitutional Council issued Decision No. 2/2018 annulling seven controversial articles of the 2018 Budget Law No. 79 of 18 April 2018. The decision addressed constitutional provisions concerning taxation, public spending, and legislative procedure, finding that certain budget provisions exceeded the legislature''s constitutional authority or violated constitutional principles of equality and legality. Legal principles established: Constitutional limits on legislative budget authority; Equality principle in taxation; Legislature must respect constitutional constraints in annual budget laws Articles cited: Lebanese Constitution (unspecified articles), Budget Law No. 79 of 2018', 'en', 'Case Law Collection - Constitutional, Article LB-CONST-2018-2', '[CASE LAW] Lebanese Constitutional Council - Decision No. 2/2018 (2018-05-14)', 'constitutional'),
  ('LB-CASELAW-CONSTITUTIONAL', 'LB-CONST-2026-JUD', 'The Lebanese Constitutional Council unanimously annulled Law No. 36, which introduced the new Judicial Organization Code, on the ground that the legislature failed to consult the Higher Judicial Council before voting on the law. This consultation is mandatory under Article 20 of the Lebanese Constitution, which guarantees judicial independence, though the Higher Judicial Council''s opinion is advisory rather than binding. The Constitutional Council consolidated appeals from independent MPs and Free Patriotic Movement lawmakers. The law had been passed as part of IMF reform requirements and had been returned by President Joseph Aoun for a second reading before being readopted in December 2025. Legal principles established: Mandatory consultation with Higher Judicial Council before legislation affecting judiciary; Failure to consult Higher Judicial Council renders law unconstitutional; Judicial independence principle (Article 20 Constitution) limits legislative power; Consultation requirement is mandatory even though Higher Judicial Council''s opinion is advisory Articles cited: Article 20 Lebanese Constitution', 'en', 'Case Law Collection - Constitutional, Article LB-CONST-2026-JUD', '[CASE LAW] Lebanese Constitutional Council - Decision annulling Law No. 36 (2026-02-25)', 'constitutional'),
  ('LB-CASELAW-CONSTITUTIONAL', 'LB-CONST-2025-16', 'The Lebanese Constitutional Council partially annulled Law No. 23/2025 on banking reform and restructuring following an appeal by ten MPs. The Council upheld core provisions but annulled: (1) Article 16 penultimate paragraph allowing the Higher Banking Authority to treat creditors of the same rank unequally without their consent, which violated Article 7 (equality before the law); (2) Article 29 paragraph 2 requiring automatic administrative transfer of pending court cases to a special court, which constituted interference in judicial authority; (3) a phrase in Article 31 limiting the scope of appeals to financial compensation only; and (4) the date in Article 1 setting the ''new deposits'' cutoff as October 30, 2019, which was inconsistent with October 17, 2019 used elsewhere in the law. The Council confirmed October 17, 2019 as the consistent benchmark date. Legal principles established: Equality before the law (Article 7 Constitution) prohibits unequal treatment of creditors of same rank; Automatic transfer of pending cases to new court constitutes impermissible interference in judicial authority; Legislative consistency required - contradictory dates in same law are unconstitutional; Bank restructuring law and Financial Gap Law are complementary and interdependent Articles cited: Article 7 Lebanese Constitution (equality), Law No. 23/2025 Articles 1, 16, 29, 31, 37, Law No. 110 of 1991', 'en', 'Case Law Collection - Constitutional, Article LB-CONST-2025-16', '[CASE LAW] Lebanese Constitutional Council - Decision No. 16/2025 (2025-10-03)', 'constitutional'),
  ('LB-CASELAW-CONSTITUTIONAL', 'LB-CONST-2025-328', 'The Lebanese Constitutional Council annulled Article 1(2) of Law No. 328 which had suspended judicial deadlines before Lebanese courts for the period from 31 March 2022 to 30 June 2024. The Council found the provision unconstitutional for violating parties'' rights to access justice and the principle of legal certainty in procedural law. Legal principles established: Right to access justice cannot be indefinitely suspended by legislation; Suspension of judicial deadlines for extended periods is unconstitutional; Procedural legal certainty is constitutionally guaranteed Articles cited: Law No. 328/2024 Article 1(2)', 'en', 'Case Law Collection - Constitutional, Article LB-CONST-2025-328', '[CASE LAW] Lebanese Constitutional Council - Decision annulling Article 1(2) of Law No. 328/2024 (2025-01-16)', 'constitutional'),
  ('LB-CASELAW-CONSTITUTIONAL', NULL, 'Collection of 4 judicial decisions and court rulings in Constitutional law from Lebanese courts including the Court of Cassation, Courts of Appeal, Constitutional Council, Council of State, and specialized tribunals. These decisions establish important legal precedents in Lebanese jurisprudence.', 'en', 'Case Law Collection - Constitutional — Historical Context', 'Historical context and overview', 'constitutional'),
  ('LB-CASELAW-ADMINISTRATIVE', 'LB-COUNCIL-STATE-2020-473', 'The Lebanese Council of State issued a landmark decision ruling that securitization activities and transactions are not liable to Value Added Tax (VAT) in Lebanon. The decision addressed the tax treatment of securitization mechanisms, clarifying that such financial transactions fall outside the scope of VAT legislation, providing important guidance for financial institutions and securitization vehicles operating in Lebanon. Legal principles established: Securitization activities are not subject to VAT; Tax liability requires clear statutory basis; Financial engineering transactions treated differently from ordinary commercial transactions for VAT purposes Articles cited: Lebanese VAT Law (Law No. 379 of 2001)', 'en', 'Case Law Collection - Administrative, Article LB-COUNCIL-STATE-2020-473', '[CASE LAW] Lebanese Council of State (Shura Council) - Decision No. 473/2019-2020 (2020-06-16)', 'administrative'),
  ('LB-CASELAW-ADMINISTRATIVE', 'LB-COUNCIL-STATE-2017-494', 'The Lebanese Council of State ruled that any claim challenging its own decisions on the exchange of tax information between countries is inadmissible. This decision effectively forecloses judicial challenges to the administrative process by which Lebanon exchanges tax information with foreign authorities pursuant to international agreements, protecting the automatic exchange mechanism. Legal principles established: Administrative decisions on international tax information exchange are not challengeable before Council of State; Claims against such decisions are inadmissible; International tax cooperation decisions have administrative finality Articles cited: Lebanese Tax Information Exchange Agreements', 'en', 'Case Law Collection - Administrative, Article LB-COUNCIL-STATE-2017-494', '[CASE LAW] Lebanese Council of State (Shura Council) - Decision No. 494/2017-2018 (2017-03-01)', 'administrative'),
  ('LB-CASELAW-ADMINISTRATIVE', 'LB-COUNCIL-STATE-2017-233', 'The Lebanese Council of State issued a precedent-setting decision on the exchange of tax information between Lebanon and France under the bilateral tax information exchange framework. The decision addressed the legal mechanisms, scope, and limits of administrative cooperation between Lebanese and French tax authorities, establishing important jurisprudence for cross-border tax transparency obligations. Legal principles established: Bilateral tax information exchange agreements create enforceable administrative obligations; Scope and limits of tax information exchange defined by treaty terms; Administrative cooperation in tax matters governed by public international law Articles cited: Lebanon-France Tax Information Exchange Agreement, Lebanese Tax Procedure Code', 'en', 'Case Law Collection - Administrative, Article LB-COUNCIL-STATE-2017-233', '[CASE LAW] Lebanese Council of State (Shura Council) - Decision No. 233/2017-2018 (2017-12-11)', 'administrative'),
  ('LB-CASELAW-ADMINISTRATIVE', 'LB-COUNCIL-STATE-2024-ITANI', 'In a landmark administrative ruling, the Lebanese State Shura Council (Lebanon''s highest administrative court) found that the Lebanese State failed in its obligations under the 2017 Anti-Torture Law to prohibit, prevent, and adequately investigate torture allegations made by actor Ziad Itani. Itani had been arrested on fabricated spying charges in November 2017, subjected to torture and solitary confinement, denied access to a lawyer, and acquitted by military court in March 2018. The Council found the State failed to protect the presumption of innocence, failed to prosecute torturers (who were instead promoted), and failed to conduct required investigations. It ordered the State to pay Itani 480 million Lebanese Liras (approximately USD 5,360) in reparations. This was the first judicial application of Lebanon''s 2017 anti-torture law by the administrative judiciary. Legal principles established: State has affirmative duty to prohibit, prevent, and investigate torture; Failure to prosecute perpetrators of torture constitutes state liability; Presumption of innocence must be protected by authorities, not undermined by press disclosures; Anti-torture law creates enforceable administrative duties on the State; State accountability for systemic torture impunity Articles cited: Anti-Torture Law No. 65/2017 (Lebanon, October 2017), Lebanese Constitution', 'en', 'Case Law Collection - Administrative, Article LB-COUNCIL-STATE-2024-ITANI', '[CASE LAW] Lebanese Council of State (State Shura Council) - Decision of 5 December 2024 (made public 10 March 2025) (2024-12-05)', 'administrative'),
  ('LB-CASELAW-ADMINISTRATIVE', 'LB-COUNCIL-STATE-2025-CIRC151-165', 'The Lebanese State filed motions before the State Shura Council (through Judge Helena Iskandar, Head of the Litigation Department at the Ministry of Justice) supporting petitions to annul Banque du Liban Circulars No. 151 and No. 165. The State''s position aligned with the petitioners'' arguments that both circulars violated Lebanon''s Code of Money and Credit. The conclusion was that the Council should annul both circulars and related actions to protect depositors'' funds and safeguard legal order. Circular 165 (issued 19 April 2023 by Governor Riad Salameh) regulated electronic cash settlement operations and distinguished ''fresh'' funds from pre-crisis deposits. Legal principles established: BDL circulars must comply with the Code of Money and Credit; Administrative circulars that violate statutory law are subject to annulment; State may intervene to support annulment of its own administrative bodies'' decisions Articles cited: Code of Money and Credit (Lebanon), BDL Circular No. 151, BDL Circular No. 165', 'en', 'Case Law Collection - Administrative, Article LB-COUNCIL-STATE-2025-CIRC151-165', '[CASE LAW] Lebanese Council of State (State Shura Council) - Petitions against Circulars 151 and 165 (pending/decided) (2025)', 'administrative'),
  ('LB-CASELAW-ADMINISTRATIVE', NULL, 'Collection of 5 judicial decisions and court rulings in Administrative law from Lebanese courts including the Court of Cassation, Courts of Appeal, Constitutional Council, Council of State, and specialized tribunals. These decisions establish important legal precedents in Lebanese jurisprudence.', 'en', 'Case Law Collection - Administrative — Historical Context', 'Historical context and overview', 'administrative'),
  ('LB-CASELAW-BANKING', 'LB-CFI-BANK-2024-BANKRUPT', 'The Beirut Court of First Instance dismissed a bankruptcy petition filed by a depositor against a Lebanese bank for failure to pay deposits. The Court ruled that standard bank insolvency provisions do not apply when the bank''s cessation of payment results from a systemic ''comprehensive crisis'' rather than an individual bank failure. Since the Banque du Liban (BDL) had failed to pay its obligations to commercial banks (despite the State''s responsibility under Article 113 of the Monetary and Credit Law), the Court found that ''what applies to one bank applies to all banks.'' The decision was criticized by The Legal Agenda for shielding banks from accountability and ignoring individual bank responsibility for investing deposits imprudently. Legal principles established: Standard bankruptcy provisions inapplicable during systemic banking crisis; Collective/regulatory crisis distinguishes from individual insolvency scenario; BDL failure to repay creates force majeure-type defense for commercial banks; State responsible under Article 113 Monetary and Credit Law for BDL losses Articles cited: Article 113 Monetary and Credit Law, Lebanese Commercial Code (bankruptcy provisions)', 'en', 'Case Law Collection - Banking, Article LB-CFI-BANK-2024-BANKRUPT', '[CASE LAW] Beirut Court of First Instance (Insolvency/Bankruptcy Chamber) - Insolvency case (number unspecified) (2024-01-08)', 'banking'),
  ('LB-CASELAW-BANKING', 'LB-UMJ-BANK-BYBLOS', 'The Beirut Urgent Matters Judge issued the most notable early ruling in Lebanon''s banking crisis, ordering Byblos Bank SAL to transfer USD 1,138,085 to the plaintiff depositor''s account at HSBC Bank in Dubai, subject to a coercive fine of 10 million Lebanese Pounds per day of delay. Byblos Bank had refused, citing BDL Circular of 4/12/2019 and the Association of Banks'' circular imposing de facto capital controls. This decision was significant as one of the first pro-depositor rulings against Lebanese banks, though higher courts later adopted more restrictive approaches. Legal principles established: Bank''s contractual obligation to execute international transfers is enforceable by specific performance; BDL circulars imposing capital controls do not eliminate contractual obligation to depositors; Coercive fines (astreinte) available to enforce banking transfer obligations Articles cited: Lebanese Code of Civil Procedure (urgent matters jurisdiction), Monetary and Credit Law', 'en', 'Case Law Collection - Banking, Article LB-UMJ-BANK-BYBLOS', '[CASE LAW] Urgent Matters Judge (Judge des Référés), Beirut - Decision (exact number unspecified) (2020)', 'banking'),
  ('LB-CASELAW-BANKING', 'LB-CASS-BANK-RECENT', 'The Lebanese Court of Cassation issued a series of rulings reversing the earlier pro-depositor trend in summary proceedings (référés). While lower judges had ordered banks to transfer funds overseas at depositors'' requests, the Court of Cassation adopted a more restrictive stance, limiting the scope of relief available to depositors in urgent/summary proceedings. This shift forced depositors to seek alternative remedies including ex parte provisional seizures or merits-based actions. Legal principles established: Summary proceedings have limited scope for ordering international fund transfers; Depositors must pursue merits actions rather than urgent proceedings for banking transfers; Court of Cassation set limits on lower courts'' expansive pro-depositor interpretations Articles cited: Lebanese Code of Civil Procedure (summary proceedings provisions)', 'en', 'Case Law Collection - Banking, Article LB-CASS-BANK-RECENT', '[CASE LAW] Lebanese Court of Cassation - Recent decisions (specific numbers unspecified) (2023)', 'banking'),
  ('LB-CASELAW-BANKING', NULL, 'Collection of 3 judicial decisions and court rulings in Banking law from Lebanese courts including the Court of Cassation, Courts of Appeal, Constitutional Council, Council of State, and specialized tribunals. These decisions establish important legal precedents in Lebanese jurisprudence.', 'en', 'Case Law Collection - Banking — Historical Context', 'Historical context and overview', 'banking'),
  ('LB-CASELAW-FAMILY', 'LB-CIVCO-FAM-2025-ZOOM', 'In a groundbreaking ruling, the Beirut Civil Court recognized the validity of a civil marriage conducted remotely via Zoom between two Lebanese citizens, officiated by a civil registrar in the State of Utah, USA. This is the first Lebanese court decision to validate a civil marriage contracted without religious oversight, conducted remotely, and outside Lebanese territory. The Court applied U.S. law and private international law principles, including freedom of conscience and the right to marry. The ruling may open space for civil marriage in Lebanon and is relevant to ongoing parliamentary debates about a unified personal status code. Legal principles established: Civil marriage conducted remotely by foreign civil registrar may be recognized in Lebanon; Private international law principles allow recognition of foreign civil marriages; Freedom of conscience and right to marry support recognition of civil unions; Lebanese courts may apply foreign law to validate marriages outside religious framework Articles cited: U.S. Utah State Marriage Law, Lebanese Private International Law principles, Lebanese Constitution Article 9 (freedom of religion/conscience)', 'en', 'Case Law Collection - Family, Article LB-CIVCO-FAM-2025-ZOOM', '[CASE LAW] Beirut Civil Court - Decision of 22 May 2025 (number unspecified) (2025-05-22)', 'family'),
  ('LB-CASELAW-FAMILY', 'LB-CASS-FAM-2009-CUSTODY', 'The Lebanese Court of Cassation interpreted the 2002 Law on Child Protection to grant civil courts jurisdiction not only over procedural matters in child custody disputes, but also over substantive issues where religious court judgments conflict with child welfare and public order principles. The Court ruled that civil courts may refuse to give civil recognition and force of law to any religious personal status judgment that contravenes the basic component of public order: child welfare and protection. This was the first time the Court of Cassation granted civil courts substantive (not merely procedural) jurisdiction over personal status matters. Legal principles established: Civil courts may refuse recognition of religious court judgments violating child welfare; Child welfare is a component of public order overriding religious personal status law; 2002 Child Protection Law grants civil courts substantive as well as procedural jurisdiction Articles cited: Lebanese Law on Child Protection (2002)', 'en', 'Case Law Collection - Family, Article LB-CASS-FAM-2009-CUSTODY', '[CASE LAW] Lebanese Court of Cassation - Decision of 2009 (number unspecified) (2009)', 'family'),
  ('LB-CASELAW-FAMILY', NULL, 'Collection of 2 judicial decisions and court rulings in Family law from Lebanese courts including the Court of Cassation, Courts of Appeal, Constitutional Council, Council of State, and specialized tribunals. These decisions establish important legal precedents in Lebanese jurisprudence.', 'en', 'Case Law Collection - Family — Historical Context', 'Historical context and overview', 'family'),
  ('LB-CIV-001', '1', 'Every person is bound to repair the damage caused to another by his fault.', 'en', 'Code of Obligations and Contracts, Article 1', 'General principle of fault-based liability', 'Civil Law'),
  ('LB-CIV-001', '1', 'Toute personne est obligée de réparer le dommage qu''elle a causé à autrui par sa faute.', 'fr', 'Code of Obligations and Contracts, Article 1', 'General principle of fault-based liability', 'Civil Law'),
  ('LB-CIV-001', '122', 'A contract is the concordance of two or more wills to create, modify, or extinguish an obligation.', 'en', 'Code of Obligations and Contracts, Article 122', 'Definition of contract', 'Civil Law'),
  ('LB-CIV-001', '221-232', 'Provisions on consent: error, fraud, duress, and lesion as grounds for annulment of contracts.', 'en', 'Code of Obligations and Contracts, Article 221-232', 'Vices of consent', 'Civil Law'),
  ('LB-CIV-001', '249-260', 'Requirements for valid object and cause of obligations.', 'en', 'Code of Obligations and Contracts, Article 249-260', 'Object and cause of obligations', 'Civil Law'),
  ('LB-CIV-001', '313-317', 'Sale of immovable property and registration requirements.', 'en', 'Code of Obligations and Contracts, Article 313-317', 'Sale of real property', 'Civil Law'),
  ('LB-CIV-001', '596-640', 'Lease and rental agreements - rights and obligations of landlord and tenant.', 'en', 'Code of Obligations and Contracts, Article 596-640', 'Lease/Rent', 'Civil Law'),
  ('LB-CIV-001', '717-728', 'Agency (mandat/وكالة) provisions.', 'en', 'Code of Obligations and Contracts, Article 717-728', 'Agency', 'Civil Law'),
  ('LB-CIV-001', '880-897', 'Mortgage and hypothec provisions.', 'en', 'Code of Obligations and Contracts, Article 880-897', 'Mortgages', 'Civil Law'),
  ('LB-CIV-001', NULL, 'Lebanon''s primary civil law code, adopted during the French Mandate. Modeled on the French Civil Code (Code Napoleon of 1804) and the Ottoman Mecelle, but adapted for Lebanese specificities. Known as the ''COC'' among Lebanese law students. Covers general obligations, contracts, torts, property transactions, and specific nominate contracts. Notably excludes personal status matters (marriage, divorce, inheritance) which are governed by each religious community''s own laws. The COC remains the backbone of Lebanese private law and is the most frequently cited code in Lebanese civil courts.', 'en', 'Code of Obligations and Contracts — Historical Context', 'Historical context and overview', 'Civil Law'),
  ('LB-CIV-001', NULL, 'The COC has been amended numerous times since 1932. Key amendments relate to contract law, property transactions, insurance obligations, and consumer protection.', 'en', 'Code of Obligations and Contracts — Amendment: Various amendments (1932-2020)', 'Amendment', 'Civil Law'),
  ('LB-CIV-002', '1-7', 'General principles of civil litigation, right of access to courts, burden of proof.', 'en', 'Code of Civil Procedure, Article 1-7', 'General principles', 'Civil Law'),
  ('LB-CIV-002', '762-810', 'Arbitration provisions - domestic and international arbitration framework.', 'en', 'Code of Civil Procedure, Article 762-810', 'Arbitration', 'Civil Law'),
  ('LB-CIV-002', NULL, 'Replaced the earlier Code of Civil Procedure. Issued as a decree-law during the Civil War period when Parliament was not functioning regularly. Governs all civil and commercial litigation procedures including jurisdiction, service of process, evidence, judgment, appeals, and execution. The arbitration chapter has gained particular importance for Lebanon''s role as a regional commercial center.', 'en', 'Code of Civil Procedure — Historical Context', 'Historical context and overview', 'Civil Law'),
  ('LB-CIV-002', 'various', 'Significant amendments to arbitration and execution procedures.', 'en', 'Code of Civil Procedure — Amendment: Law No. 440/2002', 'Amendment', 'Civil Law'),
  ('LB-CIV-003', NULL, 'Established the modern Lebanese property registration system (Torrens system). Replaced Ottoman land law categories. Created the Land Registry system still in use today. Governs ownership, servitudes, usufruct, and real property rights.', 'en', 'Real Property Law — Historical Context', 'Historical context and overview', 'Civil Law'),
  ('LB-CIV-004', NULL, 'Lebanon''s rent laws have been among the most politically contentious areas of legislation. Exceptional rent laws freezing rents for pre-1992 tenancies were enacted during and after the Civil War, creating a dual market between ''old rent'' (heavily protected tenants) and ''new rent'' (market-rate). The 2017 law attempted to gradually liberalize old rents over a transitional period but faced legal challenges and implementation difficulties.', 'en', 'Rent/Tenancy Law (Exceptional Provisions) — Historical Context', 'Historical context and overview', 'Civil Law'),
  ('LB-CIV-004', NULL, 'Post-war rent law establishing rent control and tenant protections.', 'en', 'Rent/Tenancy Law (Exceptional Provisions) — Amendment: Law No. 160/1992 (New Rent Law)', 'Amendment', 'Civil Law'),
  ('LB-CIV-004', NULL, 'New comprehensive rent law replacing previous framework. Introduced gradual rent increases for pre-1992 tenancies over 9-12 year transitional period. Created Rent Committee and Fund for tenants. Partially suspended by Constitutional Council Decision No. 6/2014 and subsequently amended.', 'en', 'Rent/Tenancy Law (Exceptional Provisions) — Amendment: Law No. 2/2017 (New Rent Law)', 'Amendment', 'Civil Law'),
  ('LB-CIV-005', NULL, 'Governs the structure and function of the Lebanese judiciary. Establishes the hierarchy of ordinary courts: courts of first instance, courts of appeal, and the Court of Cassation. Also establishes the Supreme Judicial Council headed by the First President (Chief Justice) of the Court of Cassation. Defines jurisdiction of civil, criminal, and commercial chambers at each level.', 'en', 'Judicial Organization Law — Historical Context', 'Historical context and overview', 'Judicial Organization'),
  ('LB-COMM-001', 'Article 1', 'The present code contains the rules relating to all acts of trade', 'en', 'Lebanese Commercial Code, Article Article 1', 'Scope of Commercial Code', 'Commercial Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-COMM-001', 'Article 1', 'Le présent code contient les règles relatives à tous les actes de commerce', 'fr', 'Lebanese Commercial Code, Article Article 1', 'Scope of Commercial Code', 'Commercial Law'),
  ('LB-COMM-001', 'Article 1', 'يحتوي هذا القانون على القواعد المتعلقة بجميع الأعمال التجارية', 'ar', 'Lebanese Commercial Code, Article Article 1', 'Scope of Commercial Code', 'Commercial Law'),
  ('LB-COMM-001', 'Article 22', 'The trade register enables the public to collect complete information regarding all business houses', 'en', 'Lebanese Commercial Code, Article Article 22', 'Commercial Register Purpose', 'Commercial Law'),
  ('LB-COMM-001', 'Article 22', 'Le registre du commerce permet au public de recueillir des renseignements complets sur toutes les maisons de commerce', 'fr', 'Lebanese Commercial Code, Article Article 22', 'Commercial Register Purpose', 'Commercial Law'),
  ('LB-COMM-001', 'Article 22', 'السجل التجاري يمكن الجمهور من الحصول على معلومات كاملة حول جميع المنشآت التجارية العاملة في البلاد', 'ar', 'Lebanese Commercial Code, Article Article 22', 'Commercial Register Purpose', 'Commercial Law'),
  ('LB-COMM-001', 'Article 24', 'Every trader must require the Court Clerk to list him on the register within one month of opening his stock-in-trade', 'en', 'Lebanese Commercial Code, Article Article 24', 'Trader Registration Requirement', 'Commercial Law'),
  ('LB-COMM-001', 'Article 24', 'Tout commerçant doit faire inscrire au greffe dans le mois de l''ouverture de son fonds de commerce', 'fr', 'Lebanese Commercial Code, Article Article 24', 'Trader Registration Requirement', 'Commercial Law'),
  ('LB-COMM-001', 'Article 24', 'يجب على كل تاجر أن يطلب من كاتب المحكمة تسجيله في السجل خلال شهر من افتتاح محله التجاري', 'ar', 'Lebanese Commercial Code, Article Article 24', 'Trader Registration Requirement', 'Commercial Law'),
  ('LB-COMM-001', 'Article 44', 'Deeds of partnership of all commercial companies must, under penalty of nullity, be published', 'en', 'Lebanese Commercial Code, Article Article 44', 'Company Publication Requirement', 'Commercial Law'),
  ('LB-COMM-001', 'Article 44', 'Les actes de société de toutes les sociétés commerciales doivent, sous peine de nullité, être publiés', 'fr', 'Lebanese Commercial Code, Article Article 44', 'Company Publication Requirement', 'Commercial Law'),
  ('LB-COMM-001', 'Article 44', 'عقود الشراكة لجميع الشركات التجارية يجب أن تنشر تحت طائلة البطلان', 'ar', 'Lebanese Commercial Code, Article Article 44', 'Company Publication Requirement', 'Commercial Law'),
  ('LB-COMM-001', 'Article 409-446', 'Provisions on cheques', 'en', 'Lebanese Commercial Code, Article Article 409-446', 'Cheque Regulations', 'Commercial Law'),
  ('LB-COMM-001', 'Article 409-446', 'Dispositions sur le chèque', 'fr', 'Lebanese Commercial Code, Article Article 409-446', 'Cheque Regulations', 'Commercial Law'),
  ('LB-COMM-001', 'Article 409-446', 'أحكام الشيك', 'ar', 'Lebanese Commercial Code, Article Article 409-446', 'Cheque Regulations', 'Commercial Law'),
  ('LB-COMM-001', 'Articles 459-668', 'Provisions on bankruptcy and judicial settlement', 'en', 'Lebanese Commercial Code, Article Articles 459-668', 'Bankruptcy and Insolvency', 'Commercial Law'),
  ('LB-COMM-001', 'Articles 459-668', 'Dispositions sur la faillite et le règlement judiciaire', 'fr', 'Lebanese Commercial Code, Article Articles 459-668', 'Bankruptcy and Insolvency', 'Commercial Law'),
  ('LB-COMM-001', 'Articles 459-668', 'أحكام الإفلاس والتسوية', 'ar', 'Lebanese Commercial Code, Article Articles 459-668', 'Bankruptcy and Insolvency', 'Commercial Law'),
  ('LB-COMM-001', NULL, 'The Lebanese Commercial Code of 1942 was enacted during the French Mandate period, replacing Ottoman commercial laws. It was modeled after the French Commercial Code and established the foundation for modern commercial regulation in Lebanon. The Code covers trade acts, merchants, commercial companies, commercial papers (bills of exchange, cheques, promissory notes), and bankruptcy procedures.', 'en', 'Lebanese Commercial Code — Historical Context', 'Historical context and overview', 'Commercial Law'),
  ('LB-COMP-002', 'General Provisions', 'Types of commercial companies: partnership companies and capital companies', 'en', 'Legislative Decree 150/83 on Commercial Companies, Article General Provisions', 'Company Types Classification', 'Commercial Law'),
  ('LB-COMP-002', 'General Provisions', 'Types de sociétés commerciales: sociétés de personnes et sociétés de capitaux', 'fr', 'Legislative Decree 150/83 on Commercial Companies, Article General Provisions', 'Company Types Classification', 'Commercial Law'),
  ('LB-COMP-002', 'General Provisions', 'أنواع الشركات التجارية: الشركات الشخصية (تضامن، توصية بسيطة) والشركات الرأسمالية (مساهمة، توصية بالأسهم، ذات مسؤولية محدودة)', 'ar', 'Legislative Decree 150/83 on Commercial Companies, Article General Provisions', 'Company Types Classification', 'Commercial Law'),
  ('LB-COMP-002', 'SARL Provisions', 'Limited Liability Company: minimum capital of 5 million Lebanese Pounds', 'en', 'Legislative Decree 150/83 on Commercial Companies, Article SARL Provisions', 'LLC Capital Requirements', 'Commercial Law'),
  ('LB-COMP-002', 'SARL Provisions', 'Société à responsabilité limitée: capital minimum de 5 millions de livres libanaises', 'fr', 'Legislative Decree 150/83 on Commercial Companies, Article SARL Provisions', 'LLC Capital Requirements', 'Commercial Law'),
  ('LB-COMP-002', 'SARL Provisions', 'شركة ذات مسؤولية محدودة: لا يقل رأس المال عن 5 ملايين ليرة لبنانية', 'ar', 'Legislative Decree 150/83 on Commercial Companies, Article SARL Provisions', 'LLC Capital Requirements', 'Commercial Law'),
  ('LB-COMP-002', 'SA Provisions', 'Joint Stock Company: minimum capital of 30 million Lebanese Pounds', 'en', 'Legislative Decree 150/83 on Commercial Companies, Article SA Provisions', 'JSC Capital Requirements', 'Commercial Law'),
  ('LB-COMP-002', 'SA Provisions', 'Société anonyme: capital minimum de 30 millions de livres libanaises', 'fr', 'Legislative Decree 150/83 on Commercial Companies, Article SA Provisions', 'JSC Capital Requirements', 'Commercial Law'),
  ('LB-COMP-002', 'SA Provisions', 'الشركة المساهمة: لا يقل رأس المال عن 30 مليون ليرة لبنانية', 'ar', 'Legislative Decree 150/83 on Commercial Companies, Article SA Provisions', 'JSC Capital Requirements', 'Commercial Law'),
  ('LB-COMP-002', 'Foreign Companies', 'Any foreign commercial company operating a branch or agency in Lebanon must register in the commercial register', 'en', 'Legislative Decree 150/83 on Commercial Companies, Article Foreign Companies', 'Foreign Company Registration', 'Commercial Law'),
  ('LB-COMP-002', 'Foreign Companies', 'Toute société commerciale étrangère exploitant une succursale ou une agence au Liban est tenue de s''inscrire au registre du commerce', 'fr', 'Legislative Decree 150/83 on Commercial Companies, Article Foreign Companies', 'Foreign Company Registration', 'Commercial Law'),
  ('LB-COMP-002', 'Foreign Companies', 'أي شركة تجارية أجنبية تدير فرعاً أو وكالة في لبنان ملزمة بالتسجيل في السجل التجاري', 'ar', 'Legislative Decree 150/83 on Commercial Companies, Article Foreign Companies', 'Foreign Company Registration', 'Commercial Law'),
  ('LB-COMP-002', NULL, 'Legislative Decree 150/83 was enacted to modernize company law in Lebanon, providing a comprehensive framework for commercial companies including LLCs (SARL), Joint Stock Companies (SA), and other company forms. It replaced earlier company regulations and aligned Lebanese company law with international standards.', 'en', 'Legislative Decree 150/83 on Commercial Companies — Historical Context', 'Historical context and overview', 'Commercial Law'),
  ('LB-REG-004', 'Article 23', 'A register is kept in the district of each Court of primary jurisdiction by a Clerk, under the supervision of a president or specially designated judge', 'en', 'Commercial Register Provisions, Article Article 23', 'Register Maintenance', 'Commercial Law'),
  ('LB-REG-004', 'Article 23', 'Un registre est tenu dans le ressort de chaque tribunal de première instance par un greffier, sous la surveillance du président ou d''un juge spécialement désigné', 'fr', 'Commercial Register Provisions, Article Article 23', 'Register Maintenance', 'Commercial Law'),
  ('LB-REG-004', 'Article 23', 'يحفظ سجل في دائرة كل محكمة ابتدائية من قبل كاتب، تحت إشراف رئيس المحكمة أو قاضٍ مكلف', 'ar', 'Commercial Register Provisions, Article Article 23', 'Register Maintenance', 'Commercial Law'),
  ('LB-REG-004', 'Article 24', 'Every trader must register in the commercial register within one month of opening his establishment', 'en', 'Commercial Register Provisions, Article Article 24', 'Registration Obligation', 'Commercial Law'),
  ('LB-REG-004', 'Article 24', 'Tout commerçant doit s''inscrire au registre du commerce dans le mois de l''ouverture de son fonds', 'fr', 'Commercial Register Provisions, Article Article 24', 'Registration Obligation', 'Commercial Law'),
  ('LB-REG-004', 'Article 24', 'كل تاجر ملزم بالتسجيل في السجل التجاري خلال شهر من افتتاح محله', 'ar', 'Commercial Register Provisions, Article Article 24', 'Registration Obligation', 'Commercial Law'),
  ('LB-REG-004', 'Article 36', 'Every trader and company must state on their letters and invoices the place of registration and registration number', 'en', 'Commercial Register Provisions, Article Article 36', 'Registration Display Requirement', 'Commercial Law'),
  ('LB-REG-004', 'Article 36', 'Tout commerçant et société sont tenus de mentionner sur leurs lettres et factures le lieu de leur inscription et leur numéro d''inscription', 'fr', 'Commercial Register Provisions, Article Article 36', 'Registration Display Requirement', 'Commercial Law'),
  ('LB-REG-004', 'Article 36', 'كل تاجر وشركة ملزمون بذكر مكان تسجيلهم ورقم تسجيلهم على رسائلهم وفواتيرهم', 'ar', 'Commercial Register Provisions, Article Article 36', 'Registration Display Requirement', 'Commercial Law'),
  ('LB-REG-004', NULL, 'The Commercial Register provisions are contained within the Lebanese Commercial Code of 1942. The register serves as a public record of all commercial establishments operating in Lebanon, divided into a general register for traders and companies, and a special register for commercial establishments and contracts. Registration is maintained at each Court of First Instance.', 'en', 'Commercial Register Provisions — Historical Context', 'Historical context and overview', 'Commercial Law'),
  ('LB-BANKR-005', 'Articles 459-500', 'Bankruptcy provisions: declaration of bankruptcy, effects, judicial administration of the bankrupt', 'en', 'Bankruptcy and Judicial Settlement Provisions, Article Articles 459-500', 'Bankruptcy Procedures', 'Commercial Law'),
  ('LB-BANKR-005', 'Articles 459-500', 'Dispositions sur la faillite: déclaration de faillite, effets, administration judiciaire du failli', 'fr', 'Bankruptcy and Judicial Settlement Provisions, Article Articles 459-500', 'Bankruptcy Procedures', 'Commercial Law'),
  ('LB-BANKR-005', 'Articles 459-500', 'أحكام الإفلاس: إعلان الإفلاس، آثاره، الإدارة القضائية للمفلس', 'ar', 'Bankruptcy and Judicial Settlement Provisions, Article Articles 459-500', 'Bankruptcy Procedures', 'Commercial Law'),
  ('LB-BANKR-005', 'Articles 501-550', 'Judicial settlement provisions', 'en', 'Bankruptcy and Judicial Settlement Provisions, Article Articles 501-550', 'Judicial Settlement', 'Commercial Law'),
  ('LB-BANKR-005', 'Articles 501-550', 'Dispositions sur le règlement judiciaire', 'fr', 'Bankruptcy and Judicial Settlement Provisions, Article Articles 501-550', 'Judicial Settlement', 'Commercial Law'),
  ('LB-BANKR-005', 'Articles 501-550', 'أحكام التسوية القضائية', 'ar', 'Bankruptcy and Judicial Settlement Provisions, Article Articles 501-550', 'Judicial Settlement', 'Commercial Law'),
  ('LB-BANKR-005', 'Articles 551-600', 'Preventive settlement provisions', 'en', 'Bankruptcy and Judicial Settlement Provisions, Article Articles 551-600', 'Preventive Settlement', 'Commercial Law'),
  ('LB-BANKR-005', 'Articles 551-600', 'Dispositions sur le concordat préventif', 'fr', 'Bankruptcy and Judicial Settlement Provisions, Article Articles 551-600', 'Preventive Settlement', 'Commercial Law'),
  ('LB-BANKR-005', 'Articles 551-600', 'أحكام التسوية الوقائية', 'ar', 'Bankruptcy and Judicial Settlement Provisions, Article Articles 551-600', 'Preventive Settlement', 'Commercial Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-BANKR-005', 'Articles 601-668', 'Fraudulent bankruptcy and criminal liability provisions', 'en', 'Bankruptcy and Judicial Settlement Provisions, Article Articles 601-668', 'Fraudulent Bankruptcy', 'Commercial Law'),
  ('LB-BANKR-005', 'Articles 601-668', 'Dispositions sur la faillite frauduleuse et la responsabilité pénale', 'fr', 'Bankruptcy and Judicial Settlement Provisions, Article Articles 601-668', 'Fraudulent Bankruptcy', 'Commercial Law'),
  ('LB-BANKR-005', 'Articles 601-668', 'أحكام الإفلاس الاحتيالي والمسؤولية الجنائية', 'ar', 'Bankruptcy and Judicial Settlement Provisions, Article Articles 601-668', 'Fraudulent Bankruptcy', 'Commercial Law'),
  ('LB-BANKR-005', NULL, 'Lebanon does not have a standalone Bankruptcy Law. Bankruptcy and insolvency are governed by Book V of the Commercial Code (Articles 459-668) and the Penal Code. The law provides for both voluntary and judicial liquidation, as well as debt restructuring options for distressed businesses. Workers may resort to the Labor Court and the National Social Security Fund to recover pay and benefits from bankrupt firms. The law criminalizes fraudulent bankruptcy.', 'en', 'Bankruptcy and Judicial Settlement Provisions — Historical Context', 'Historical context and overview', 'Commercial Law'),
  ('LB-MAR-006', 'General Provisions', 'Ship registration at Beirut Ship Registry', 'en', 'Maritime Commerce Law, Article General Provisions', 'Ship Registration', 'Maritime Law'),
  ('LB-MAR-006', 'General Provisions', 'Enregistrement des navires au Registre des Navires de Beyrouth', 'fr', 'Maritime Commerce Law, Article General Provisions', 'Ship Registration', 'Maritime Law'),
  ('LB-MAR-006', 'General Provisions', 'تسجيل السفن في سجل بيروت للسفن', 'ar', 'Maritime Commerce Law, Article General Provisions', 'Ship Registration', 'Maritime Law'),
  ('LB-MAR-006', 'Transport Contracts', 'Maritime transport contracts and bills of lading', 'en', 'Maritime Commerce Law, Article Transport Contracts', 'Maritime Transport', 'Maritime Law'),
  ('LB-MAR-006', 'Transport Contracts', 'Contrats de transport maritime et connaissement', 'fr', 'Maritime Commerce Law, Article Transport Contracts', 'Maritime Transport', 'Maritime Law'),
  ('LB-MAR-006', 'Transport Contracts', 'عقود النقل البحري وبوليصة الشحن', 'ar', 'Maritime Commerce Law, Article Transport Contracts', 'Maritime Transport', 'Maritime Law'),
  ('LB-MAR-006', 'Crew Provisions', 'Crew contracts and working conditions', 'en', 'Maritime Commerce Law, Article Crew Provisions', 'Maritime Labor', 'Maritime Law'),
  ('LB-MAR-006', 'Crew Provisions', 'Contrats d''équipage et conditions de travail', 'fr', 'Maritime Commerce Law, Article Crew Provisions', 'Maritime Labor', 'Maritime Law'),
  ('LB-MAR-006', 'Crew Provisions', 'عقود طاقم السفن وشروط العمل', 'ar', 'Maritime Commerce Law, Article Crew Provisions', 'Maritime Labor', 'Maritime Law'),
  ('LB-MAR-006', 'Maritime Accidents', 'Maritime accidents, salvage and liability', 'en', 'Maritime Commerce Law, Article Maritime Accidents', 'Maritime Liability', 'Maritime Law'),
  ('LB-MAR-006', 'Maritime Accidents', 'Accidents maritimes, sauvetage et responsabilité', 'fr', 'Maritime Commerce Law, Article Maritime Accidents', 'Maritime Liability', 'Maritime Law'),
  ('LB-MAR-006', 'Maritime Accidents', 'الحوادث البحرية والإنقاذ والمسؤولية', 'ar', 'Maritime Commerce Law, Article Maritime Accidents', 'Maritime Liability', 'Maritime Law'),
  ('LB-MAR-006', NULL, 'Lebanese maritime law is primarily regulated by the 1947 Maritime Commerce Law (Code de Commerce Maritime) and the Lebanese Commercial Code. Inspired by French maritime law, it contains detailed provisions on ship registration, maritime transport contracts, crew employment, maritime accidents, marine insurance, and arbitration procedures. Lebanon follows international standards including MLC 2006, STCW, SOLAS, and MARPOL conventions.', 'en', 'Maritime Commerce Law — Historical Context', 'Historical context and overview', 'Maritime Law'),
  ('LB-AGENCY-007', 'Commercial Code Provisions', 'Commercial agent: may act on behalf of the principal in commercial transactions', 'en', 'Commercial Agency and Distribution Provisions, Article Commercial Code Provisions', 'Commercial Agency Definition', 'Commercial Law'),
  ('LB-AGENCY-007', 'Commercial Code Provisions', 'Agent commercial: peut agir au nom du principal dans les transactions commerciales', 'fr', 'Commercial Agency and Distribution Provisions, Article Commercial Code Provisions', 'Commercial Agency Definition', 'Commercial Law'),
  ('LB-AGENCY-007', 'Commercial Code Provisions', 'الوكالة التجارية: يمكن للوكيل التجاري أن يتصرف باسم الم principal في المعاملات التجارية', 'ar', 'Commercial Agency and Distribution Provisions, Article Commercial Code Provisions', 'Commercial Agency Definition', 'Commercial Law'),
  ('LB-AGENCY-007', 'Registration Requirement', 'Commercial agencies must be registered in the commercial register', 'en', 'Commercial Agency and Distribution Provisions, Article Registration Requirement', 'Agency Registration', 'Commercial Law'),
  ('LB-AGENCY-007', 'Registration Requirement', 'Les agences commerciales doivent être enregistrées au registre du commerce', 'fr', 'Commercial Agency and Distribution Provisions, Article Registration Requirement', 'Agency Registration', 'Commercial Law'),
  ('LB-AGENCY-007', 'Registration Requirement', 'يجب تسجيل الوكالات التجارية في السجل التجاري', 'ar', 'Commercial Agency and Distribution Provisions, Article Registration Requirement', 'Agency Registration', 'Commercial Law'),
  ('LB-AGENCY-007', 'Exclusive Agency', 'Exclusive agency: the exclusive agent has the right to represent the principal in a specific territory', 'en', 'Commercial Agency and Distribution Provisions, Article Exclusive Agency', 'Exclusive Agency Rights', 'Commercial Law'),
  ('LB-AGENCY-007', 'Exclusive Agency', 'Agence exclusive: l''agent exclusif a le droit de représenter le principal dans une zone déterminée', 'fr', 'Commercial Agency and Distribution Provisions, Article Exclusive Agency', 'Exclusive Agency Rights', 'Commercial Law'),
  ('LB-AGENCY-007', 'Exclusive Agency', 'الوكالة الحصرية: يحق للوكيل الحصري تمثيل الم principal في منطقة معينة', 'ar', 'Commercial Agency and Distribution Provisions, Article Exclusive Agency', 'Exclusive Agency Rights', 'Commercial Law'),
  ('LB-AGENCY-007', NULL, 'Commercial agency in Lebanon is governed by provisions in the Commercial Code and Civil Code. The Ministry of Economy and Trade maintains statistics on exclusive agencies. Foreign companies operating through agents in Lebanon must comply with registration requirements. Agency agreements should clearly define the scope of authority, territory, and compensation terms.', 'en', 'Commercial Agency and Distribution Provisions — Historical Context', 'Historical context and overview', 'Commercial Law'),
  ('LB-CONS-008', 'Article 1', 'This law protects consumers against harmful commercial practices', 'en', 'Consumer Protection Law, Article Article 1', 'Consumer Protection Scope', 'Consumer Protection'),
  ('LB-CONS-008', 'Article 1', 'Cette loi protège le consommateur contre les pratiques commerciales nuisibles', 'fr', 'Consumer Protection Law, Article Article 1', 'Consumer Protection Scope', 'Consumer Protection'),
  ('LB-CONS-008', 'Article 1', 'يحمي هذا القانون المستهلك من الممارسات التجارية الضارة', 'ar', 'Consumer Protection Law, Article Article 1', 'Consumer Protection Scope', 'Consumer Protection'),
  ('LB-CONS-008', 'E-Commerce Provisions (Law 81/2018)', 'Consumer Protection Law provisions apply to e-commerce provided they do not conflict with E-Transactions Law', 'en', 'Consumer Protection Law, Article E-Commerce Provisions (Law 81/2018)', 'E-Commerce Consumer Protection', 'Consumer Protection'),
  ('LB-CONS-008', 'E-Commerce Provisions (Law 81/2018)', 'Les dispositions de la loi sur la protection du consommateur s''appliquent au commerce électronique sous réserve de compatibilité', 'fr', 'Consumer Protection Law, Article E-Commerce Provisions (Law 81/2018)', 'E-Commerce Consumer Protection', 'Consumer Protection'),
  ('LB-CONS-008', 'E-Commerce Provisions (Law 81/2018)', 'تطبق أحكام قانون حماية المستهلك على التجارة الإلكترونية بشرط عدم تعارضها مع قانون المعاملات الإلكترونية', 'ar', 'Consumer Protection Law, Article E-Commerce Provisions (Law 81/2018)', 'E-Commerce Consumer Protection', 'Consumer Protection'),
  ('LB-CONS-008', 'Article 40 bis (Law 81/2018)', 'Consumer Protection Law provisions apply to matters related to electronic commerce', 'en', 'Consumer Protection Law, Article Article 40 bis (Law 81/2018)', 'E-Commerce Application', 'Consumer Protection'),
  ('LB-CONS-008', 'Article 40 bis (Law 81/2018)', 'Les dispositions de la loi sur la protection du consommateur s''appliquent aux questions relatives au commerce électronique', 'fr', 'Consumer Protection Law, Article Article 40 bis (Law 81/2018)', 'E-Commerce Application', 'Consumer Protection'),
  ('LB-CONS-008', 'Article 40 bis (Law 81/2018)', 'تطبق أحكام قانون حماية المستهلك على الأمور المتعلقة بالتجارة الإلكترونية بشرط عدم تناقضها مع هذا القانون', 'ar', 'Consumer Protection Law, Article Article 40 bis (Law 81/2018)', 'E-Commerce Application', 'Consumer Protection'),
  ('LB-CONS-008', NULL, 'The Consumer Protection Law (659/2005) establishes protections for consumers in Lebanon, prohibiting unfair commercial practices. The law was updated by Law 81/2018 on Electronic Transactions to include e-commerce consumer protection provisions. The Ministry of Economy and Trade is responsible for enforcement and publishes monthly consumer protection reports.', 'en', 'Consumer Protection Law — Historical Context', 'Historical context and overview', 'Consumer Protection'),
  ('LB-COMPET-009', 'General Provisions', 'Prohibits agreements between businesses that restrict competition such as price-fixing, market-sharing, and bid-rigging', 'en', 'Competition Protection Law, Article General Provisions', 'Anti-competitive Agreements', 'Competition Law'),
  ('LB-COMPET-009', 'General Provisions', 'Interdit les accords entre entreprises qui restreignent la concurrence tels que la fixation des prix, le partage des marchés et la collusion dans les appels d''offres', 'fr', 'Competition Protection Law, Article General Provisions', 'Anti-competitive Agreements', 'Competition Law'),
  ('LB-COMPET-009', 'General Provisions', 'يحظر الاتفاقيات بين الشركات التي تقيد المنافسة مثل تحديد الأسعار وتقسيم الأسواق والتزوير في المناقصات', 'ar', 'Competition Protection Law, Article General Provisions', 'Anti-competitive Agreements', 'Competition Law'),
  ('LB-COMPET-009', 'Abuse of Dominant Position', 'Businesses holding significant market power cannot engage in conduct that eliminates or restricts competition', 'en', 'Competition Protection Law, Article Abuse of Dominant Position', 'Dominant Position Abuse', 'Competition Law'),
  ('LB-COMPET-009', 'Abuse of Dominant Position', 'Les entreprises détenant un pouvoir de marché significatif ne peuvent pas se livrer à des comportements éliminant ou restreignant la concurrence', 'fr', 'Competition Protection Law, Article Abuse of Dominant Position', 'Dominant Position Abuse', 'Competition Law'),
  ('LB-COMPET-009', 'Abuse of Dominant Position', 'لا يجوز للشركات ذات القوة السوقية الكبيرة الانخراط في سلوك يلغي أو يقيد المنافسة', 'ar', 'Competition Protection Law, Article Abuse of Dominant Position', 'Dominant Position Abuse', 'Competition Law'),
  ('LB-COMPET-009', 'Merger Control', 'There is no formal pre-merger notification system under Lebanese law', 'en', 'Competition Protection Law, Article Merger Control', 'Merger Control', 'Competition Law'),
  ('LB-COMPET-009', 'Merger Control', 'Il n''existe pas de système formel de notification préalable des fusions en droit libanais', 'fr', 'Competition Protection Law, Article Merger Control', 'Merger Control', 'Competition Law'),
  ('LB-COMPET-009', 'Merger Control', 'لا يوجد نظام إلزامي للإخطار المسبق بالاندماجات بموجب القانون اللبناني', 'ar', 'Competition Protection Law, Article Merger Control', 'Merger Control', 'Competition Law'),
  ('LB-COMPET-009', NULL, 'Lebanon''s competition law is primarily governed by Law No. 369 of 2001 on the Protection of Competition. This law aims to promote and protect competition by prohibiting anti-competitive agreements, abuse of dominant positions, and other unfair market practices. Lebanon currently does not have a specialized competition authority; enforcement is mainly through the judiciary, where courts assess competition cases brought by the Ministry of Economy and Trade or private parties. Lebanon was the last country in the Middle East to introduce competition legislation (2022 according to some sources).', 'en', 'Competition Protection Law — Historical Context', 'Historical context and overview', 'Competition Law'),
  ('LB-IP-010', 'Trademark Definition (Resolution 2385)', 'Trademarks include names, titles, symbols, stamps, letters and drawings used to distinguish products', 'en', 'Intellectual Property and Trademark Laws, Article Trademark Definition (Resolution 2385)', 'Trademark Definition', 'Intellectual Property'),
  ('LB-IP-010', 'Trademark Definition (Resolution 2385)', 'Les marques comprennent les noms, titres, symboles, cachets, lettres et dessins utilisés pour distinguer les produits', 'fr', 'Intellectual Property and Trademark Laws, Article Trademark Definition (Resolution 2385)', 'Trademark Definition', 'Intellectual Property'),
  ('LB-IP-010', 'Trademark Definition (Resolution 2385)', 'العلامات التجارية تشمل الأسماء والعناوين والرموز والطوابع والحروف والرسوم التي تستخدم لتمييز المنتجات', 'ar', 'Intellectual Property and Trademark Laws, Article Trademark Definition (Resolution 2385)', 'Trademark Definition', 'Intellectual Property');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-IP-010', 'Trademark Duration (Law 324/2024)', 'Trademark protection duration: 10 years for new registrations (was 15 years)', 'en', 'Intellectual Property and Trademark Laws, Article Trademark Duration (Law 324/2024)', 'Trademark Duration', 'Intellectual Property'),
  ('LB-IP-010', 'Trademark Duration (Law 324/2024)', 'Durée de protection de la marque: 10 ans pour les nouveaux enregistrements (était 15 ans)', 'fr', 'Intellectual Property and Trademark Laws, Article Trademark Duration (Law 324/2024)', 'Trademark Duration', 'Intellectual Property'),
  ('LB-IP-010', 'Trademark Duration (Law 324/2024)', 'مدة حماية العلامة التجارية 10 سنوات للتسجيلات الجديدة (كانت 15 سنة سابقاً)', 'ar', 'Intellectual Property and Trademark Laws, Article Trademark Duration (Law 324/2024)', 'Trademark Duration', 'Intellectual Property'),
  ('LB-IP-010', 'Copyright (Law 75/99)', 'Protection of literary and artistic property - copyright', 'en', 'Intellectual Property and Trademark Laws, Article Copyright (Law 75/99)', 'Copyright Protection', 'Intellectual Property'),
  ('LB-IP-010', 'Copyright (Law 75/99)', 'Protection de la propriété littéraire et artistique - droit d''auteur', 'fr', 'Intellectual Property and Trademark Laws, Article Copyright (Law 75/99)', 'Copyright Protection', 'Intellectual Property'),
  ('LB-IP-010', 'Copyright (Law 75/99)', 'حماية الملكية الأدبية والفنية - حقوق المؤلف', 'ar', 'Intellectual Property and Trademark Laws, Article Copyright (Law 75/99)', 'Copyright Protection', 'Intellectual Property'),
  ('LB-IP-010', 'Patent Law (Law 240/2000)', 'Patent Law - protection of inventions and industrial models', 'en', 'Intellectual Property and Trademark Laws, Article Patent Law (Law 240/2000)', 'Patent Protection', 'Intellectual Property'),
  ('LB-IP-010', 'Patent Law (Law 240/2000)', 'Loi sur les brevets - protection des inventions et modèles industriels', 'fr', 'Intellectual Property and Trademark Laws, Article Patent Law (Law 240/2000)', 'Patent Protection', 'Intellectual Property'),
  ('LB-IP-010', 'Patent Law (Law 240/2000)', 'قانون براءات الاختراع - حماية الاختراعات والنماذج الصناعية', 'ar', 'Intellectual Property and Trademark Laws, Article Patent Law (Law 240/2000)', 'Patent Protection', 'Intellectual Property'),
  ('LB-IP-010', 'Article 137 (Resolution 2385)', 'The person who invents a literary or artistic work has the right of absolute possession of this work', 'en', 'Intellectual Property and Trademark Laws, Article Article 137 (Resolution 2385)', 'Creator''s Rights', 'Intellectual Property'),
  ('LB-IP-010', 'Article 137 (Resolution 2385)', 'La personne qui invente une œuvre littéraire ou artistique a le droit de possession absolue de cette œuvre', 'fr', 'Intellectual Property and Trademark Laws, Article Article 137 (Resolution 2385)', 'Creator''s Rights', 'Intellectual Property'),
  ('LB-IP-010', 'Article 137 (Resolution 2385)', 'للشخص الذي يخترع عملاً أدبياً أو فنياً حق الملكية المطلقة لهذا العمل', 'ar', 'Intellectual Property and Trademark Laws, Article Article 137 (Resolution 2385)', 'Creator''s Rights', 'Intellectual Property'),
  ('LB-IP-010', NULL, 'Lebanon''s intellectual property framework is based on Resolution 2385 of 1924 (governing commercial and industrial property) which was amended by the Law of January 31, 1946. Copyright is protected under Law 75/99, and patents under Law 240/2000. Lebanon is compliant with TRIPS standards and has ratified the Paris Convention, Madrid Agreement, and Berne Convention. In 2024, Law 324 reduced trademark protection duration from 15 to 10 years for new registrations. The Ministry of Economy and Trade''s Intellectual Property Protection Office (IPPO) oversees IP matters.', 'en', 'Intellectual Property and Trademark Laws — Historical Context', 'Historical context and overview', 'Intellectual Property'),
  ('LB-ETRAN-011', 'Article 4', 'Electronic writings and signatures have the same legal effect as writings and signatures on paper', 'en', 'Electronic Transactions and Personal Data Law, Article Article 4', 'Electronic Signature Validity', 'E-Commerce Law'),
  ('LB-ETRAN-011', 'Article 4', 'Les écrits et signatures électroniques ont le même effet juridique que les écrits et signatures sur papier', 'fr', 'Electronic Transactions and Personal Data Law, Article Article 4', 'Electronic Signature Validity', 'E-Commerce Law'),
  ('LB-ETRAN-011', 'Article 4', 'للكتابات والتوقيعات الإلكترونية نفس الأثر القانوني للكتابات والتوقيعات على الورق', 'ar', 'Electronic Transactions and Personal Data Law, Article Article 4', 'Electronic Signature Validity', 'E-Commerce Law'),
  ('LB-ETRAN-011', 'Article 7', 'Electronic writings are accepted as evidence and have the same evidentiary power as paper documents', 'en', 'Electronic Transactions and Personal Data Law, Article Article 7', 'Electronic Evidence', 'E-Commerce Law'),
  ('LB-ETRAN-011', 'Article 7', 'Les écrits électroniques sont acceptés comme preuve et ont la même force probante que le document papier', 'fr', 'Electronic Transactions and Personal Data Law, Article Article 7', 'Electronic Evidence', 'E-Commerce Law'),
  ('LB-ETRAN-011', 'Article 7', 'تُقبل الكتابات الإلكترونية كدليل ولها نفس القوة الإثباتية للوثيقة الورقية', 'ar', 'Electronic Transactions and Personal Data Law, Article Article 7', 'Electronic Evidence', 'E-Commerce Law'),
  ('LB-ETRAN-011', 'Article 41-64', 'Provisions on electronic banking services and electronic payments', 'en', 'Electronic Transactions and Personal Data Law, Article Article 41-64', 'E-Banking Services', 'E-Commerce Law'),
  ('LB-ETRAN-011', 'Article 41-64', 'Dispositions sur les services bancaires électroniques et les paiements électroniques', 'fr', 'Electronic Transactions and Personal Data Law, Article Article 41-64', 'E-Banking Services', 'E-Commerce Law'),
  ('LB-ETRAN-011', 'Article 41-64', 'أحكام الخدمات المصرفية الإلكترونية والمدفوعات الإلكترونية', 'ar', 'Electronic Transactions and Personal Data Law, Article Article 41-64', 'E-Banking Services', 'E-Commerce Law'),
  ('LB-ETRAN-011', 'Article 110-116', 'Offenses related to IT systems and bank cards', 'en', 'Electronic Transactions and Personal Data Law, Article Article 110-116', 'Cybercrime Provisions', 'E-Commerce Law'),
  ('LB-ETRAN-011', 'Article 110-116', 'Infractions relatives aux systèmes informatiques et aux cartes bancaires', 'fr', 'Electronic Transactions and Personal Data Law, Article Article 110-116', 'Cybercrime Provisions', 'E-Commerce Law'),
  ('LB-ETRAN-011', 'Article 110-116', 'الجرائم المتعلقة بأنظمة المعلوماتية والبطاقات المصرفية', 'ar', 'Electronic Transactions and Personal Data Law, Article Article 110-116', 'Cybercrime Provisions', 'E-Commerce Law'),
  ('LB-ETRAN-011', NULL, 'Law 81/2018 was enacted to address the growing reliance on electronic documents, digital signatures, and online transactions. It provides a comprehensive legal framework for electronic transactions, personal data protection, and associated activities. The law grants electronic documents and signatures the same legal standing as traditional paper-based documents, facilitates e-commerce, and establishes data protection standards. COLIBAC (Lebanese Accreditation Council) oversees electronic authentication services.', 'en', 'Electronic Transactions and Personal Data Law — Historical Context', 'Historical context and overview', 'E-Commerce Law'),
  ('LB-MONEY-012', 'General Provisions', 'Covers monetary regulation, the role of Banque du Liban, and banking activities', 'en', 'Code of Money and Credit, Article General Provisions', 'Banking Regulation', 'Banking Law'),
  ('LB-MONEY-012', 'General Provisions', 'Couvre la réglementation monétaire, le rôle de la Banque du Liban, et les activités bancaires', 'fr', 'Code of Money and Credit, Article General Provisions', 'Banking Regulation', 'Banking Law'),
  ('LB-MONEY-012', 'General Provisions', 'يغطي تنظيم النقد ودور مصرف لبنان والوظائف والأنشطة المصرفية', 'ar', 'Code of Money and Credit, Article General Provisions', 'Banking Regulation', 'Banking Law'),
  ('LB-MONEY-012', 'BDL Authority', 'Banque du Liban powers to issue regulations and supervise banks', 'en', 'Code of Money and Credit, Article BDL Authority', 'Central Bank Authority', 'Banking Law'),
  ('LB-MONEY-012', 'BDL Authority', 'Pouvoirs de la Banque du Liban pour émettre des règlements et superviser les banques', 'fr', 'Code of Money and Credit, Article BDL Authority', 'Central Bank Authority', 'Banking Law'),
  ('LB-MONEY-012', 'BDL Authority', 'صلاحيات مصرف لبنان في إصدار اللوائح والرقابة على المصارف', 'ar', 'Code of Money and Credit, Article BDL Authority', 'Central Bank Authority', 'Banking Law'),
  ('LB-MONEY-012', NULL, 'The Code of Money and Credit is the main regulation of the banking and financial system in Lebanon. It covers the regulation of money, the Central Bank of Lebanon''s role and functions, banks'' activities, and the activities of professions linked to the banking profession. Law 28/67 amended the Code and established the Higher Banking Commission and the Banking Control Commission at the Central Bank.', 'en', 'Code of Money and Credit — Historical Context', 'Historical context and overview', 'Banking Law'),
  ('LB-AML-013', 'General Provisions', 'The Special Investigation Commission has the exclusive right to lift banking secrecy', 'en', 'Anti-Money Laundering Law, Article General Provisions', 'SIC Authority', 'Financial Crime Law'),
  ('LB-AML-013', 'General Provisions', 'La Commission Spéciale d''Investigation a le droit exclusif de lever le secret bancaire', 'fr', 'Anti-Money Laundering Law, Article General Provisions', 'SIC Authority', 'Financial Crime Law'),
  ('LB-AML-013', 'General Provisions', 'اللجنة الخاصة للتحقيق في تبيض الأموال وتمويل الإرهاب لها الحق الحصري في رفع السرية المصرفية', 'ar', 'Anti-Money Laundering Law, Article General Provisions', 'SIC Authority', 'Financial Crime Law'),
  ('LB-AML-013', NULL, 'Law 318/2001 was enacted to combat money laundering and terrorist financing in Lebanon. It established the Special Investigation Commission (SIC) as the sole authority empowered to lift banking secrecy for investigations related to money laundering and terrorist financing. The law was amended by Law 44/2015 to strengthen provisions.', 'en', 'Anti-Money Laundering Law — Historical Context', 'Historical context and overview', 'Financial Crime Law'),
  ('LB-COM-001', '1-10', 'Definition of commercial acts, merchant status, commercial register requirements.', 'en', 'Code of Terrestrial Commerce / Code of Commerce, Article 1-10', 'Commercial acts and merchants', 'Commercial Law'),
  ('LB-COM-001', '44-68', 'Commercial books and accounting obligations for merchants.', 'en', 'Code of Terrestrial Commerce / Code of Commerce, Article 44-68', 'Commercial books', 'Commercial Law'),
  ('LB-COM-001', '307-488', 'Negotiable instruments: bills of exchange, promissory notes, checks.', 'en', 'Code of Terrestrial Commerce / Code of Commerce, Article 307-488', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001', '489-560', 'Bankruptcy and insolvency proceedings.', 'en', 'Code of Terrestrial Commerce / Code of Commerce, Article 489-560', 'Bankruptcy', 'Commercial Law'),
  ('LB-COM-001', NULL, 'Lebanon''s commercial code was modeled closely on the French Commercial Code. Replaced the Ottoman Commercial Code (1850), itself a translation of the French Code de Commerce of 1807. Governs commercial transactions, merchant obligations, partnerships, negotiable instruments, bankruptcy, and commercial pledges. The companies chapter was replaced by Decree-Law 150/1983.', 'en', 'Code of Terrestrial Commerce / Code of Commerce — Historical Context', 'Historical context and overview', 'Commercial Law'),
  ('LB-COM-001', 'Part on companies', 'Replaced the companies chapter of the Code of Commerce with a comprehensive modern companies law.', 'en', 'Code of Terrestrial Commerce / Code of Commerce — Amendment: Decree-Law No. 150 of September 16, 1983 (Companies Law)', 'Amendment', 'Commercial Law'),
  ('LB-COM-002', NULL, 'Replaced the companies portion of the 1942 Code of Commerce. Governs formation, operation, and dissolution of all types of commercial companies: general partnerships (société en nom collectif), limited partnerships (société en commandite simple), joint stock companies (société anonyme / SAL), limited liability companies (société à responsabilité limitée / SARL), and holding companies (société holding). The SAL and SARL are the most common corporate forms in Lebanon.', 'en', 'Companies / Commercial Companies Law — Historical Context', 'Historical context and overview', 'Commercial Law'),
  ('LB-COM-002', NULL, 'Updated holding company regulations.', 'en', 'Companies / Commercial Companies Law — Amendment: Law No. 126/2019 (Holding Companies)', 'Amendment', 'Commercial Law'),
  ('LB-COM-003', NULL, 'Governs maritime commerce including ship registration, maritime liens, charter parties, bills of lading, maritime insurance, collisions, salvage, and general average. Important for Lebanon given the significance of the Port of Beirut to the national economy.', 'en', 'Maritime Commerce Code — Historical Context', 'Historical context and overview', 'Commercial Law'),
  ('LB-COM-004', NULL, 'Lebanon''s primary intellectual property legislation. Covers copyright, literary and artistic works, and neighboring rights. Lebanon is a member of the Berne Convention and TRIPS Agreement. Trademark protection is governed by separate legislation (Decree No. 2385 of 1924).', 'en', 'Literary and Artistic Property Protection Law — Historical Context', 'Historical context and overview', 'Commercial Law'),
  ('LB-COM-004', NULL, 'Comprehensive patent protection law.', 'en', 'Literary and Artistic Property Protection Law — Amendment: Law No. 240/2000 (Patent Law)', 'Amendment', 'Commercial Law'),
  ('LB-COM-004', NULL, 'Updated copyright protections to align with international standards.', 'en', 'Literary and Artistic Property Protection Law — Amendment: Law No. 423/2002 (Copyright Amendment)', 'Amendment', 'Commercial Law'),
  ('LB-COM-005', NULL, 'Law No. 659/2005 established the consumer protection framework including product safety requirements, labeling, fair pricing, and established the Consumer Protection Directorate within the Ministry of Economy and Trade.', 'en', 'Consumer Protection Law — Historical Context', 'Historical context and overview', 'Commercial Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-COM-006', NULL, 'Originally enacted as Decree No. 2385 of January 17, 1924, during the French Mandate. One of the oldest continuously enforced laws in Lebanon. Governs trademark registration, protection, and enforcement. Lebanon maintains a first-to-use system rather than first-to-file.', 'en', 'Trademarks, Trade Names and Unfair Competition — Historical Context', 'Historical context and overview', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '1', 'Article 1 The present code contains the rules relating to all acts of trade, irrespective of the legal quality of their performer, on the one hand, and provisions enforceable on professional traders, on the other.', 'en', 'Commercial Code (Expanded), Article 1', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '2', 'Article 2 Unless otherwise specified in the present code, common law provisions shall apply. in commercial matters, only in so far as they are reconcilable with the principles proper to the commercial law.', 'en', 'Commercial Code (Expanded), Article 2', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '3', 'Article 3 In the absence of any applicable legal provision, the judge can draw upon previous test cases for guidance as much as he may let himself inspired by the strictures of commercial equity and loyalty.', 'en', 'Commercial Code (Expanded), Article 3', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '4', 'Article 4 In his assessment of the effects of a commercial operation, the judge shall apply well established usages, unless it becomes apparent that the parties had. agreed to derogate them, and unless such usages run counter to imperative legal provisions. Special or local usages are presumed to override general usages.', 'en', 'Commercial Code (Expanded), Article 4', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '5', 'Article 5 Trade exchanges, fairs and markets, general warehouses, entrepots and other institutions for trade, are, whenever necessary, governed by special laws or regulations. TITLE II - TRADE ACTS', 'en', 'Commercial Code (Expanded), Article 5', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '6', 'Article 6 Are considered land trade acts by their own nature such acts as are hereinafter listed, as well as those which, by their apparently identical characters and the identical purpose they pursue, could be likened thereto: 1 - The purchase of goods or other movables, corporeal and incorporeal, with a view to re-sale at a profit, either in a state of nature or after they have been fashioned or transformed; 2- The purchase of the same movable objects for letting or renting for subletting; 3- The re-sale, letting or sub-letting of the objects thus purchased or rented; 4 - Exchange or bank operations; 5 - Supplying; 6- Manufacturing, even if this is ancillary to an agricultural exploitation, but excluding the case when transformation is achieved through simple manual work; 7 - Land, water or air transport; 8 - Commission and brokerage; 9 - Fixed premiums insurance; 10 - Public entertainments; 11 - Publishing; 12 -General warehousing; 13 - Mining or petroleum enterprises; 14 - Real estate enterprises; 15 - Buying buildings for re-sale at a profit; 16 - Business agencies.', 'en', 'Commercial Code (Expanded), Article 6', 'Sale of goods', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '7', 'Article 7 Are likewise acts of maritime trade 1 - Any construction enterprise, all purchases of vessels for internal or external navigation, in order to exploit them commercially or for re-sale, and all sales of vessels thus acquired; 2 - A11 maritime expeditions and all operations related thereto, as well as the purchase or sale of gear, tackle and supplies; 3 - Freighting or chartering of vessels, bulk borrowing or lending; 4 - All other contracts concerning sea trade, such as agreements and conventions for the crew''s hire and wages, the employment of sea-farers for the manning of trade vessels.', 'en', 'Commercial Code (Expanded), Article 7', 'Sale of goods', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '8', 'Article 8 The law also recognizes as acts of trade all those that are performed by the merchant for the requirements of this trade. Barring proof to the contrary, a merchant''s acts are presumed, in the event of doubt, to be so designed. TITLE III - MERCHANTS CHAPTER 1 - Traders in general and the legal qualification required to go into trade', 'en', 'Commercial Code (Expanded), Article 8', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '9', 'Article 9 Traders are 1 - Those whose profession is to transact acts of trade; 2 - Companies whose object is commercial. Those whose object is civil, but which have assumed the form of joint-stock companies or of partnership companies limited by shares, shall be submitted to all the merchant''s obligations as specified in chapters 2 and 3 and hereinafter, as well as- to the system of composition and insolvency as is laid down in Book V of the present code.', 'en', 'Commercial Code (Expanded), Article 9', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '10', 'Article 10 Those who individually carry on a small trade or simple handicraft with minimal overheads, such as the peddler, the journeyman retailer or he who undertakes small transport operations by land or water, are not subject to those obligations concerning trade books, nor to the publicity rules prescribed by the present code.', 'en', 'Commercial Code (Expanded), Article 10', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '11', 'Article 11 The married woman, whatever the provisions of her personal status, is legally qualified for trading only in so far as she obtains her husband''s express or tacit agreement. Tacit agreement is presumed granted when trade is public and manifest, and is carried on without the husband''s opposition.', 'en', 'Commercial Code (Expanded), Article 11', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '12', 'Article 12 Agreement thus granted may be cancelled for just motives by the husband, subject to judicial control, if need be. Such cancellation shall be mentioned in the trade register.', 'en', 'Commercial Code (Expanded), Article 12', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '13', 'Article 13 The married woman regularly qualified enjoys unrestricted legal capacity to transact all acts in the interest of her commercial enterprise. However she must be specifically authorized if she intends to join a partnership or be financed in a limited company.', 'en', 'Commercial Code (Expanded), Article 13', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '14', 'Article 14 The married woman''s rights are limited, if need be, by the rules of her personal status or by those of her matrimonial regime.', 'en', 'Commercial Code (Expanded), Article 14', 'Women''s rights', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '15', 'Article 15 Any separate maintenance pronounced abroad shall be no bar against Third Parties, in Lebanon, unless such separation has been duly entered on-the trade register of the place where the spouses or either of them carries on a commercial trade. CHAPTER 2 - Trade books', 'en', 'Commercial Code (Expanded), Article 15', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '16', 'Article 16 (as modified by the Law promulgated by Decree N° 9800 of ---------- (4 May 1968 Any natural or juridical person duly qualified as trader is required to keep a ledger on which he shall record, day by day, all the operations concerning, under whatever title this may be, his commercial enterprise and, at the least, whenever he is prevented from doing so by the very nature of his work in the enterprise, relate month by month, the results of these operations, on condition that in the latter case, he should keep all the documents which make possible the checking of the regularity of these operations, day after day, throughout the period provided in article 19 of the Code of Commerce. He must equally draw up an annual inventory of all the elements of his enterprise and all the accounts thereof in order to strike the Balance Sheet and the Profit and Loss Account and to record, at the very least, the Balance Sheet and the Profit and Loss Account in the inventory book. If this book does not comprise the detailed elements of the inventory, the supporting documents must be filed and kept throughout the period referred to in article 19 of the Code of Commerce.', 'en', 'Commercial Code (Expanded), Article 16', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '17', 'Article 17 Compulsory trade books are to be kept by calendar order, without spacing, gaps, marginal annotations, interlinear spacing or erasures.', 'en', 'Commercial Code (Expanded), Article 17', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '18', 'Article 18 They are numbered, initialed and countersigned, either in the town where sits the Court of primary jurisdiction by the president of this Court, or by the conciliation magistrate.', 'en', 'Commercial Code (Expanded), Article 18', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '19', 'Article 19 The books must be kept by the trader for a period of 10 years after their closure.', 'en', 'Commercial Code (Expanded), Article 19', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '20', 'Article 20 They-may be accepted as documentary evidence in Court in favor of the trader on condition that they are regularly kept, that their statements are used against another trader and that the dispute concerns an act of trade. In all cases, they are proof against the trader who has kept them; if the latter refuses to produce them, the oath may be administrated by the judge to the other party.', 'en', 'Commercial Code (Expanded), Article 20', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '21', 'Article 21 The books are submitted to Court in full only in the event of an inheritance, the apportionment of common property, company, composition and insolvency. Apart from these cases, the presentation of the books may always be offered, required or even prescribed as a matter of course in order to draw therefrom what concerns the dispute. CHAPTER 3 - The trade register', 'en', 'Commercial Code (Expanded), Article 21', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '22', 'Article 22 The trade register enables the public to collect complete information regarding all the business houses operating in the country. It is also, whenever expressly stated by the law, an instrument of publicity designed to use the entries therein against Third Parties.', 'en', 'Commercial Code (Expanded), Article 22', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '23', 'Article 23 A register is kept in the district of each Court of primary jurisdiction, by a Clerk, under the supervision of a president or that of a judge specially designated each year by the latter. Section 1 - Registration of traders of every nationality whose main establishment is in Lebanon', 'en', 'Commercial Code (Expanded), Article 23', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '24', 'Article 24 Every trader must require the Court Clerk in whose district his main establishment lies, to list him on the register within one calendar month of the opening or the acquisition of his stock-in-trade. The applicant remits the Clerk a declaration, in duplicate, duly signed by him; the declaration indicates 1 - The t rader''s surname and first names; 2 - The name under which he carries on his trade and, if need be, his nickname and borrowed name; 3 - The date and place of birth; 4- His original nationality and, in the event of his acquiring a new nationality, the date and the process by which such nationality was acquired; 5- If the case concerns a married woman of foreign nationality who, under the terms of her personal status, is not authorized to engage in trading without her husband''s expressed authorization, the authorization given in conformity with this status; b - The matrimonial regime of the trader of foreign nationality, unless this is legal community (of property); 7 - The object of the trade; 8- The places where lie the branches or agencies of the stock-in-trade in Lebanon or in Syria; 9 - The sign or "style" of the establishment; 10 - The surname, first names, date and place of birth as well as nationality of the proxies; 11 - The trade establishment which the applicant has previously exploited or those under exploitation within the territorial competence of other Courts. The Clerk reproduces the contents of the declaration on the trade register. He remits the applicant one copy of it, on the bottom of which he certifies it true to original.', 'en', 'Commercial Code (Expanded), Article 24', 'Property law', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '25', 'Article 25 Must also be mentioned on the trade register 1- Any change or modification relating to the facts, the entry of which in the register is prescribed by the preceding article. 2- The patents exploited and the manufacturing or trade marks employed by the trader; 3- The rulings or orders appointing a legal counsel to the registered trader or pronouncing a prohibition on him, as well as decisions of repletion. 4- Judgments or orders adjucating insolvency, confirming a scheme of arrangement, pronouncing the termination or annulment, declaring excusability, closing the insolvency for insufficient assets, rescinding a closure order, pronouncing rehabilitation. 5- Conveyance of the stock-in-trade. Entries are required of the trader in cases referred to in Nos. 1, 2 & 5 of the present article. They are so required by the Clerk and the Court who pronounced the decisions for entry, in the cases referred to in Nos. 3 6c 4 of the present article. Entries are effected as a matter of course by the Clerk when judgment has been passed by the Court in whose office the register is kept. Section 2 - Registration of trading companies of every nationality whose main establishment is in Lebanon', 'en', 'Commercial Code (Expanded), Article 25', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '26', 'Article 26 Trading companies of every nationality whose main establishment is in Lebanon must be entered on the trade register of their head office. Registration is requested within one month of the company formation, either by the Manager or by the Directors. Petitioners produce in the Court office an abstract of the deed of partnership on stamped paper, in duplicate signed by them, bearing notably the following indications 1- The surnames and names of partners other than the shareholders and sleeping partners, the date and place of birth, the nationality of each of them; 2- The style or denomination of the company; 3- The object of the company; 4- The places where the company operates branches or agencies, either in Lebanon or abroad; 5 - The names of partners or Third Parties authorized to administer, manage or sign for the company; 6 - The amount of the company capital and the amount of sums or value to be provided by the shareholders or sleeping partners, as well as the individual importance of contributions in cash and those in other goods; 7 - The time when the company commences and that when it must end; 8 - The nature of the company; 9 - If it is with sliding capital, the level down to which capital may be reduced.', 'en', 'Commercial Code (Expanded), Article 26', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '27', 'Article 27 Are to be equally mentioned on the trade register 1- Any change or mo dification regarding the facts entry of which is prescribed by the preceding article; 2- The surnames, names, date and place of birth, as well as the nationality of Managing Directors, Hoard Directors or Directors appointed in the course of the duration of the company; 3- The patents exploited and the manufacturing or trade marks employed by the company. Registration thereof is required of Managing Directors or Board Directors in office at the time when such registration is to be made. 4- Judgments or orders pronouncing the dissolution or nullity of the company; 5- Judgments or orders adjudicating the Company''s insolvency or confirming its scheme of arrangement as well as decisions relating thereto. Section 3 - Traders of every nationality operating their main establishment abroad and a branch office or agency in Lebanon', 'en', 'Commercial Code (Expanded), Article 27', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '28', 'Article 28 Any trader operating a main establishment in a foreign country and a branch office or agency in Lebanon must, whatever his nationality, have himself registered within the month following the opening of such agency or branch office, in the Court Office within whose territorial competence the agency lies. The declaration must contain the aforementioned entries with indication of the place of the main establishment. Equally to be mentioned on the trade register are all the modifications stated above as well as the foregoing judgments or orders, when they have been declared executory by the Courts of those countries. Section 4 - Foreign companies operating a branch office or an agency in Lebanon', 'en', 'Commercial Code (Expanded), Article 28', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '29', 'Article 29 Excluding joint-stock companies or partnership companies limited by shares governed by High Commissioner''s Order No. 96 of 30 January 1926, any foreign commercial company operating a branch office or an agency in Lebanon is required to register on the trade register.', 'en', 'Commercial Code (Expanded), Article 29', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '36', 'Article 36 Every trader and company, under obligation of registration, is required to state on his letters, invoices, order sheets, price lists, pamphlets and other printed matter emanating from his house, the place where he is regis tered and his registration number.', 'en', 'Commercial Code (Expanded), Article 36', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '37', 'Article 37 (as modified by the Law promulgated by Decree N° 9798 of ---------- (4 May 1968 Any trader, manager or company director who does not carry out within the prescribed time-limits the compulsory inscriptions or who does not show the necessary references on the letters, invoices, or other printed matter emanating from his house is under penalty of a fine from fifty to one thousand Lebanese Pounds. The fine is inflicted by the Court of primary jurisdiction on the request of the president or of the judge in charge of the supervision of the trade register, after the interested party has been heard or summoned. The Court ordains that the omitted inscription shall be made within a fortnight. If it has not been effected, within this time-limit, the fine duly inflicted shall be doubled. The Court Recorders who do not conform to the obligations provided by the present rule shall be subject to disciplinary proceedings.', 'en', 'Commercial Code (Expanded), Article 37', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '38', 'Article 38 (as modified by the Law promulgated by Decree N° 9798 of ---------- (4 May 1968 Any incorrect reference given in ill faith with the view to its registration or inscription in the trade register is under penalty of a fine from 250 to 5,000 Pounds and of a term of imprisonment from one month to six months or of either penalty, without prejudice to the application of cumulative penalties to the stronger sentence passed in conformity with special laws and the Penal Code for all offences resulting from the incorrect reference. The sentence of the Misdemeanor Court passing the condemnation ordains that the incorrect reference shall be rectified ''in the wording that it determines.', 'en', 'Commercial Code (Expanded), Article 38', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '39', 'Article 39 These penalties are enforceable without prejudice to the invalidation of opposition to Third Parties of the facts or mentions, the entry of which on the trade register is prescribed under penalty of nullity. TITLE IV - STOCK-IN-TRADE', 'en', 'Commercial Code (Expanded), Article 39', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '40', 'Article 40 (Abrogated and replaced by Decree-Law N° 11 of 11 July 1967)', 'en', 'Commercial Code (Expanded), Article 40', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '41', 'Article 41 (Abrogated and replaced by Decree-Law N° 11 of 11 July 1967) BOOK II COMMERCIAL COMPANIES TITLE I - GENERAL PROVISIONS', 'en', 'Commercial Code (Expanded), Article 41', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '42', 'Article 42 The rules laid down by the code of obligations relating to company contracts are enforceable on commercial companies, only in so far as they would not be in expressed or even tacit contradiction with the rules of the present code.', 'en', 'Commercial Code (Expanded), Article 42', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '43', 'Article 43 All commercial companies, with the exception of participating companies, are to be stated in writing. But Third Parties may, if need be, be admitted to prove by all means the existence either of the company, or of such company clause.', 'en', 'Commercial Code (Expanded), Article 43', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '44', 'Article 44 Deeds of partnership of all commercial companies, with the exception of participating companies, must, under penalty of nullity, be published, through the completion of formalities which shall be detailed hereinafter.', 'en', 'Commercial Code (Expanded), Article 44', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '45', 'Article 45 All commercial companies, under the same exception, are endowed with moral personality. TITLE II - PARTNERSHIP COMPANIES', 'en', 'Commercial Code (Expanded), Article 45', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '46', 'Article 46 A partnership company, which operates under a style, is constituted by two or several persons who are personally and jointly responsible for the liabilities of the company.', 'en', 'Commercial Code (Expanded), Article 46', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '47', 'Article 47 The partnership deed of the company may be indifferently authenticated or under private seal; in the latter case, as many copies as there are partners must be made out.', 'en', 'Commercial Code (Expanded), Article 47', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '48', 'Article 48 Within the month of the company formation, a duplicate or copy of the deed of partnership is to be deposited in the Clerk''s Office of the Court of primary jurisdiction where the company head office lies.', 'en', 'Commercial Code (Expanded), Article 48', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '49', 'Article 49 Within the same time-limit the company must be entered on the trade register of its head office. This publicity shall be made by abstract and shall contain all the entries which Third Parties are interested to know, notably 1- The names, first names, nationality, domiciles of the partners and the style of the company; 2- The form of the company; 3- Its object; 4- Its head office and its branch offices and agencies; 5- The amount of the company capital and the value attributed to contributions; 6- The names of partners or of proxies empowered to sign for the company; 7- The date of formation and the duration of the company.', 'en', 'Commercial Code (Expanded), Article 49', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '50', 'Article 50 In the event of a subsequent modification of the deed of partnership a new deposit must be lodged with the Clerk''s office. Registration must also be made in the trade register, if this concerns an item of interest to Third Parties.', 'en', 'Commercial Code (Expanded), Article 50', 'Banking and credit', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '51', 'Article 51 Failure to deposit in the Clerk''s Office or to enter in the trade register the deed of partnership entails the nullity of the company and, in the event of prejudice to Third Parties, the joint liability of all the partners. The omission of an entry of interest to Third Parties, either in the Articles deposited in the Clerk''s Office, or in the abstract of the trade register, invalidates the opposition of this clause to interested parties. Failure of publicizing alterations to the Company deed invalidates the opposition of such modifications to Third Parties.', 'en', 'Commercial Code (Expanded), Article 51', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '52', 'Article 52 Nullity for defaulting in publicity is not prescribed. It may however be invoked by all interested parties, but the partners are not authorized to avail themselves of it against Third Parties. However, if the publicity formalities were belatedly completed, only those persons who have dealt with the company before its compliance with regulations may avail themselves of the nullity incurred.', 'en', 'Commercial Code (Expanded), Article 52', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '53', 'Article 53 Each of the partners of a partnership company must be considered as trading by himself under. a company style; each acquires the legal quality of trader and the failure of the company entails the individual failures of all the partners. Article-54 The "style" is composed of the names of all the partners or of some of them followed by the words "& Co.". It must always correspond to the present personnel of the company; the Third Party who would knowingly allow his name to stand in the style would be liable for the debts of the company in relation to anyone who might have thus been misled into error.', 'en', 'Commercial Code (Expanded), Article 53', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '55', 'Article 55 Apart-from conveyances which would have been expressly provided for in the deed of partnership, the partners'' shareholding interests may not be ceded to Third Parties, except by the unanimous consent of all the partners and subject to compliance with all the publicity obligations. Hut a partner is authorized to transmit to a Third Party the rights and advantages deriving from his holding interest, such agreement having effect only between the contracting parties.', 'en', 'Commercial Code (Expanded), Article 55', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '56', 'Article 56 Management belongs to all partners, unless it has been entrusted, by the Articles or a subsequent deed, to one or several partners or even to an outsider.', 'en', 'Commercial Code (Expanded), Article 56', NULL, 'Commercial Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-COM-001-EXPANDED', '57', 'Article 57 Managers are subject to dismissal in accordance with the same conditions as have governed their appointment; however, if the dismissal is abusive, this may give title to damages within the framework of article 822 of the code of obligations. Substitution of a new manager for a statutory manager must be published.', 'en', 'Commercial Code (Expanded), Article 57', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '58', 'Article 58 Managers may perform all acts required for the normal operation of the enterprise under partnership, except for such curtailment of their powers as many be provided by the (company) Articles.', 'en', 'Commercial Code (Expanded), Article 58', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '59', 'Article 59 (as modified by the Law promulgated by Decree N° 9798 of ---------- (4 May 1968 Without the special permission of partners renewable if need be every year, managers may not conclude for their personal account any deal with the company or any agreement wherein one of them or all should have a direct or indirect interest. Usual contracts bearing on operations effected by the company with its customers are excluded from this prohibition.', 'en', 'Commercial Code (Expanded), Article 59', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '60', 'Article 60 Neither can Managers, without due authorization renewed every year, apply themselves to the management of a similar enterprise.', 'en', 'Commercial Code (Expanded), Article 60', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '61', 'Article 61 If there are several Managers, each of them may veto the conclusion of operations contemplated by the others. The decision lies with the majority of Managers unless the veto is grounded on the unstatutory character of the projected act. Eventually, it shall lie with the Court to appreciate the character of the act.', 'en', 'Commercial Code (Expanded), Article 61', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '62', 'Article 62 Managers commit the company, whenever they act within the limits of their powers and that they sign under the company style, even if such signature is used in their own interest, except when the Third Party is of ill faith.', 'en', 'Commercial Code (Expanded), Article 62', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '63', 'Article 63 The company creditors take action against the company which they must serve with formal notice to pay them, and against each of the partners within the partnership at the time when the commitment is contracted; the latter are held jointly on their personal assets.', 'en', 'Commercial Code (Expanded), Article 63', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '64', 'Article 64 The causes for dissolution, common to all trading companies, are the following . 1 - Expiry of the time for which the company had been formed; 2 - The normal end of the contemplated enterprise; 3 - The disappearance of the very object of the enterprise. On the other hand, the Court may always, upon the partners'' request, either declare the dissolution of the company for such causes as it may appreciate, or decide the exclusion of such a partner who does not meet his obligations under the partnership.', 'en', 'Commercial Code (Expanded), Article 64', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '65', 'Article 65 Partnership companies are, moreover, submitted to the following causes of dissolution 1- The will of one of the partners, if the company has been formed for unlimited duration, on condition that such withdrawal does not endanger the legitimate interests of the company, due regard being taken of the circumstances during which this intervenes; 2- General disqualification of one of the partners; 3- The insolvency of one of them. However, the other partners may unanimously decide to continue the partnership among themselves, to the exclusion of the resigning partner, but on condition that the measures of legal publicity are proceeded with.', 'en', 'Commercial Code (Expanded), Article 65', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '66', 'Article 66 Unless otherwise provided in the Articles, in the event of a partner''s death, the partnership company continues among the survivors if the pre-deceased leaves neither spouse nor descendant to collect titles. Otherwise, the company continues with the spouse or the descendants, who assume the quality of sleeping partners.', 'en', 'Commercial Code (Expanded), Article 66', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '67', 'Article 67 In all cases, the value of partnership titles of a pre-deceased or excluded partners is assessed by special stock-taking, unless another mode of assessment is provided under the Articles.', 'en', 'Commercial Code (Expanded), Article 67', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '68', 'Article 68 The dissolution, except in the event when it conforms to provisions in the partnership deed, must be published in like manner and time-limit as the deed itself. The same applies when one of the partners is exc luded or when the company is continued after the death of one of the partners.', 'en', 'Commercial Code (Expanded), Article 68', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '69', 'Article 69 After the dissolution of trading companies, their personality is supposed to survive only during the period and for the requirements of liquidation.', 'en', 'Commercial Code (Expanded), Article 69', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '70', 'Article 70 If the Articles fail to designate the liquidator or liquidators and if the partners fail to agree on their choice, it shall lie with the Court of the head office to appoint them.', 'en', 'Commercial Code (Expanded), Article 70', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '71', 'Article 71 The deliberations or the judicial ruling designating the liquidators shall be published by the latter.', 'en', 'Commercial Code (Expanded), Article 71', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '72', 'Article 72 Upon their taking office, the liquidators are required to proceed with stocktaking, jointly with the managers.', 'en', 'Commercial Code (Expanded), Article 72', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '73', 'Article 73 The liquidators shall recover what may be due to the company by Third Parties or by the partners; they shall settle the company''s debts, realize the assets and perform such acts as may be necessary for liquidation. But they could not continue the exploitation of the company enterprise nor cede its stock-in-trade globally, without obtaining special authorization from the partners.', 'en', 'Commercial Code (Expanded), Article 73', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '74', 'Article 74 Upon the partners'' request, the liquidators shall have to provide all information regarding the state of liquidation, on condition that the process of liquidation is not impeded by abusive requests.', 'en', 'Commercial Code (Expanded), Article 74', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '75', 'Article 75 Sharing-out shall be effected according to the provisions of the deed of partnership and, also, in conformity with the rules laid down in articles 941 to 949 of the code of obligations.', 'en', 'Commercial Code (Expanded), Article 75', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '76', 'Article 76 In all trading companies, except for proceedings which may be taken against the liquidators as such, cases brought by the company''s creditors against its partners, their heirs or other persons concerned,, shall be limited to five years after the dissolution of the company, or after the departure of a partner in so far as he may be concerned. This time limitation commences on the day when publicity has been completed whenever such publicity is required. Limitation in respect of cases which may arise from the liquidation itself commences on the day this liquidation is closed. The time-limitation may be interrupted or suspended according to what is provided by the rules of common law. TITLE III - JOINT-STOCK COMPANIES', 'en', 'Commercial Code (Expanded), Article 76', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '77', 'Article 77 The joint-stock company is a company deprived of a "style", formed by a certain number of persons who subscribe to shares, negotiable securities, and who are held for the company liabilities only up to the amount of their contribution.', 'en', 'Commercial Code (Expanded), Article 77', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '78', 'Article 78 (as modified by Decree-Law N° 54 of 16 June 1977) Whatever its object, every joint-stock company shall be subject to the laws and practices of commerce. All joint-stock companies established in Lebanon shall have their Read Office in Lebanese territory, and such companies shall - as a matter of unqualified right - vested with Lebanese nationality, notwithstanding any text to the contrary. One third of joint-stock companies capital whose object is the operation of a public service shall be made up of nominal shares belonging to Lebanese shareholders. In any case, such shares may not be ceded except to Lebanese shareholders, failing which cession shall be null and void. CHAPTER 1 - Formation', 'en', 'Commercial Code (Expanded), Article 78', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '79', 'Article 79 (as modified by the Law promulgated by Decree No 9798 of ---------- (4 May 1968 The number of Founders may not be less than three. No one may participate in the foundation of a joint-stock company if he has been declared insolvent and has not been rehabilitated over the last ten years at least, convicted in Lebanon or abroad within less than ten years, for a crime or offence, subject to penalties of swindling, or embezzlement of funds or securities, the mala fide issue of unfunded cheques, for impairing the financial security of the State as is defined in articles 319 and 320 of the Penal Code, or for receiving goods acquired though these crimes. The same conditions apply to representatives of juridical persons participating in the foundation of a company. Company Founders are jointly liable for commitments entered into and for expenses made towards the formation of the company, without recourse against subscribers for shares in the event the company failed to be formed.', 'en', 'Commercial Code (Expanded), Article 79', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '80', 'Article 80 (as modified by the Law of 23 November 1948 and by Decree-Law ---------- (N° 54 of 16 June 1977 With due regard to the provisions of laws and regulations which submit the performance of certain activities to a prior license, the setting up of joint-stock companies shall require no authority emanating from the administrative authorities. The articles of association of the joint-stock company and any subsequent modification shall be submitted and registered with the Notary of the district where the company''s head office is located.', 'en', 'Commercial Code (Expanded), Article 80', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '81', 'Article 81 (as modified by the Law promulgated by Decree N° 9798 of ---------- (4 May 1968 Before any call is made to the public for subscription to the company capital, Founders are required to have it inserted in the Official Gazette and in two newspapers, one a local daily and the other economic, a notice bearing the signature and address of each of them and indicating notably the, "style" and the head office of the company and of its branches, its object, its duration, the amount of the company capital, the nominal value of the shares and the initial down payment, the importance of contributions in kind, the clause of fixed interest, the conditions of profit-sharing, the number of directors, their statutory remuneration and their powers. The individual subscription form, the share certificate, as well as the posters, circular letters and prospectuses mu st carry the statements of the notice, with reference to the issue of the newspapers where it was published.', 'en', 'Commercial Code (Expanded), Article 81', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '82', 'Article 82 (as modified by the Law promulgated by Decree N° 9798 of ---------- (4 May 1968 Any infringement to the provisions of the preceding article is liable to a fine from 1,000 to 5,000 Lebanese Pounds, without prejudice to the Court''s powers to cancel, if need be, such subscriptions as may have already been collected.', 'en', 'Commercial Code (Expanded), Article 82', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '83', 'Article 83 (as modified by the Law promulgated by Decree N° 9798 of ---------- (4 May 1968 The company capital which may not be less than 300,000 Lebanese Pounds must be fully subscribed.', 'en', 'Commercial Code (Expanded), Article 83', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '84', 'Article 84 The minimum rate of fractional shares is 25 Lebanese Ponds and each subscriber is required to make a minimum down payment, in cash, of one quarter of the amount of his shares.', 'en', 'Commercial Code (Expanded), Article 84', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '85', 'Article 85 (as modified by the Law promulgated by Decree N° 9798 of ---------- (4 May 1968 Founders may deposit these sums paid-in by subscribers before the definitive formation of the company in one of the State-approved banks under an account established in the name of the company with the list of subscribers and the sums individually paid-in. These sums shall be withdrawn after the formation of the company under the signature of the person or persons duly qualified according to the Articles and upon the production of copies, certified true to the Articles, of the decree authorizing the formation and of the minutes of the Constituent Meeting. In the absence of a deposit or when the sums so deposited have been withdrawn or disposed of wholly or partially before the definitive formation of the company, infringers are liable to a fine equal to 10 per cent of the value of the sums deposited, withdrawn or utilized and are open, if the case so requires, to penalties for breach of trust or dishonest management, without prejudice to liabilities under civil law which such acts may involve them into. If the company has not been formed within the six-month time-limit dating from the authorization, any subscriber shall be entitled to petition the judge of summary procedure to appoint a provisional administrator whose terms of reference will be to withdraw the sums and repay them to the subscribers after deducting charges for distribution. _', 'en', 'Commercial Code (Expanded), Article 85', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '86', 'Article 86 (as modified by the Law promulgated by Decree NO 9798 of ---------- (4 May 1968 The accuracy of evaluation of contributions in kind is subject to the appreciation of one or several experts appointed by ordinance from the president of the Court in whose locality lies the head office of the company upon the request of the Founders, such expert or experts to be selected from the panel of experts officially agreed by the Court. The vesting of individual advantages in the company Articles on whomsoever is prohibited.', 'en', 'Commercial Code (Expanded), Article 86', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '87', 'Article 87 The experts'' report shall be put at the disposal of subscribers; the latter shall be authorized to relinquish their subscription if the Founder''s assessment exceeds by 20 per cent the actual value of initial shares and advantages, according to the appreciation of competent persons. It shall lie with the Founders to subscribe in substitution of the defaulting subscribers or to have others subscribe for the latter''s shares.', 'en', 'Commercial Code (Expanded), Article 87', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '88', 'Article 88 The initial shares must be paid up at the time of the formation of the company.', 'en', 'Commercial Code (Expanded), Article 88', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '89', 'Article 89 They remain registered, must be left attached to the counterfoil and struck with a stamp indicating their nature and the date of the formation of the company; they shall not be negotiable until after the approval by the General Meeting of the accounts of the second financial year. Non-negotiability does not apply to the initial shares allotted to shareholders of an amalgamated company, whose securities had already become negotiable.', 'en', 'Commercial Code (Expanded), Article 89', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '90', 'Article 90 (as modified by the Law promulgated by Decree N° 9798 of ---------- (4 May 1968 Within one calendar month of the expert''s report, the Founders are required to convene a general meeting of the shareholders, such meeting to be announced ten clear days in advance, wherein the expert''s report on the evaluation of contributions in kind shall be submitted. Deliberations shall then be held in conformity with the rules of quorum and majority proper to such meetings. Contributions in kind shall be barred from voting, even though they should equally be subscribers for shares in cash or agents for such subscribers. This procedure may not be imposed whenever there are contributors in cash outside contributors in kind.', 'en', 'Commercial Code (Expanded), Article 90', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '91', 'Article 91 (as modified by the Law promulgated by Decree N° 9798 of ---------- (4 May 1968 Completion of these formalities does not preclude subsequent proceedings for liability which may be jointly initiated within five years dating from formation, against the Founders, contributors in cash, first directors, first supervisory commissioners and experts whenever a substantial and conscious overestimation of the contributions in kind should be demonstrated.', 'en', 'Commercial Code (Expanded), Article 91', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '92', 'Article 92 The constituent meeting verifies in all cases, with supporting evidence, if all the terms of the company formation have been met.', 'en', 'Commercial Code (Expanded), Article 92', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '93', 'Article 93 The meeting appoints the first Directors, in the event they have not been designated in the Articles, as well as the first supervisory commissioners, and the company is formed upon their acceptance. Directors and supervisory commissioners must ascertain, under their joint responsibility, that the company has been formed in accordance with regulations.', 'en', 'Commercial Code (Expanded), Article 93', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '94', 'Article 94 When a joint-stock company has been formed irregularly, any interested party shall be empowe red, within a period of five years, to give it formal notice that the omitted formality should be accomplished. In the event of failure by the company to initiate, within one calendar month, a regularizing procedure, the interested party shall be authorized to have it pronounced null. Nullity may not be opposed to Third Parties by the partners. The annulled company is liquidated as a de facto company.', 'en', 'Commercial Code (Expanded), Article 94', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '95', 'Article 95 (as modified by the Law promulgated by Decree N° 9798 of ---------- (4 May 1968 In the event of irregular formation, proceedings for joint liability may be taken, alongside proceedings for nullity, by the partners or Third Parties against the Founders, the first directors, first supervisory commissioners and equally against contributors in kind and experts in those cases where the formalities for verification should not have been faithfully observed. But the plaintiff will be required to prove the existence of a relationship of cause to effect between the irregularity of formation and the prejudice he sustained. These proceedings for liability shall have the same duration as proceedings for nullity, without however being subject to curtailment to less than three years through rectification of the irregularity.', 'en', 'Commercial Code (Expanded), Article 95', 'Inheritance and succession', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '96', 'Article 96 (as modified by the Law promulgated by Decree N° 9798 of -_------_- (4 May 1968 Shall be under the penalty of a fine from 500 to 5,000 Lebanese Pounds those persons who, even in bona fide, should have delivered to subscribers final certificates of shares of a joint-stock comp any irregularly incorporated, as well as those who should have negotiated or participated in negotiating such shares, or officially published the value of these shares, in case where irregularity was at least apparent.', 'en', 'Commercial Code (Expanded), Article 96', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '97', 'Article 97 Any fraudulent scheming designed to urge subscriptions or payment shall come under penalties for swindling.', 'en', 'Commercial Code (Expanded), Article 97', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '98', 'Article 98 Once the company has been formed, the Directors are bound to proceed with the initial formalities of publicity, of deposit in the Clerk''s Office and of registration on the trade register, such as are prescribed for all companies.', 'en', 'Commercial Code (Expanded), Article 98', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '99', 'Article 99 Default in publicity shall entail the same penalties : nullity either of the company, or of the omitted clause; joint liability of the first Directors and the first supervisory commissioners, whose duty is to control the completion of all formalities.', 'en', 'Commercial Code (Expanded), Article 99', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '100', 'Article 100 In addition, the company is submitted to a permanent publicity thus constituted Articles must be put up on the Notice Board of the company offices. Any person may obtain a copy certified true, against normal remuneration. All the printed or autographed matters of the company must make mention of its denomination, whether it is a joint-stock company, the amount of its capital and the portion which has been paid down.', 'en', 'Commercial Code (Expanded), Article 100', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '101', 'Article 101 (as modified by the Law promulgated by Decree NO 9798 of ----------- (4 May 1968 Every year, two months following the approval of accounts by the general meeting, the Directors shall have the Balance Sheet of the closed financial year published in the Official Gazette, as well as in an economic newspaper and a local daily, together with the list of the members of the Board and of the account commissioners.', 'en', 'Commercial Code (Expanded), Article 101', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '102', 'Article 102 (as modified by the Law promulgated by Decree NO 9798 of ----------- (4 May 1968 The formality regarding the publicity of the Balance Sheet shall be under the sanction of a fine of between 1,000 and 5,000 Lebanese Pounds; formalities concerning the posting of the Articles and of the reference to be carried on the written material emanating from the company shall be under the sanction of a fine of between 100 and 1,000 Lebanese Pounds. In the event of a second offence, penalty shall be doubled. CHAPTER 2 - Securities issued by joint-stock companies and the legal status of holders of such securities', 'en', 'Commercial Code (Expanded), Article 102', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '103', 'Article 103 (as modified by Decree-Law No 54 of 16 June 1977) Joint-stock companies issue shares. They may issue debentures, as they may also issue debentures convertible into shares. They are forbidden to issue founder-shares, that is to say, securities giving title to profit-sharing without a previous contribution to capital. Section 1 - Shares', 'en', 'Commercial Code (Expanded), Article 103', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '104', 'Article 104 Shares are equal subdivisions of the company capital, indivisible, to which correspond a negotiable security either registered, or to Order, or to Bearer.', 'en', 'Commercial Code (Expanded), Article 104', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '105', 'Article 105 The share confers on its holder a certain number of specific rights right to dividend, right to option to subscription in the event of capital increase, right to refund of the nominal amount of the share and to the apportionment of the company''s assets, right of vote at general meetings, right of conveyance of his title.', 'en', 'Commercial Code (Expanded), Article 105', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '106', 'Article 106 The dividend must bear only on the net profit resulting from a genuine balance sheet and which remains available after providing for the legal and statutory reserve funds.', 'en', 'Commercial Code (Expanded), Article 106', NULL, 'Commercial Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-COM-001-EXPANDED', '107', 'Article 107 (as modified by the Law promulgated by Decree N° 9798 of ----------- (4 May 1968 Every fictitious dividend distribution involves the civil liability of the Directors towards whosoever may be prejudiced therefrom. Liability of the account commissioners is equally involved if they have failed in their supervisory duties. Penal liability of these very persons may be involved if dividends are dis tributed in the absence of any Balance Sheet or by virtue of a report on fraudulent stock-taking, Balance Sheet, or Profit and Loss Account. Their penalty shall be that of swindling.', 'en', 'Commercial Code (Expanded), Article 107', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '108', 'Article 108 Shareholders who have received these dividends are not bound to refund them unless their dishonesty or their serious offence equivalent to fraud has been proved. Action for recouping, which may be taken against them, either by the company, or by the company''s creditors, shall force them to bear, in addition to the sum unduly received, the interests on this sum from the day of payment. This action is time-limited to five years dating from distribution.', 'en', 'Commercial Code (Expanded), Article 108', 'Fraud', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '109', 'Article 109 Sums distributed in conformity with clauses of fixed interests paid to shareholders in all eventualities and posted to the comp any''s overheads do not constitute fictitious dividends. However, to be in order, such a clause is submitted to the following conditions : the rate of interest may not exceed 4 per cent; the application time of the clause is of a maximum five years; the interests paid shall be comprised in the expenditures of the first establishment to be written off as such in the balance sheets showing a profit. This clause must be published in accordance with regulations, under penalty of nullity.', 'en', 'Commercial Code (Expanded), Article 109', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '110', 'Article 110 In principle, all the shareholders of the same company must enjoy the same rights and participate in the same advantages. However it is permitted to create, by a resolution of an extraordinary meeting deliberating as shall be indicated hereinafter, preference shares whenever the Articles are not formally against them.', 'en', 'Commercial Code (Expanded), Article 110', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '116', 'Article 116 Every shareholder is entitled to take part in the different meetings which are held for the formation and the operation of the company, and to vote therein with a power, in principle, equal to the number of shares he holds.', 'en', 'Commercial Code (Expanded), Article 116', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '117', 'Article 117 However, paid up shares, existing under registration in the name of the same holder for at least the last two years before each meeting is convened, shall give title to two votes each. Registered shares are supposed, from the point of view of time elapsed, to have belonged to the same holder, when they have been acquired through inheritance, donation or legacy.', 'en', 'Commercial Code (Expanded), Article 117', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '118', 'Article 118 Without prejudice to the restrictions on contribution shares and the directors'' guarantee shares, every shareholder is totally free to convey his title to an acquirer who shall assume his partnership''s rights and obligations. However a preemption right may be stipulated in the Articles, on behalf either of the partners or of a number of them, or of the company itself, on condition that it is used within a time-limit and payment terms determined by statute. But the exercise of this right should not degenerate into abuse, either by suppressing practically the negotiable character of the share, or by causing the shareholder a serious prejudice. The preemption right stipulated on behalf of the company may not be exercised by the company except through reserves.', 'en', 'Commercial Code (Expanded), Article 118', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '119', 'Article 119 The holder of a share which is not fully paid up is required to answer the company''s call far funds. Are severally held for the payment of the unpaid (balance) all those who have held the share before him, but only for the two-year period following the transfer. The share shall remain registered until it has been fully paid up. All statutory clauses contrary to the provisions of the present article would be null.', 'en', 'Commercial Code (Expanded), Article 119', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '120', 'Article 120 The old shareholder who has been forced to pay up a security conveyed by him shall be legally subrogated in the company''s rights and proceedings against all subsequent holders of the security.', 'en', 'Commercial Code (Expanded), Article 120', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '121', 'Article 121 In cases of default of total payment, the company may proceed, after serving summons on the defaulting shareholder, with hammering at the Exchange at the latter''s expenses, risks and perils. If the proceeds of the sale are below the amount of the payment due, the shareholder shall be held the excess. Section 2 - Debentures', 'en', 'Commercial Code (Expanded), Article 121', 'Sale of goods', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '122', 'Article 122 (as modified by the Law promulgated by Decree NO 9798 of ----------- (4 May 1968 The company may issue negotiable and indivisible debentures, of an equal nominal amount, delivered to subscribers as counterpart for the sums loaned by them. There can be no issue of debentures until all the capital subscribed by shareholders has been paid up. Directors or managers who shall have issued or allowed the issue of debentures in violation of the preceding paragraph shall be under penalty of a fine of between 1,000 and 5,000 Lebanese Pounds, and such debentures shall be null.', 'en', 'Commercial Code (Expanded), Article 122', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '123', 'Article 123 The debenture-holder is entitled to a fixed interest payable at periodical intervals and to the refund of his capital out of the company assets.', 'en', 'Commercial Code (Expanded), Article 123', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '124', 'Article 124 (as modified by Decree-Law NO 54 of 16 June 1977) With due regard to the rules applicable on real estate credit companies, no debentures may be issued for an amount in excess of double the company''s capital still available following the last approved balance sheet.', 'en', 'Commercial Code (Expanded), Article 124', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '125', 'Article 125 Even when provided by the Articles, the issue of debentures may not take place except after the regular deliberation of a general meeting.', 'en', 'Commercial Code (Expanded), Article 125', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '126', 'Article 126 (as modified by the Law promulgated by Decree NO 9798 of ___-___-__- (4 May 1968 Prior to any publicity preceding issue, company directors are required under penalty of a fine of between 1,000 and 5,000 Lebanese Pounds to insert in the Official Gazette, as well as in an economic newspaper and a local daily, a notice bearing the signature and address of each one of them and indicating notably; the date of the resolution of the general meeting authorizing the issue; the number and value of the debentures to be issued; the rate of interest; the time, the conditions and the guarantees of refund; the amount of the capital and of its paid-in portion; the importance of the contributions in kind; the existence of a clause of fixed interest; the results of the last Balance Sheet certified true.', 'en', 'Commercial Code (Expanded), Article 126', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '127', 'Article 127 (as modified by the Law promulgated by Decree N° 9798 of ----------(4 May 1968 The subscription form, the certificate of debentures as well as the posters, circulars-letters and prospectuses must reproduce the statements of this notice, with reference to the issues of the newspapers wherein it was published.', 'en', 'Commercial Code (Expanded), Article 127', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '128', 'Article 128 Those who would have subscribed to debentures, without compliance with these formalities, may have their subscription cancelled.', 'en', 'Commercial Code (Expanded), Article 128', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '129', 'Article 129 (as modified by the Law promulgated by Decree NO 9798 of ----------(4 May 1968 Any debentures issue, once realized, must be mentioned in the trade register through the good offices of the Directors. If they fail to comply with this formality, they shall be under penalty of a fine of between 500 and 2,500 Lebanese Pounds.', 'en', 'Commercial Code (Expanded), Article 129', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '130', 'Article 130 If the debentures have not been initially fully paid up, and if calls for fund remain unanswered, the company may have recourse to the hammering-down procedure at the Exchange.', 'en', 'Commercial Code (Expanded), Article 130', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '131', 'Article 131 Debentures on mortgage may be issued. The issue of such securities is governed by the High Commissioner Order No. 77/L.R. of 26 May 1933.', 'en', 'Commercial Code (Expanded), Article 131', 'Mortgage', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '132', 'Article 132 (as modified by the Law promulgated by Decree NO 9798 of ----------(4 May 1968 Premium debentures must be duly authorized by the government following the proposal of the Minister of National Economy.', 'en', 'Commercial Code (Expanded), Article 132', 'Insurance', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '133', 'Article 133 Debentures may be issued with refund premiums which are paid at the time the security is redeemed.', 'en', 'Commercial Code (Expanded), Article 133', 'Insurance', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '134', 'Article 134 The refund of debentures is effected according to the terms laid down at the time of issue, and the company is not entitled to delay or advance its period (of maturity).', 'en', 'Commercial Code (Expanded), Article 134', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '135', 'Article 135 Notwithstanding clauses to the contrary, debenture-holders are gathered in a group which is self-formed at every issue and whose decisions, taken by majority vote, are compulsory upon all.', 'en', 'Commercial Code (Expanded), Article 135', 'Electoral', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '136', 'Article 136 After the closing of subscription, the issuing company shall convene a general meeting of debenture-holders, who shall approve the statutes of the group and who shall appoint their representatives.', 'en', 'Commercial Code (Expanded), Article 136', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '137', 'Article 137 The general meeting of debenture-holders may be convened whenever it is deemed necessary, either by a group of holders representing 1/20 of the debentures, or by the joint-stock company.', 'en', 'Commercial Code (Expanded), Article 137', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '138', 'Article 138 (as modified by the Law promulgated by Decree N° 9798 of (4 May 1968 The meeting shall be convened by two consecutive insertions, within eight days of each other, in the Official Gazette, in an economic newspaper and in a local daily, indicating the subjects on the agenda which, alone, may be debated.', 'en', 'Commercial Code (Expanded), Article 138', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '139', 'Article 139 Quorum and voting shall be governed by the rules laid down in articles 193 and 195 concerning shareholders general meetings.', 'en', 'Commercial Code (Expanded), Article 139', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '140', 'Article 140 Representatives of a debenture-holders group may validly take all measures designed to safeguard the letter''s rights.', 'en', 'Commercial Code (Expanded), Article 140', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '141', 'Article 141 But such measures as may be intended to grant an extension of the refund time-limit, or to reduce either the interest rates, or the capital of the debt, or the sureties matching it and, broadly speaking, all measures sacrificing the rights of debenture-holders, shall not be adopted except by the debenture-holders general meeting in conformity with the conditions of quorum set in the first paragraph of', 'en', 'Commercial Code (Expanded), Article 141', 'Banking and credit', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '193', 'Article 193 (as modified by the Law promulgated by Decree NO 9798 of -______---- (4 play 1968 The constituent meeting deliberates validity only when it is composed of the company capital. If this quorum is not secured, a new meeting may be convened following two insertions made, at a week''s interval, in the Official Gazette, an economic newspaper and a local daily. Convocation states the agenda of the preceding meeting and the results obtained. This second meeting deliberates validly if it is composed of shareholders representing at least fifty per cent of the company capital. If this quorum is not yet secured, a third assembly representing only ---third of the company capital,. at least- may I° ''--', 'en', 'Commercial Code (Expanded), Article 193', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '142', 'Article 142 Debenture-holders'' proxies shall be entitled to attend the s hareholders'' general meetings, but without debating power, after having obtained the same communications as the shareholders.', 'en', 'Commercial Code (Expanded), Article 142', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '143', 'Article 143 When any company has continued to pay interests or dividends for shares, debentures or other securities repayable through drawing, it may not repeat these sums, when the security is presented for refund, notwithstanding any clause to the contrary. CHAPTER 3 - Operation of joint-stock companies Section 1 - Directors', 'en', 'Commercial Code (Expanded), Article 143', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '144', 'Article 144 (as modified by the Law promulgated by Decree N° 9798 of --_ (4 May 1968 The management of the joint-stock company shall be entrusted to a Hoard of Directors consisting of three members, at least, and of twelve members, at most. Without prejudice to what could be provided by special legislation for certain joint-stock companies, the majority at least of the members of the Board of Directors must be of Lebanese nationality. The Hoard of Directors must appoint one of its members for the chairmanship.', 'en', 'Commercial Code (Expanded), Article 144', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '145', 'Article 145 Their remuneration consists either of an annual stipend, or in tallies for attendance, or a percentage of the net profit, or a combination of these various advantages. The profit on which the Directors'' percentage is based must comprise, in principle, only the net product of the exploitation which is the object of the company. Thus portfolio proceeds may not be included but exceptionally and by virtue of a special resolution of the general meeting renewed every year..', 'en', 'Commercial Code (Expanded), Article 145', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '146', 'Article 146 (as modified by the Law of 23 November 1948) Directors are elected by the shareholders'' general meeting. However, the first Directors may be designated by the company Articles. If, in the intervening period between two annual meetings, the number in office is reduced by death, resignation or any other cause, below half the minimum number set by the Articles, or below three, the remaining Director must convene a general meeting within a maximum time-limit of two months in order to provide the vacant posts.', 'en', 'Commercial Code (Expanded), Article 146', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '147', 'Article 147 (as modified by the Law promulgated by Decree N° 14028 of ----------- (16 March 1970 The general meeting elects the members of the Hoard of Directors from among those shareholders who hold a minimum number of shares as fixed in the Articles. Such shares shall remain registered; they shall be struck with the "not negotiable" stamp and deposited in the company''s treasury. They shall be assigned to provide security for the individual and collective liability of the Directors for all acts of mismanagement of which they might be guilty.', 'en', 'Commercial Code (Expanded), Article 147', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '148', 'Article 148 (as modified by the Law promulgated by Decree N° 9798 of ----------- (4 May 1968 None may be called to directorship if he has been declared insolvent and has not been rehabilitated over the last ten years at least, convicted in Lebanon or abroad within the last ten years at least for a crime or offence or for attempted crime or offence described as forgery, theft, swindling, breach of trust, for an offence liable to sanctions for swindling, or embezzlement of funds or securities, for the mala fide issue of unfunded cheques or for attempt against the State financial security within the provisions of articles 319 and 320 of- the Penal Code, or for receiving goods acquired through these crimes. The same conditions apply to representatives of juridical persons sitting on the Board of Directors.', 'en', 'Commercial Code (Expanded), Article 148', 'Theft and robbery', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '149', 'Article 149 Directors by virtue of the statutes are appointed for a maximum period of 5 years; those who are appointed by the shareholders'' meeting are for a maximum period of three years, subject to re-election. The statutes may provide for the partial renewal of the Hoard.', 'en', 'Commercial Code (Expanded), Article 149', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '150', 'Article 150 Notwithstanding any clause to the contrary, Directors are liable to dismissal ad nutum.', 'en', 'Commercial Code (Expanded), Article 150', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '151', 'Article 151 In case the dismissal should have been decided by the shareholders'' general meeting, while the matter was not included on the agenda, such a resolution shall not take effect except after it has been confirmed by a new meeting whose agenda shall state the object. This second meeting shall be convened by the supervisory commissioners, within two months of the first. It shall be chaired by one of the commissioners.', 'en', 'Commercial Code (Expanded), Article 151', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '152', 'Article 152 Any change effected in the composition of the Board shall be mentioned in the trade register by the Directors.', 'en', 'Commercial Code (Expanded), Article 152', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '153', 'Article 153 (as modified by the Law promulgated by Decree No 9798 of (4, May 1968 and by Decree-Law N° 54 of 16 June 1977 The Chairman of the Board of Directors shall discharge the duties of General Manager. The Chairman shall be at liberty to propose that the Board appoints a General Manager other than himself. However, such Manager shall discharge his duties on behalf of the Chairman and under his personal responsibility. The Chairman of the Board of Directors may appoint a consultative committee made up of members of the Board or managers from outside the Board, or members of Board and managers. Members of this committee shall be charged to look into matters referred to them by the Chairman. The committee''s findings shall be binding neither on the Chairman nor on the Board. In case the Chairman should find himself definitively prevented from discharging his duties, he may delegate such duties, wholly or partially, to a Director, for a limited period of time. In case the Chairman should find himself definitively prevented from discharging his duties, the Board of Directors shall deem him resigning and appoint another. Directors may fill administrative posts in the company for a salary which shall be fixed by the Board of Directors, but in this event they shall not have the benefit of the provisions of the Code of Labor, except if they have been on the payroll of the company for at least two years by the time they accede to the post of Directors.', 'en', 'Commercial Code (Expanded), Article 153', 'Employment and labor', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '154', 'Article 154 (as modified by the Law of 15 February 1957) None can exercise more than four chairman''s mandates, provided that General Managers are appointed in two out of the four companies that he chairs. None can be Director in more than six companies, whose head office is in Lebanon. If a Director is over 70 years of age, he may not hold directorship in more than two companies. Is considered chairman or Director of a single company whoever is chairman or Director of several insurance companies operating under the same style.', 'en', 'Commercial Code (Expanded), Article 154', 'Insurance', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '155', 'Article 155 (as modified by the Law of 23 November 1948) The chairman of the Board is reputed a trader for the enforcement of article 135 only in the following cases The commercial Court must apply on him those forfeitures which the law attaches to insolvency if the company is declared insolvent and that this is ascribable to fraud or to serious offences in the management of the company''s affairs. If the chairman''s functions have been delegated wholly or partially to a Director, as provided under article 153, the latter incurs, in so far as this delegation is concerned, the responsibilities defined by the present article, in lieu of the chairman.', 'en', 'Commercial Code (Expanded), Article 155', 'Fraud', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '156', 'Article 156 (as modified by the Law of 23 November 1948) The attendance or representation of at least half of the Directors is required for the validity of the Board''s resolutions.. A Director is forbidden to represent more than one other Director.', 'en', 'Commercial Code (Expanded), Article 156', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '157', 'Article 157 (as modified by the Law promulgated by Decree NO 9798 of --_-------- (4 May 1968 The Board of Directors has the most extensive powers to carry out the resolutions of the general meeting and to transact such operations as are a normal part of the business management and which are not to be considered as current affairs. These powers have no other limitations or restrictions, except for what may be edicted by law and company Articles. The chairman of the Board of Directors and, eventually, the General Manager or the Managing Director in pursuance of sub-paragraph 4 of article 153, representing the company before Third Parties, assume the execution of the resolutions of the Board and the dispatch of the company''s current business, such as may be determined by the Articles or usage, under the supervision of the Board of Directors. The Board of Directors may, for a short and limited period, delegate certain of its powers to its chairman or to the Deputy General Manager, such delegation being subject to registration on the trade register. The company is held for the acts of its representatives performed within the scope of their powers; beyond that scope it shall be held only for such acts as may be authorized or approved by the shareholders'' general meeting.', 'en', 'Commercial Code (Expanded), Article 157', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '158', 'Article 158 (as modified by the Law promulgated by Decree N° 9798 of ----------- (4 May 1968 Any deal concluded between-the company and a Director is subject to the prior approval of the general meeting, whether such deal is transacted directly or through a middleman. Acts covering day-to-day operations between the company and its customers are exempted from this provision. Equally submitted to this authorization is any transaction passed between the company and another establishment which would be owned by one of the Directors and in which the latter would be a joint partner, manager or director: The Director who should be in- one of these cases is required to advise the Board of Directors accordingly. The Board of Directors and the supervisory commissioner submit - separately -to the general meeting a report on the transactions to be concluded, and the general meeting shall take its decision in the light of these two reports. Transactions so authorized may not be incriminated except in the event of concealment. Authorization must be renewed every year if it concerns transactions involving long-term consecutive commitments. Directors are forbidden, except when they are juridical persons, to obtain in their favor from the company, in any manner whatsoever, an open current account, a guarantee or an endorsement of trade Bills made out to the order of Third Parties. Such prohibition does not apply to banks if the aforementioned acts constitute normal operations within the scope of these banks.', 'en', 'Commercial Code (Expanded), Article 158', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '159', 'Article 159 Directors may not, without special authorization renewed every year, take part in the management of a similar company.', 'en', 'Commercial Code (Expanded), Article 159', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '160', 'Article 160 Directors are forbidden to take an interest in all companies, associations, syndicates or groupings of whatever description, which would undertake operations designed to influence in the Stock Market all sorts of securities issued by the company.', 'en', 'Commercial Code (Expanded), Article 160', 'Companies and corporate', 'Commercial Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-COM-001-EXPANDED', '161', 'Article 161 Directors must establish, at the end of the first semester of every financial year, a summary statement of the liabilities and assets, and, at the end of the year, a stock-taking, a balance sheet, and a Profit and Loss Account.', 'en', 'Commercial Code (Expanded), Article 161', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '162', 'Article 162 (as modified by the Law promulgated by Decree NO 9798 of _-_----___- (4 May 1968 The Balance Sheet must be clear and methodical. Any change from one year to another in the method of its establishment or presentation is to be accompanied by special explanations in the report of the account commissioners.', 'en', 'Commercial Code (Expanded), Article 162', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '163', 'Article 163 (as modified by the Law promulgated by Decree N° 9798 of _-_____--_- (4 May 1968 The Balance Sheet must comprise all the postings which shall be determined by decree and, in all cases, reveal the amount of holding interests which the company may have in other enterprises either in the form of shareholding, or in a different form and, especially, the amount of advances which would have been granted to subsidiaries.', 'en', 'Commercial Code (Expanded), Article 163', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '164', 'Article 164 It is for the Directors to convene the shareholders'' general meetings.', 'en', 'Commercial Code (Expanded), Article 164', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '165', 'Article 165 Directors are required to setup reserve funds, by diverting 10 per cent of the net profit,-until the fund has reached one-third of the company capital.', 'en', 'Commercial Code (Expanded), Article 165', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '166', 'Article 166 Directors are responsible, even towards Third Parties, for all fraudulent acts and all infringements to the Law and the Articles. Proceedings open to the injured party are individual; they may not be checked, even in relation to shareholders, by a vote of the general meeting granting final discharge to the Directors.', 'en', 'Commercial Code (Expanded), Article 166', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '167', 'Article 167 Directors are, on the other hand, responsible to shareholders for their mismanagement. As a general rule, the Directors'' liability for mismanagement is not involved in relation to Third Parties. However, in the event of insolvency or juridical liquidation of the company, demonstrating insufficient assets, the commercial Court may, either on the request of the Receiver or judicial Liquidator, or that of the Public Prosecutor''s office, or even officially, decide that the company''s debts shall be borne, up to an amount it shall determine, by the Directors and all other persons vested with a management or supervisory mandate, with or without joint (liability). In order to clear their responsibility, they must produce proof that in their management of the company''s business they have exercised the diligence of a salaried proxy.', 'en', 'Commercial Code (Expanded), Article 167', 'Agency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '168', 'Article 168 The case to be brought against the Directors by virtue of the first paragraph of the preceding article, lies with the company. But in the event of the latter''s inertia, any shareholder may take proceedings in its place within the limit of his interest in the company.', 'en', 'Commercial Code (Expanded), Article 168', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '169', 'Article 169 Final discharge, if it is to be used as defense, must always be preceded by a statement of the company''s account and the commissioners'' report; it only covers facts of management with which the general meeting may have been acquainted.', 'en', 'Commercial Code (Expanded), Article 169', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '170', 'Article 170 They commit their responsibility, either individually or jointly, even towards third parties, whenever they commit a supervision offence, subject to the five-year time-limit. Section 3 - Shareholders general meetings', 'en', 'Commercial Code (Expanded), Article 170', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '171', 'Article 171 Proceedings for liability are limited to five years dating from the meeting during which the Directors were required to account for their management. Section 2 - Supervis ory commissioners', 'en', 'Commercial Code (Expanded), Article 171', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '172', 'Article 172 The constituent meeting, then the ordinary meetings appoint one or several supervisory commissioners, whose functions are for a one-year term, but who may be returned.', 'en', 'Commercial Code (Expanded), Article 172', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '173', 'Article 173 A complementary commissioner, selected from the panel of chartered accountants approved by the Court of primary jurisdiction, with the same powers and remuneration, is seconded to them. He is designated by order of the Court of the company''s head office, such order to be uttered on the request of the Board within two months following the formation of the company, their every year, within the month following the holding of the ordinary general meeting.', 'en', 'Commercial Code (Expanded), Article 173', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '174', 'Article 174 The supervisory commissioners exercise a permanent control over the company''s operations. They may require to be acquainted with all deeds, all documentary evidence in support of accounts, demand ail information from the Directors. Stock-taking, the balance sheet and the Profit and Loss Account shall be put at their disposal fifty days, at the latest, prior to the general meeting.', 'en', 'Commercial Code (Expanded), Article 174', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '175', 'Article 175 The commissioners report to the general meeting on the situation of the company, the balance sheet, the accounts tabled before them by the Directors and the proposed dividend distribution. Failure (to produce) this report would nullify the deliberation of the general meeting approving the accounts.', 'en', 'Commercial Code (Expanded), Article 175', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '176', 'Article 176 Commissioners are required to convene the general meeting whenever the Directors omit so doing, in cases specified by law or by the Articles. Likewise they are empowered to convene the meeting in all cases they deem it needful. They are even bound to do it, when they are so required by a group of shareholders representing one-fifth of the company''s capital.', 'en', 'Commercial Code (Expanded), Article 176', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '177', 'Article 177 They are not to take any interest in a group whose object would be to influence Stock Exchange dealings involving any of the company''s securities.', 'en', 'Commercial Code (Expanded), Article 177', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '179', 'Article 179 There are a shareholders'' constituent meeting, ordinary meetings and extraordinary meetings.', 'en', 'Commercial Code (Expanded), Article 179', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '180', 'Article 180 Power to convene, in respect of ordinary and extraordinary meetings, lies as a matter of principle with the Directors, and, in respect of the constituent meeting, with the Founders. Supervisory commissioners may substitute for Directors in the aforementioned cases.', 'en', 'Commercial Code (Expanded), Article 180', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '181', 'Article 181 Shareholders who cannot attend a meeting may have themselves represented by proxies, who must themselves be shareholders, except as regards the legal representatives of shareholders deprived of legal capacity.', 'en', 'Commercial Code (Expanded), Article 181', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '182', 'Article 182 An attendance sheet is kept, wherein are mentioned the names and domiciles of shareholders attending and represented, the number of shares each of them holds and the number of votes relating to these shares. This sheet shall be deposited in the company''s head office and communicated to any applicant who shall prove his shareholding quality.', 'en', 'Commercial Code (Expanded), Article 182', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '183', 'Article 183 An office shall be set up, composed of at least a chairman and a secretary.', 'en', 'Commercial Code (Expanded), Article 183', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '184', 'Article 184 The meeting may debate only matters on the agenda, without prejudice to unforeseen or urgent matters which may be raised in the course of a meeting.', 'en', 'Commercial Code (Expanded), Article 184', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '185', 'Article 185 Any shareholder, whatever the type of shares he holds, and even though he possess only the provisional voucher, may cast his vote.', 'en', 'Commercial Code (Expanded), Article 185', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '186', 'Article 186 Without prejudice to the double voting power which is the privilege of holders of registered shares for at least two years beforehand, as was explained above, each shareholder has as many votes as the shares he holds or represents, without limitation thereon, unless such limitation is formally provided by the Articles, and on condition it is identical for all shares, irrespective of the category to which they belong.', 'en', 'Commercial Code (Expanded), Article 186', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '187', 'Article 187 (as modified by the Law of 23 November 1948) The shareholder is precluded from voting in his personal name or as proxy, whenever the matter concerns vesting him with a specific advantage or that the meeting is required to take a decision in respect of a dispute between himself and the company.', 'en', 'Commercial Code (Expanded), Article 187', 'Agency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '188', 'Article 188 Debenture-holders'' representatives attending a meeting have no voice in the matter.', 'en', 'Commercial Code (Expanded), Article 188', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '189', 'Article 189 Upon the request of a single shareholder, secret ballot is compulsory in all matters of a personal character, such as the revocation of Directors or the questioning of their responsibility.', 'en', 'Commercial Code (Expanded), Article 189', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '190', 'Article 190 When the attending shareholders do not think themselves sufficiently acquainted with the matters submitted for debate, the meeting shall be deferred to eight days, if one quarter of the members at the meeting so requires.', 'en', 'Commercial Code (Expanded), Article 190', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '191', 'Article 191 Minutes of the sitting must be drafted and signed by the members of the office.', 'en', 'Commercial Code (Expanded), Article 191', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '192', 'Article 192 The decisions taken in accordance with regulations, the conditions of quorum and majority proper to each meeting, without fraud or diversion of power, are binding on all shareholders even absentees and dissidents.', 'en', 'Commercial Code (Expanded), Article 192', 'Fraud', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '194', 'Article 194 (as modified by the Law promulgated by Decree N° 9798 of ___________ (4 May 1968 As regards the verification of contributions in kind, quorum must be calculated exclusively on the shares subscribed or held by shareholders other than those contributing in kind.', 'en', 'Commercial Code (Expanded), Article 194', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '195', 'Article 195 (as modified by the Law of 23 November 1948) In the meetings referred to in articles 193 & 194, resolutions are passed by a two-thirds majority of the shareholders attending or represented.', 'en', 'Commercial Code (Expanded), Article 195', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '196', 'Article 196 Ordinary meetings are convened annually, at the end of the financial year, to decide on the Directors'' accounts and dividend distribution and to appoint new supervisory commissioners, as well as Directors when their term of office has come to expiry. They may convene also in the course of a financial year in unforeseen circumstances, provided that this does not concern a modification of the Articles.', 'en', 'Commercial Code (Expanded), Article 196', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '197', 'Article 197 (as modified by the Law promulgated by Decree N° 9798 of ----------- (4 May 1968 Subject to the nullity of subsequent deliberations, any shareholder, any debenture-holder may have access at the head office to stock-taking, the Balance Sheet, the Profit and Loss Account, the list of shareholders, the report of the Hoard of Directors, the report of the supervisory commissioners, the consolidated Profit and Loss Account and the consolidated Balance Sheet if any exists, and to the report of the supervisory commissioners on these consolidated Account and Balance Sheet, within the-fifteen clear days preceding the annual meeting. Directors are required to complete the list of shareholders as and when stocks to Hearer are deposited. Interested parties may take or have themselves delivered copy of these documents, at their expense, barring the inventory (stock-taking). The company is not authorized to levy on such copies anything more than the charges set down in the price-list established by the Ministry of National Economy.', 'en', 'Commercial Code (Expanded), Article 197', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '198', 'Article 198 The ordinary meeting is to. be composed of a number of shareholders representing one-third at least of the company''s capital. If such quorum is not obtained, a second meeting shall be convened, and it deliberates validly, whatever portion of the capital is represented.', 'en', 'Commercial Code (Expanded), Article 198', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '199', 'Article 199 (as modified by the Law of 23 November 1948) In all cases where no contrary provisions exist, resolutions are passed by absolute majority of the number of shareholders attending or represented.', 'en', 'Commercial Code (Expanded), Article 199', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '201', 'Article 201 (as modified by the Law of 23 November 1948 and by Decree-Law ----------- (N° 54 of 16 June 1977 By adhering to the provisions of article 80 of the following rules, extraordinary meetings shall be empowered to modify the Articles of Associations in all their clauses, on condition that the nationality of the company is not changed, that the shareholders'' commitments are not increased, and that Third Parties rights are not impaired.', 'en', 'Commercial Code (Expanded), Article 201', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '202', 'Article 202 (as modified by the Law of 23 November 1948) '' Regarding the resolutions involving modification of the company''s object or form, quorum must not be less than three-quarters of the company''s capital.', 'en', 'Commercial Code (Expanded), Article 202', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '203', 'Article 203 Concerning all other permissible modifications, quorum shall be two-thirds, half or at least one-third of the capital in the course of three consecutive meetings, convened as constituent meetings.', 'en', 'Commercial Code (Expanded), Article 203', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '204', 'Article 204 (as modified by the Law of 23 November 1948) In extraordinary general meetings, resolutions are passed by a two-thirds majority of the shareholders attending or represented.', 'en', 'Commercial Code (Expanded), Article 204', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '205', 'Article 205 (as modified by the Law promulgated by Decree N° 9798 of ___ __-_____ (4 May 1968 Increase of the company capital may be effected only after the total initial capital has been paid up.', 'en', 'Commercial Code (Expanded), Article 205', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '206', 'Article 206 (as modified by the Law promulgated by Decree NO 9798 of --------- (4 May 1968 The legal rules governing the formation of joint-stock companies must be observed in what regards the issue of new shares, subject to the same sanctions for capital increase, of fine and liability chargeable on the officiating Directors, on shareholders whose contributions have not been approved in accordance with regulations, on supervisory commissioners and on experts.', 'en', 'Commercial Code (Expanded), Article 206', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '207', 'Article 207 If new shares are subscribed by others than the old shareholders, in spite of the latter''s option, and that the company possesses a reserve capital, such shares shall be issued at a price higher than their nominal value, with excess corresponding to participation to reserves.', 'en', 'Commercial Code (Expanded), Article 207', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '208', 'Article 208 Reduction of the company''s capital may not be voted, except without prejudice to Third Parties'' rights. In consequence, deliberation of the general meeting deciding thereon shall not be executory except after its publication in the Official Gazette and on condition that, within three months, creditors have not opposed it. Opposition shall suspend the reduction of capital, until the Court has decided whether or not the reduction impairs Third Parties'' rights.', 'en', 'Commercial Code (Expanded), Article 208', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '209', 'Article 209 Any irregular capital reduction, effected via the purchase by the company of its own shares, whether this is paid for out of the company''s capital or the legal reserve, commits the Directors'' liability.', 'en', 'Commercial Code (Expanded), Article 209', 'Sale of goods', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '210', 'Article 210 The merger of several companies shall be decided by deliberation in general extraordinary meetings of each of these companies.', 'en', 'Commercial Code (Expanded), Article 210', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '211', 'Article 211 In the event of the formation of a new company through the amalgamation of the older ones, the legal rules of formation must be observed. Publicity formalities shall be met, in as such as the advance dissolution of the various companies is concerned as it is in respect of the creation of the new company.', 'en', 'Commercial Code (Expanded), Article 211', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '212', 'Article 212 In case of a take-over of one company by another, the annexed company shall publish its advance dissolution; the annexing company shall submit to the rules of fundamentals and form governing capital increase.', 'en', 'Commercial Code (Expanded), Article 212', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '213', 'Article 213 Provisions relating to Third Parties'' rights, in the event of capital reduction, are applicable on all deliberations deciding a merger or a take-over bid.', 'en', 'Commercial Code (Expanded), Article 213', NULL, 'Commercial Law');
